window.NAM_METHOD_RECORDS = [{"id":"TM2012-06","shortName":"Bhas 42 CTA","title":"Cell Transformation Assay Based on the Bhas 42 Cell Line","organisation":"EURL ECVAM - European Union","description":"The in vitro CTA using Bhas 42 cell line is aimed at detecting the carcinogenic potential of chemicals. The assay is based on the change of the phenotypic features of cells undergoing the first steps of the conversion from normal cells to neoplastic-like cell foci with oncogenic properties. Carcinogenesis is a complex multistage process by which normal cells are transformed into cancer cells characterised by an accumulation of changes at the cellular, genetic and epigenetic level. In vitro CTAs such as the Bhas 42 CTA have been shown to recapitulate a multistage process that closely models some stages of in vivo carcinogenesis. Cell transformation in all the systems studied to-date involves changes at each stage in order for progression to the next stage in the transformation process to occur. A minimum of four phenotypic stages appears to be involved in cell transformation. These include (from primary to fully malignant cells): a block in cellular differentiation, acquisition of immortality, characterised by unlimited lifespan, an aneuploidy karyotype and a decreased genetic stability; acquisition of tumorigenicity, which is closely associated with the in vitro phenotypes of foci formation, anchorage independent growth in semi-solid agar and autocrine growth factor production; full malignancy, including metastasis when the cells are injected into a suitable host, supporting the biological relevance of in vitro transformation to in vivo carcinogenicity. The Bhas 42 cell line was developed from BALB/c 3T3 cells through transfection with a Harvey rat sarcoma viral mutated oncogene homolog (v-Ha-ras). Since Ha-ras is strongly related to multi-step carcinogenesis, Bhas 42 cells are more predisposed to transformation than the original cells BALB/c 3T3. The assay was first developed by Ohmori et al. (2004) to identify tumour promoters. Subsequently, Asada et al. (2005) modified the Bhas 42 CTA protocol such that it was capable of detecting tumour initiating activity, as well as tumour promoting activity of chemicals. The current protocols consist of two assay components, the initiation assay and the promotion assay to detect the tumour-initiating and tumour-promoting activity of chemicals, respectively. Two variants of the protocol have been validated, a 6-well method and a 96-well method.","stepStage":"Regulatory acceptance/Standards > Drafting of new regulatory standard/guideline","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Drafting of new regulatory standard/guideline","topic":"Carcinogenicity","yearReceived":"2012","generalComments":"The validation of this assay was coordinated by the Japanese Center for the Validation of Alternative Methods (JaCVAM), while the peer review was conducted by ESAC.","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=156","lastUpdate":"Monday, August 10, 2026 - 09:32","lastUpdateDate":"2026-08-10","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_DRAFT","applicationDomain":"Mixed/general toxicology","endpoint":"Carcinogenicity","methodology":"In vitro","specificMethodologies":"HTS; Cell transformation assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_DRAFT","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Reduction","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2020-01","shortName":"RS Comet assay","title":"3D Reconstructed Human Skin Comet assay","organisation":"EURL ECVAM - European Union","description":"The RS Comet Assay is an in vitro genotoxicity assay, presented as an adaptation of the known alkaline comet assay and designed in a three-dimensional reconstructed human skin (RHS) model. The method uses specifically the Phenion® Full-Thickness Skin Model which is composed of two tissues from primary and p53 competent cells of human origin, primary keratinocytes and fibroblasts. As such, the method is aimed to predict the potential of substances that are primarily associated with dermal exposure to cause DNA damage.","stepStage":"Regulatory acceptance/Standards > Drafting of new regulatory standard/guideline","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Drafting of new regulatory standard/guideline","topic":"Genotoxicity/Mutagenicity","yearReceived":"2020","generalComments":"Under evaluation","protocolSop":"","lastUpdate":"Wednesday, August 5, 2026 - 12:49","lastUpdateDate":"2026-08-05","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_DRAFT","applicationDomain":"Mixed/general toxicology","endpoint":"Genotoxicity","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Biomarker/DNA damage assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_DRAFT","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Applicability domain","bottleneckCount":"3","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2020-04","shortName":"RSMN","title":"3D Reconstructed Human Skin Micronucleus assay (RSMN)","organisation":"EURL ECVAM - European Union","description":"The RS MN Assay is an in vitro genotoxicity assay, which transfers the known micronucleus test in a three-dimensional reconstructed human skin (3D RHS) model. The assay addresses the potential of test items to cause genotoxicity in the form of chromosomal damage (clastogenicity and aneugenicity). The method uses the EpiDerm™ Skin Model (MatTek, Ashland, USA) which is cultured from normal human epidermal keratinocytes derived from neo-natal foreskin tissue on specifically prepared tissue culture inserts. As such, the method is aimed to predict the potential of substances that are primarily associated with dermal exposure to cause DNA damage.","stepStage":"Regulatory acceptance/Standards > Drafting of new regulatory standard/guideline","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Drafting of new regulatory standard/guideline","topic":"Genotoxicity/Mutagenicity","yearReceived":"2020","generalComments":"Under evaluation","protocolSop":"","lastUpdate":"Wednesday, August 5, 2026 - 12:48","lastUpdateDate":"2026-08-05","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_DRAFT","applicationDomain":"Mixed/general toxicology","endpoint":"Genotoxicity","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Micronucleus/genotoxicity assay; Biomarker/DNA damage assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_DRAFT","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Applicability domain; Regulatory relevance / integration","bottleneckCount":"5","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2009-14","shortName":"HepaRG™","title":"Cytochrome P450 (CYP) enzyme induction in vitro method using cryopreserved differentiated human HepaRG™ cells","organisation":"EURL ECVAM - European Union","description":"The human cytochrome P450 (CYP) enzyme induction method assesses the potential of test chemicals to induce the activity of three CYP enzymes (CYP1A2, CYP2B6 and CYP3A sub-family) in cryopreserved differentiated human HepaRG™ cells. At the molecular level, CYP enzyme induction is a process controlled by a set of nuclear receptors associated with downstream signal transduction pathways. The human HepaRG™ cell model is a suitable candidate human hepatic metabolic competent test system. Experimentally, at the end of cell exposure to the test chemical, a cocktail of three specific CYP enzymatic substrate probes is applied to the cells and CYP enzyme induction is assessed through the measurement of of the specific metabolites formation by CYP1A2, 2B6 and 3A sub-family by analytical liquid chromatography/mass spectrometry (LC/MS) technique. The CYP enzyme induction in vitro methods (see also TM2009-13) are reliable and relevant methods for the generation of human metabolism data in animal-free testing strategies assessing adverse health effects of xenobiotics.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Toxicokinetics","yearReceived":"2009","generalComments":"","protocolSop":"Protocol for the CYP induction test method, OECD TG 445A","lastUpdate":"Thursday, July 2, 2026 - 15:50","lastUpdateDate":"2026-07-02","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Pharmaceutical","endpoint":"Toxicokinetics","methodology":"In vitro","specificMethodologies":"Analytical chemistry readout; Enzyme/biochemical activity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package; Predictive performance; Applicability domain; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"5","animalUseImpact":"Reduction","applicationDomainExpert":"Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2022-03","shortName":"α-Sens®","title":"In Vitro Skin Sensitisation: The FBS free ARE-Nrf2 Luciferase α-Sens® Test Method","organisation":"JaCVAM - Japan","description":"The α-Sens® test method was developed to achieve a serum-free and simple operation procedure with high accuracy for the prediction of skin sensitizers. The α-Sens® employs a dual luciferase assay system to detect both antioxidant response element (ARE)-mediated transcriptional activity and cell viability to evaluate the KE-2 response, the keratinocyte activation of the AOP in the skin sensitization process. The α-Sens® cell line was originally developed as “α-Sens (without ®)”, the multi-clone cell system of PHK 16-0b cell line (immortalized human keratinocyte by HPV16 virus genome) stably transfected with two reporter constructs, Antioxidant response element (ARE) inducible Firefly luciferase gene for ARE response and Thymidine Kinase (TK) promoter-driven Renilla luciferase gene for cell viability measurement(Maeda et al., 2020). Therefore, the α-Sens can measure ARE-mediated activity and cell viability simultaneously with the same exposure sample. α-Sens was further improved by modifying the reporter gene construct and was established as a single clone cell system, “α-Sens® (with ®)","stepStage":"Regulatory acceptance/Standards > Revision of existing regulatory standard/guideline","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Revision of existing regulatory standard/guideline","topic":"Skin sensitisation","yearReceived":"2022","generalComments":"","protocolSop":"Protocol for α-Sens®","lastUpdate":"Friday, June 19, 2026 - 07:36","lastUpdateDate":"2026-06-19","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_OTHERSTAGE","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Reporter gene assay; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Missing","verificationNote":"External status check: α-Sens® was incorporated into the OECD TG 442D revision published 2 July 2026. The current TSAR snapshot may still reflect the preceding guideline-revision stage; update through the source-refresh workflow rather than manual expert override.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain; Mechanistic relevance; Regulatory relevance / integration","bottleneckCount":"3","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2026-01","shortName":"LS Bioassay","title":"Lung Surfactant Bioassay","organisation":"EURL ECVAM - European Union","description":"The Lung Surfactant (LS) Bioassay is a cell-free method designed to assess acute lung toxicity shortly after inhalation, focusing on immediate alveolar effects. It evaluates LS function, which is crucial for healthy lungs, by monitoring surface tension and rheological changes in a 'breathing' drop of pig-derived LS exposed to test compounds. Increased surface tension, as measured with a Constrained Drop Surfactometer, and altered surface rheology, as calculated with a mathematical model, are considered inhibitory to LS function, potentially leading to alveolar collapse and breathing difficulties. Inhibition of LS function is identified as the Molecular Initiating Event in Adverse Outcome Pathway 302, predicting acute lung effects.According to the test submitter, the LS Bioassay is intended for non-regulatory prioritisation and chemical screening in research and development. While it assesses one of many inhalation effects, it might complement other lung-relevant in vitro methods and potentially replace acute inhalation toxicity tests following OECD Test Guidelines (TGs) that rely on systemic effects. Immediate lung effects can be noted in these TG studies by observing respiration changes. Coupling this method with OECD TGs can offer insights into the mechanism of toxicity of test compounds.","stepStage":"Submission > Assessment finalised","workflowStep":"Submission","workflowStage":"Assessment finalised","topic":"Acute toxicity, Human Health Effects","yearReceived":"2026","generalComments":"","protocolSop":"","lastUpdate":"Tuesday, May 19, 2026 - 14:45","lastUpdateDate":"2026-05-19","stage":"Test Submission","status":"Finalised","code":"SUB_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Acute toxicity; Human health — unspecified","methodology":"In chemico; In silico; Mixed","specificMethodologies":"","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"The current specific-methodology vocabulary has no suitable label for constrained-drop surfactometry/biophysical surface-tension testing. AI/ML was rejected because the mathematical rheology model is not described as an AI or machine-learning method.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_FINAL","bottlenecks":"Predictive performance; Applicability domain; Regulatory relevance / integration","bottleneckCount":"3","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2025-02","shortName":"InFiniteLungDT","title":"Quantitative prediction of inflammation from acute to chronic condition associated with inhalation and delivered ahead of time by lung animal-free in-vitro-learned digital twin (InFiniteLungDT)","organisation":"EURL ECVAM - European Union","description":"InFiniteLungDT is a quantitative prediction tool for inflammation transitioning from acute to chronic conditions associated with inhalation. It is an animal-free, in-vitro-learned digital twin designed to predict long-term, time-evolved, dose-dependent inflammation triggered by inhaled poorly-water-soluble substances. InFiniteLungDT works by monitoring subcellular dynamics in vitro using a lung epithelium cellular cluster. Live-cell microscopy captures time-lapse images, which are then quantified into 17 time-dependent observables. A patented algorithm translates these into interaction couplings, defining the material's Mode-of-Action (MoA). This MoA is then used for in silico time-propagation to predict dose-dependent endpoints (neutrophil influx) and LOAELs for up to two years, extending beyond the in vitro observation timescale. Two cell lines are used, the murine epithelial lung tissue cell line (LA-4) and the murine alveolar lung macrophages (MH-S).The intended purpose of the proposed method is to offer a resource-efficient alternative to animal testing, for regulatory applications (e.g. OECD TGs 403, 412, 413, and 452), delivering LOAELs for acute, sub-acute, sub-chronic, and chronic exposure scenarios. Additionally, it might support material developers in sectors such as advanced materials, nano and micromaterials, construction materials, and more, by facilitating early-phase pre-screening. The method is high-throughput compatible and can be scaled up for use by Contract Research Organisations (CROs).","stepStage":"Submission > Assessment finalised","workflowStep":"Submission","workflowStage":"Assessment finalised","topic":"Human Health Effects","yearReceived":"2025","generalComments":"","protocolSop":"","lastUpdate":"Tuesday, May 19, 2026 - 07:59","lastUpdateDate":"2026-05-19","stage":"Test Submission","status":"Finalised","code":"SUB_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Acute toxicity; Repeated dose toxicity; Chronic toxicity","methodology":"In vitro; In silico; Mixed","specificMethodologies":"HTS; High-content imaging; AI/ML","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"InFiniteLungDT combines live-cell microscopy of murine LA-4/MH-S co-cultures (17 observables) with an in silico digital twin predicting chronic inhalation LOAELs. EURL ECVAM stopped presubmission in May 2026 (SUB_STOP) due to PARERE concerns on mechanistic and regulatory relevance. Qualifies as a Direct Case Study (code 1) based on external progression to an independent multi-center pre-validation trial (Urbančič et al., 2026 bioRxiv DOI 10.64898/2026.05.12.723437; VAL_INIT). AI/ML methodology added.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_FINAL","bottlenecks":"Validation readiness / evidence package; Mechanistic relevance; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"4","animalUseImpact":"Replacement","applicationDomainExpert":"Industrial chemicals; Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2019-06","shortName":"TYRO-IOD","title":"Thyroid method 2c: Tyrosine iodination using liquid chromatography","organisation":"EURL ECVAM - European Union","description":"This method provides information on the Thyroid Peroxidase (TPO)-mediated iodination of tyrosine. The conversion from L-tyrosine to Iodotyrosine by TPO that is present in prepared extracts from FTC-238 cells transfected with human recombinant TPO, can be measured with LC-MS/MS. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Ongoing","workflowStep":"Validation","workflowStage":"Ongoing","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Tuesday, April 7, 2026 - 10:06","lastUpdateDate":"2026-04-07","stage":"Validation","status":"Ongoing","code":"VAL_ONGO","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Analytical chemistry readout; Enzyme/biochemical activity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"The positive reproducibility/transferability signal refers specifically to the unresolved inter-laboratory transferability requirement; it should not be interpreted as evidence of poor within-laboratory reproducibility.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_ONGO","bottlenecks":"Reproducibility / transferability","bottleneckCount":"1","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2017-02","shortName":"TR MARCoNI","title":"Thyroid receptor microarray assay for real-time Nuclear Receptor-coregulator interaction","organisation":"EURL ECVAM - European Union","description":"Thyroid hormone signalling plays a key role in many physiological processes, including brain development and metabolism. The thyroid hormone elicits its action via the two types of thyroid hormone receptor (TR), TRα and TRβ. This method characterises TRα-Ligand Binding Domain (LBD) interaction with a range of coregulators, by assessing binding affinity of a defined set of immobilised nuclear receptor coactivator and corepressor peptides. The binding affinity is assessed via interaction with the LXXLL and LXXXIXXXL motifs for coactivators and corepressors respectively. The binding affinity is enhanced by ligand induced activation of the receptor, while ligand-independent binding reduces the binding affinity. The amount of ligand-modulated interaction of coregulators with TRα-LBD is assessed via image analysis, by adding fluorescent antibodies against TRα-LBD. The obtained binding profiles can be used to identify compounds that can activate TRα, thereby differentiating between agonistic and antagonistic action.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Endocrine disruption","yearReceived":"2017","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 13:20","lastUpdateDate":"2026-04-02","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In chemico","specificMethodologies":"Binding/interaction assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Missing","verificationNote":"Expert methodology correction: TR MARCoNI is coded as In chemico because it is a non-cellular recombinant receptor–coregulator peptide binding assay. 'Microarray' does not indicate omics here, and fluorescent image analysis/antibody detection are readout components rather than high-content imaging or a primary immunoassay.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2016-01","shortName":"EDITOX","title":"Predictive testing for adverse psychiatric side effects","organisation":"EURL ECVAM - European Union","description":"The EDITOX test method is an in vitro cell assay designed to predict the risk of depression and/or suicidal adverse effects of a given drug in a patient. This test method quantitatively analyses variations of the relative proportion of the 32 mRNA editing isoforms of the serotonin receptor (5-HT2cR) (biomarkers) using a next generation sequencing (NGS) approach in SH-SY5Y cell line (human neuroblastoma). It is confirmed in the literature that anomalies of serotonin biology in brain appear to be a characteristic trait underlying depression and/or suicidal behavior (Dracheva et al., 2008). By analysing postmortem brain tissue of suicide victims, Alcediag and others have observed distinct epigenetic alterations of the RNA editing profile of the 5-HT2cR pre-mRNA, known to greatly impair its pharmacological properties (Weissmann et al. 2016; Dracheva et al., 2008; Burns et al. 1997), including significant decrease in its response to serotonin. Apparently, similar RNA editing profile of the 5-HT2cR is reproduced by an exposure to human IFNa (positive control) using SH-SY5Y cell line. IFNa is known to induce, in some patients treated for chronic type C hepatitis, full blown depression and suicidal behaviour (Cavarec et al. 2013). Based on this observation, the Submitter has developed a proprietary algorithm to assess whether the editing profile of tested drugs is close to the one induced by human IFNa, allowing categorisation of tested compounds into \"hIFNa-like\" vs \"non-hIFNa-like\" profiles. Furthermore, EDITOX test method is proposed to be used for classification of drugs into the following categories of “High risk”, “Low risk” or “Moderate risk” to induce adverse side effects, such as depression and/or suicide in pre-clinical drug development phase, and also in regulatory toxicological safety assessment.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Neurotoxicity, Human health","yearReceived":"2016","generalComments":"On hold-pending further information","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 13:12","lastUpdateDate":"2026-04-02","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Pharmaceutical; Industrial chemicals","endpoint":"Neurotoxicity","methodology":"In vitro; In silico; Mixed","specificMethodologies":"Omics","review":"Expert-reviewed","threeR":"Reduction","literature":"Missing","verificationNote":"Outside-TSAR progression verified: after the TSAR submission was stopped, EDITOX continued in scientific and industrial development, including use of EDITOX assay data within the EU/IMI NeuroDeRisk programme and continued preclinical commercial application. This supports case_study_method = 1. No evidence of formal OECD/EMA/FDA regulatory adoption of EDITOX was identified. AI/ML was removed from the detailed methodology because a proprietary algorithm is described, but no explicit machine-learning/AI method was identified.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Applicability domain; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2016-03","shortName":"ToxTracker","title":"ToxTracker Assay","organisation":"EURL ECVAM - European Union","description":"ToxTracker is an in vitro genotoxicity assay that also includes a number of non-genotoxic end points that have been associated with increased cancer hazard. ToxTracker detects induction of DNA damage, oxidative stress and protein unfolding, thereby providing insight into the mechanisms of (geno)toxicity, allowing accurate genotoxicity assessment and reducing the frequency of misleading positive in vitro test results that would trigger in vivo follow up testing.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Genotoxicity/Mutagenicity","yearReceived":"2016","generalComments":"Invitation to send full test submission","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 12:56","lastUpdateDate":"2026-04-02","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Genotoxicity","methodology":"In vitro","specificMethodologies":"Reporter gene assay; Cytotoxicity/cell viability assay; Immunoassay/flow cytometry; Biomarker/DNA damage assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Missing","verificationNote":"Outside-TSAR progression verified: ToxTracker continued through a parallel OECD route after the TSAR submission stopped, progressed through international multi-laboratory validation and independent peer review, and was adopted/published as OECD TG 446A on 2 July 2026. This supports case_study_method = 1 and External_evidence_step_stage = REG_ADOPT. TSAR source-copy lifecycle fields remain unchanged.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Pharmaceutical / human medicines; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2019-18","shortName":"PMOD-hNPC","title":"Thyroid method 8b: Proliferation, migration and oligodendrocyte maturation (including myelin formation) in mixed neuronal/glial culture (neurospheres) derived from human induced Pluripotent Stem Cells (hiPSC)","organisation":"EURL ECVAM - European Union","description":"Thyroid hormone disruption can interfere with proliferation, migration and differentiation of oligodendrocyte which may lead to neurodevelopmental impairments. The method encompasses evaluation of these biological processes using mixed neuronal/glial culture derived from human induced Pluripotent Stem Cells (hiPSC) cultured as free-floating neurospheres. Cell viability, proliferation, migration and differentiation measured by expression of myelin specific proteins are assessed following a 1-2-week treatment with test items. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 08:52","lastUpdateDate":"2026-04-02","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay; Immunoassay/flow cytometry","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Mechanistic interpretation: PMOD-hNPC is a downstream human neurodevelopmental assay rather than a direct thyroid-hormone assay. It measures oligodendrocyte maturation/myelin-related outcomes and associated developmental processes that are sensitive to thyroid-hormone signalling, but an effect on myelination is not thyroid-specific and should be integrated with upstream thyroid-mechanistic evidence. Outside-TSAR progression was verified through later EURL ECVAM/JRC validation-oriented work with commercial hiPSC-derived BrainSpheres. This supports case_study_method = 1 and External_evidence_step_stage = VAL_ONGO; TSAR source-copy lifecycle fields remain unchanged.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_ONGO","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Programme prioritisation / route selection; Access / implementation; Standardisation / regulatory adoption","bottleneckCount":"6","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2019-16","shortName":"ZETA","title":"Thyroid method 7a: Measurement of intrafollicular thyroxine (T4) using zebrafish eleutheroembryos","organisation":"EURL ECVAM - European Union","description":"The Zebrafish Eleutheroembryo Thyroid Assay (ZETA) is used to detect direct thyroid gland function disruptors in the thyroid of 120 hours post- fertilisation (hpf) zebrafish embryos after their exposure to test items for 66 hours. The intrafollicular T4-content (IT4C) is determined by immunofluorescence signal. IT4C is a physiologically relevant integrative endpoint, as any potential disrupting mechanism of the thyroid gland function would result in increase or decrease of T4 production. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 08:54","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Finalised","code":"VAL_FINAL","applicationDomain":"Environmental","endpoint":"Endocrine disruption","methodology":"In vivo","specificMethodologies":"Immunoassay/flow cytometry; Embryo/developmental model","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert interpretation: ZETA is an in vivo assay because it exposes an intact living zebrafish developmental stage (eleutheroembryos), even though this life stage may fall outside protected-animal legislation. The assay measures intrafollicular T4 by antibody-based immunofluorescence and therefore provides an integrated thyroid-gland functional endpoint rather than identifying one specific molecular mechanism. Conventional fluorescence microscopy is not coded as high-content imaging. Authoritative external evidence supports External_evidence_step_stage = VAL_PEER_FINAL; no later stage for the exact ZETA method was identified.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_FINAL","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Applicability domain; Standardisation / regulatory adoption","bottleneckCount":"5","animalUseImpact":"Reduction","applicationDomainExpert":"Environmental; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2019-03","shortName":"TSH-CHOK1","title":"Thyroid method 1b: Thyrotropin-stimulating hormone (TSH) receptor activation based on cAMP measurement","organisation":"EURL ECVAM - European Union","description":"This method measures the production of cAMP after activation of the Thyroid Stimulating Hormone Receptor (TSHR). The production of intracellular adenosine 3’,5’ cyclic monophosphate (cAMP) is important for thyroid hormone physiology. cAMP is a critical component of a signal transduction pathway linking TSHR and its ligand TSH to the activation of adenylate cyclase and therefore cAMP production. The method measures the intracellular cAMP concentration in Chinese hamster ovary cells (CHO-K1) transfected with the gene of the human TSHR, using an Enzyme Linked Immuno Sorbent Assay. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 08:56","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Finalised","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Immunoassay/flow cytometry; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert interpretation: TSH-CHOK1 is an in vitro functional TSH-receptor signalling assay using CHO-K1 cells expressing human TSHR. The primary endpoint is cAMP measured by an immunoassay/ELISA-type readout, with cell viability measurements used to distinguish receptor-signalling effects from general cytotoxicity. The assay therefore measures a specific upstream thyroid-signalling event rather than thyroid-hormone production itself. Authoritative external evidence supports External_evidence_step_stage = VAL_PEER_FINAL; no later lifecycle stage for the exact assay was identified.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_FINAL","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Applicability domain; Standardisation / regulatory adoption","bottleneckCount":"5","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2019-10","shortName":"DIO1-SKR","title":"Thyroid method 4a: Deiodinase 1 activity based on Sandell-Kolthoff reaction","organisation":"EURL ECVAM - European Union","description":"This method assesses the inhibition of thyroid hormones deiodination, the major pathway regulating thyroid hormones bioavailability in mammalian tissues. This method measures the activity of deiodinase enzyme D1 in human liver microsomes by measurement of free iodine with a spectrophotometric absorbance readout following the Sandell-Kolthoff reaction, during which the yellow cerium(IV) is reduced to the colourless cerium (III). This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:03","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Ongoing","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"HTS; Analytical chemistry readout; Enzyme/biochemical activity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Core methodology retained as In vitro to align with conventional toxicology terminology for the human-liver-microsome DIO1 assay. The test system is donor-derived human liver microsomal material, but the literature consistently describes the method as an in vitro microsomal assay. Detailed methodology corrected to HTS; Analytical chemistry readout; Enzyme/biochemical activity assay. Barrier/permeability and phototoxicity/photoreactivity labels were removed. External progression is supported beyond the TSAR VAL_FINAL snapshot through PEPPER transfer validation and formal OECD Test Guidelines Programme Project 4.179, supporting case_study_method = 1 and External_evidence_step_stage = REG_DRAFT.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_DRAFT","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Applicability domain; Standardisation / regulatory adoption","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2019-11","shortName":"GLUC-LCMS","title":"Thyroid method 4b: Inhibition of thyroid hormones (THs) glucuronidation using liquid chromatography/mass spectrometry (LC/MS)","organisation":"EURL ECVAM - European Union","description":"This method assesses the potential of test items to inhibit the metabolism and excretion of thyroid hormones. Glucuronidation is one of the main pathways in the metabolism of thyroid hormones (T3 and T4). The method consists in the incubation of either T4 or T3 with human liver microsomes that contain UDP-glucuronosyltransferases (UGT), the enzyme involved in the glucuronidation. Following separation and purification the mixture is analysed by liquid chromatography/mass spectrometry (LC/MS). Acyl- and Phenolic- Glucuronides are separated and peaks identities confirmed. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:04","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Finalised","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Analytical chemistry readout; Enzyme/biochemical activity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert interpretation: GLUC-LCMS is retained as In vitro for consistency with conventional toxicology terminology and with DIO1-SKR. It uses pooled human liver microsomes containing UGT enzymes and quantifies T3/T4 glucuronide formation by LC-MS/MS. The assay measures inhibition of thyroid-hormone glucuronidation, but this direction is not necessarily the predominant adverse in-vivo perturbation, because increased glucuronidation can drive increased thyroid-hormone clearance. No evidence of progression beyond the completed validation/peer-assessment stage was identified, so case_study_method = 0 and External_evidence_step_stage = VAL_FINAL.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_FINAL","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Mechanistic relevance; Programme prioritisation / route selection; Standardisation / regulatory adoption","bottleneckCount":"6","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2019-19","shortName":"VAAN-hadum","title":"Thyroid method 8c: In vitro human adipose stromal cell—human umbilical vein endothelial cell (hASC-HUVEC) vasculogenesis/angiogenesis method","organisation":"EURL ECVAM - European Union","description":"Thyroid hormone disruption can interfere with vasculogenesis and angiogenesis and can be assessed using human primary adipose stromal cells and human primary umbilical vein endothelial cells coculture test without any artificial matrixes. In the method the effect of test item on the formation of vasculature is measured six days after the exposure by quantifying the formed tubules using image analysis. Cell viability test (WST-1) is used to measure general cytotoxicity to clarify if the inhibitory mechanism is related to cytotoxicity. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Stopped","workflowStep":"Validation","workflowStage":"Stopped","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:05","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Discontinued","code":"VAL_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"High-content imaging; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert interpretation: VAAN-hadum is a downstream human in vitro vasculogenesis/angiogenesis assay. Reduced or increased vascular-network formation is not thyroid-specific; the planned Part 2 study was intended to test that mechanistic relationship but was never performed. Part 1 did not document a reproducibility or performance failure; the thyroid-validation route stopped because programme capacity/human-resource constraints prevented continuation. Outside-TSAR development of the same hASC-HUVEC VAM platform in a different application domain (non-genotoxic carcinogenicity) supports case_study_method = 1, but this does not constitute formal lifecycle progression of the exact thyroid assay. Therefore External_evidence_step_stage = VAL_STOP, while the raw TSAR NEW_STEP_STAGE remains unchanged.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_STOP","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2019-17","shortName":"T-SCREEN","title":"Thyroid method 8a: Measurement of proliferation of rat pituitary-derived cell line GH3","organisation":"EURL ECVAM - European Union","description":"This method is based on thyroid hormone (TH) dependent cell proliferation of a rat pituitary tumour cell line (GH3) in serum-free medium. It can be used to study interference of test items with TH at the cellular level, thus bridging the gap between limitations of assays using either isolated molecules (enzymes, transport proteins) or complex in vivo experiments with all the complex feedback mechanisms present. GH3 cell growth, which is measured with the colorimetric AlamarBlue™ assay is increased in the presence of TH agonists, and decreased in the presence of TH antagonists. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:06","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Finalised","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"HTS; Metabolic activity sensor assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert interpretation: T-SCREEN is an in vitro GH3-cell proliferation assay used to detect thyroid-receptor modulation. The validated agonist mode is substantially better supported than the antagonist mode. Because the primary endpoint is proliferation rather than a thyroid-specific molecular event, a positive response is not sufficient by itself to establish thyroid-mediated activity and should be interpreted with complementary mechanistic evidence. Detailed methodology corrected to HTS; Metabolic activity sensor assay; binding/interaction and barrier/permeability labels were removed. Authoritative OECD expert assessment supports External_evidence_step_stage = VAL_PEER_FINAL. No separate alternative progression route was identified, so case_study_method = 0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_PEER_FINAL","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Mechanistic relevance; Regulatory relevance / integration; Standardisation / regulatory adoption","bottleneckCount":"6","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2019-15","shortName":"TRβ-CALUX","title":"Thyroid method 6b: CALUX human thyroid hormone receptor beta (TRβ) reporter gene transactivation measuring agonist and antagonist activities","organisation":"EURL ECVAM - European Union","description":"This method assesses the activation of thyroid hormone receptor beta (TRβ). It is making use of proprietary TRβ CALUX® cells which originated from human osteoblastic osteosarcoma U2OS line. These cells express a functioning human thyroid (TRβ) receptor coupled with a luciferase reporter gene. Test items with both an agonist or antagonist effect on TR activity can be detected and an increase or decrease of thyroid hormone signalling, results in corresponding changes in the expression of luciferase activity in TRβ CALUX® cells that can be measured with a luminometer. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Friday, June 5, 2026 - 11:18","lastUpdateDate":"2026-06-05","stage":"Validation","status":"Finalised","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert interpretation: TRβ-CALUX is a direct human TRβ reporter-gene assay and is therefore mechanistically more specific than downstream proliferation-based thyroid assays. Agonist performance is better supported than antagonist performance. The primary detailed methodology remains Reporter gene assay; cytotoxicity measurements are treated as supporting interpretation rather than a separate primary methodology. OECD expert assessment supports External_evidence_step_stage = VAL_PEER_FINAL. No distinct alternative regulatory progression route for the exact TM2019-15 method was identified, so case_study_method = 0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_PEER_FINAL","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Applicability domain; Programme prioritisation / route selection; Standardisation / regulatory adoption","bottleneckCount":"6","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2019-14","shortName":"TRαTRβ-REP","title":"Thyroid method 6a: Human thyroid hormone receptor alpha (TRα) and Human thyroid hormone receptor beta (TRβ) reporter gene transactivation measuring agonist activities","organisation":"EURL ECVAM - European Union","description":"This method assesses the activation of thyroid hormone receptor alpha (TRα) and beta (TRβ). It is making use of proprietary human HEK293 cells engineered to provide constitutive, high-level expression of the human TRα and TRβ coupled with a highly responsive luciferase reporter gene (commercially available kit from INDIGO Biosciences). Quantification of changes in luciferase expression in the treated vs. untreated reporter cells by detection of luminescence provides a sensitive measure of changes in TR activation without collateral induction/suppression of genes that are otherwise regulated by these transcription factors. This method allows to measure agonist TR functional activity. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:08","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Finalised","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert interpretation: TRαTRβ-REP is an in vitro human thyroid-receptor reporter-gene assay measuring agonist activity at TRα and TRβ. The assay has direct mechanistic relevance and OECD expert assessment considered it valid for detection of TRα/TRβ agonists. Remaining evidence needs relate mainly to between-laboratory reproducibility, possible extension to antagonist activity and whether further standardisation provides sufficient regulatory added value relative to alternative approaches. Detailed methodology remains Reporter gene assay. External_evidence_step_stage = VAL_PEER_FINAL; no distinct alternative progression route for the exact method was identified, so case_study_method = 0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_PEER_FINAL","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Programme prioritisation / route selection; Standardisation / regulatory adoption","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2019-13","shortName":"MCT8-TR","title":"Thyroid method 5a: Inhibition of monocarboxylate transporter 8 (MCT8) based on Sandell-Kolthoff reaction","organisation":"EURL ECVAM - European Union","description":"This method measures the active transport of thyroid hormone T3 across the plasma membrane by monocarboxylate transporter 8 (MCT8). T3 uptake, by Madin Darby Canine Kidney (MDCK) cells stably transfected with human MCT8, is measured with a specrophotometric absorbance readout following the Sandell-Kolthoff (SK) reaction, during which the yellow cerium(IV) is reduced to the colourless cerium (III). This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Stopped","workflowStep":"Validation","workflowStage":"Stopped","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:09","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Discontinued","code":"VAL_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"HTS; Analytical chemistry readout; Barrier/permeability/transport assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert interpretation: MCT8-TR is an in vitro mechanistic thyroid-hormone transport assay using MDCK1 cells stably expressing human MCT8, with T3 uptake quantified through a Sandell-Kolthoff-based analytical readout. Detailed methodology corrected to HTS; Analytical chemistry readout; Barrier/permeability/transport assay. Reporter-gene, cytotoxicity/cell-viability, enzyme/biochemical and phototoxicity labels were removed. The original TSAR validation route stalled because core validation documentation was not provided rather than because a scientific performance failure was demonstrated. Later method development and the 2026 BfR ThyroTransVal formal validation project support case_study_method = 1 and External_evidence_step_stage = VAL_ONGO.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_STOP","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection; Access / implementation; Standardisation / regulatory adoption","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2019-12","shortName":"THSUL-LC","title":"Thyroid method 4c: Inhibition of THs sulfation using liquid chromatography","organisation":"EURL ECVAM - European Union","description":"This method assesses the potential of test items to inhibit the metabolism and excretion of thyroid hormones (THs,T3 and T4). Sulfation appears to be a primary step leading to the irreversible inactivation of TH and it is carried out by sulfotransferases (SULT); it increases the water solubility of TH, facilitating the excretion of sulfated TH via bile and urine. In humans, as sulfated TH can be hydrolysed to their precursor by the sulfatases present in tissues and gut microbiota, they are important as a reservoir for biological active iodothyronines. This assay measures the inhibition of THs by liquid chromatography/mass spectrometry (LC/MS). The potential inhibition of the compounds towards sulfation of T3 and T4 is determined by measuring and comparing the thyroid hormones sulfate conjugates formation, after incubation with and without the test chemicals. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Stopped","workflowStep":"Validation","workflowStage":"Stopped","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:09","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Discontinued","code":"VAL_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Analytical chemistry readout; Enzyme/biochemical activity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert interpretation: THSUL-LC is an in vitro biochemical/analytical assay concept intended to quantify inhibition of thyroid-hormone sulfation by measuring T3/T4 sulfate conjugate formation using liquid chromatography-mass spectrometry. The TSAR validation route stopped during method definition because further method development was required; no method-specific robustness or performance failure was demonstrated because experimental validation did not proceed. Detailed methodology remains Analytical chemistry readout; Enzyme/biochemical activity assay. External_evidence_step_stage = VAL_STOP and case_study_method = 0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_STOP","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection; Standardisation / regulatory adoption","bottleneckCount":"3","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2019-09","shortName":"T4-FITC","title":"Thyroid method 3b: Thyroxine-binding prealbumin (TTR) binding using fluorescence displacement (T4-FITC)","organisation":"EURL ECVAM - European Union","description":"This method investigates interference of test items with binding of thyroid hormones to human serum transport protein 'thyroxine-binding prealbumin (TTR)'. The principle of the method is that the addition of TTR-binding compounds to a mixture of TTR and a fluorescent conjugate FITC-T4 causes a decrease in fluorescence, because the TTR-binding compounds compete FITC-T4 out of the TTR binding-pocket and consequently lead to a decrease in the ratio of bound to unbound FITC-T4. The FITC-T4 conjugate exhibits higher fluorescence intensity when bound to TTR than in the unbound condition, probably due to the fact that the iodine atoms of the T4 present in the TTR binding pocket can no longer contribute to the intramolecular fluorescence quenching of the FITC-T4 conjugate. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:10","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Ongoing","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"HTS; Binding/interaction assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert interpretation: T4-FITC is an in vitro competitive binding assay measuring displacement of fluorescently labelled T4 from transthyretin (TTR). It interrogates a direct thyroid-hormone transport-protein interaction rather than transmembrane transport, so the previous Barrier/permeability/transport label was removed. Detailed methodology corrected to HTS; Binding/interaction assay. Later PEPPER validation and OECD Test Guidelines Programme Project 4.180 support case_study_method = 1 and External_evidence_step_stage = REG_DRAFT.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_DRAFT","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Applicability domain; Standardisation / regulatory adoption","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2019-08","shortName":"ANSA-FD","title":"Thyroid method 3a: Thyroxine-binding prealbumin (TTR) / thyroxine-binding globulin (TBG) binding using fluorescence displacement (ANSA)","organisation":"EURL ECVAM - European Union","description":"This method investigates interference of test items with binding of thyroid hormones to human serum transport proteins 'thyroxine-binding prealbumin' (TTR) and 'thyroxine-binding globulin' (TBG). The binding of 8-anilino-1-naphtalenesulfonic acid (ANSA) to TTR or TBG produces fluorophore complexes with intrinsic fluorescence signal. In the presence of competitive ligands, displacement of ANSA occurs and the fluorescence signal detected decreases. Binding/displacement capacity of endocrine/thyroid disrupting chemicals can be assessed and compared to that of T3 and/or T4. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:12","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Finalised","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"HTS; Binding/interaction assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert interpretation: ANSA-FD is an in vitro competitive protein-binding assay for TTR and TBG. It measures displacement of fluorescent ANSA from thyroid-hormone transport proteins and does not directly measure transmembrane transport, so the previous Barrier/permeability/transport label was removed. Detailed methodology corrected to HTS; Binding/interaction assay. TTR performance was stronger than TBG performance, and later work further evolved the assay formats, but no distinct formal alternative regulatory progression route for the exact TM2019-08 method was identified. External_evidence_step_stage = VAL_PEER_FINAL and case_study_method = 0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_PEER_FINAL","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Applicability domain; Standardisation / regulatory adoption","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2019-07","shortName":"NIS-SKR","title":"Thyroid method 2d: Activation of the sodium iodide symporter (NIS) based on Sandell-Kolthoff reaction","organisation":"EURL ECVAM - European Union","description":"This method measures the active transport of extracellular iodide across the cellular membrane of cells expressing a functional sodium/iodide (Na+/I-) symporter (NIS), an intrinsic membrane glycoprotein that actively transports iodide from blood into thyroid follicular cells during the initial step of TH synthesis. This method is designed to identify test items that inhibit NIS-mediated iodide uptake by directly competing with iodide for intracellular transport, or indirectly, through an inhibition of Na+/K+ ATPase that disrupts maintenance of the critical cross-membrane sodium gradient required for NIS functionality. Reduction of intracellular iodide is measured as optical density with a spectrophotometric readout following the Sandell-Kolthoff (SK) reaction. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Stopped","workflowStep":"Validation","workflowStage":"Stopped","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:13","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Discontinued","code":"VAL_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"HTS; Analytical chemistry readout; Barrier/permeability/transport assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert interpretation: NIS-SKR is an in vitro mechanistic iodide-transport assay measuring NIS-mediated uptake with a Sandell-Kolthoff analytical readout. Detailed methodology corrected to HTS; Analytical chemistry readout; Barrier/permeability/transport assay. Enzyme/biochemical and phototoxicity labels were removed. The original TSAR route stopped because the Part 1 report was not provided and the Mel624 test system was no longer commercially available, not because assay performance or mechanistic relevance was shown to fail. Subsequent redevelopment using alternative human NIS-expressing systems and the ongoing ThyreoSafe validation programme support case_study_method = 1 and External_evidence_step_stage = VAL_ONGO.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_STOP","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection; Access / implementation; Standardisation / regulatory adoption","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2019-04","shortName":"AUR-TPO","title":"Thyroid method 2a: Thyroperoxidase (TPO) inhibition based on oxidation of Amplex UltraRed","organisation":"EURL ECVAM - European Union","description":"This method evaluates the activity of the thyroperoxidase (TPO), a key enzyme for the synthesis of thyroid hormones. The method allows to identify TPO-inhibiting test items by assessing the enzyme activity in prepared extracts from FTC-238 cells transfected with human recombinant TPO. TPO activity is measured through the oxidation of a commercially-available peroxidase substrate (Amplex UltraRed, AUR, ® LifeTech) and its conversion to a fluorescent product. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:13","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Finalised","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"HTS; Enzyme/biochemical activity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert interpretation: AUR-TPO is an in vitro mechanistic thyroperoxidase-activity assay measuring oxidation of Amplex UltraRed by human TPO. Detailed methodology corrected to HTS; Enzyme/biochemical activity assay. The original validation identified substantial run-to-run/background variability, particularly for inactive or weak-response conditions. Later high-throughput AUR-hTPO development and the ongoing ThyreoSafe programme support continued method development outside the original TSAR route. case_study_method = 1. The furthest completed authoritative stage remains OECD expert assessment, so External_evidence_step_stage = VAL_PEER_FINAL.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_PEER_FINAL","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Programme prioritisation / route selection; Standardisation / regulatory adoption","bottleneckCount":"5","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2019-02","shortName":"TRH-CHOK1","title":"Thyroid method 1a: PATHHUNTER® BETA-ARRESTIN thyrotropin-releasing hormone (TRH) receptor activation (beta-galactosidase) measuring agonist and antagonist activities","organisation":"EURL ECVAM - European Union","description":"This method is a chemiluminescent in vitro method which measures the agonist and antagonist activities of test items by assessing the thyrotropin-releasing hormone receptor (TRHR) activation. The method employs the commercially available Chinese hamster ovary cells (CHO-K1) engineered to stably express the tagged proteins TRHR and β-Arrestin (PathHunter® CHO-K1 TRHR β-Arrestin Cell Line). Following chemical-TRHR binding, the ProLink™ tagged GPCR is activated inducing the recruitment of Enzyme Acceptor tagged β-Arrestin, forcing complementation of the two enzyme fragments. The resulting functional enzyme hydrolyses the substrate to generate a chemiluminescent signal. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods ’.","stepStage":"Validation > Stopped","workflowStep":"Validation","workflowStage":"Stopped","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:14","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Discontinued","code":"VAL_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"HTS; Binding/interaction assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert interpretation: TRH-CHOK1 is an in vitro functional TRH-receptor signalling assay based on beta-arrestin recruitment and enzyme-fragment complementation, not reporter-gene transcription. Detailed methodology corrected to HTS; Binding/interaction assay; Reporter gene and Enzyme/biochemical activity assay labels were removed. The planned Part 1 and Part 2 studies were not performed because laboratory personnel were redeployed to pandemic-related emergency medical services. No scientific performance failure was therefore demonstrated. case_study_method = 0 and External_evidence_step_stage = VAL_STOP.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_STOP","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection; Access / implementation; Standardisation / regulatory adoption","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2025-01","shortName":"GARDSkin DR","title":"GARDskin Dose-Response","organisation":"EURL ECVAM - European Union","description":"The GARDskin Dose Response (DR) method is a transcriptomics-based in vitro assay measuring with a NanoString nCounter instrumentation the transcriptional levels of a panel of genes called the GARDskin Prediction Signature (GPS). It is a variation of the established GARDskin assay (TSAR TM2011-09; OECD TG 442E) for skin sensitisation assessment. Consistently with the GARDskin, the GARDskin DR addresses the third key event of the skin sensitisation Adverse Outcome Pathway (activation of dendritic cells). It uses the very same cell system (a subclone of the MUTZ-3 cell line), protocols, and analysis pipeline, but instead of testing at a single concentration as in the traditional GARDskin, it measures gene expression across a range of concentrations. In addition, it provides an add-on to the established prediction model allowing to convert the data into a \"Predicted Potency Value\" which is proposed for discriminating between UN GHS subcategory 1A skin sensitisers from those not categorised as subcategory 1A i.e., subcategory 1B or no category.","stepStage":"Submission > Assessment of full submission","workflowStep":"Submission","workflowStage":"Assessment of full submission","topic":"Skin sensitisation","yearReceived":"2025","generalComments":"","protocolSop":"","lastUpdate":"Thursday, July 24, 2025 - 12:09","lastUpdateDate":"2025-07-24","stage":"Test Submission","status":"Ongoing","code":"SUB_ASSESS","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro; In silico; Mixed","specificMethodologies":"Omics; AI/ML","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Expert interpretation: GARDskin Dose-Response is a method extension of GARDskin TM2011-09, using the same MUTZ-3-derived cell system, protocol family and transcriptomic analysis pipeline but adding multi-concentration testing and a quantitative Predicted Potency Value. The existing lineage coding to TM2011-09 as predecessor with relationship 'Method extension' is retained. The method is currently still at full-submission assessment; between-laboratory reproducibility and additional GHS 1A evidence remain outstanding. case_study_method = 0 and External_evidence_step_stage = SUB_ASSESS.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_ASSESS","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance","bottleneckCount":"3","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2024-01","shortName":"BBB-oC","title":"Blood-brain barrier-on-a-chip (BBB-oC) for drug testing of brain-targeting delivery","organisation":"EURL ECVAM - European Union","description":"The Blood-brain barrier-on-a-chip (BBB-oC) is a 3D co-culture of brain microvascular endothelial cells, pericytes, astrocytes and/or neurons in a microfluidic interconnected three-chamber device. The BBB-oC is designed to evaluate the permeability of the BBB, by transendothelial electrical resistance (TEER) measurement through integrated microelectrodes and fluorescent measurements using tracers of different molecular weight. The method is proposed as an in vitro alternative for the evaluation of the performance of brain-targeting drugs.","stepStage":"Submission > Not considered for validation","workflowStep":"Submission","workflowStage":"Not considered for validation","topic":"Human health","yearReceived":"2024","generalComments":"","protocolSop":"","lastUpdate":"Tuesday, June 3, 2025 - 13:10","lastUpdateDate":"2025-06-03","stage":"Test Submission","status":"Discontinued","code":"SUB_NOTVAL","applicationDomain":"Pharmaceutical","endpoint":"Human health — unspecified","methodology":"In vitro","specificMethodologies":"MPS; Microfluidic; Barrier/permeability/transport assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Expert interpretation: BBB-oC is an in vitro microphysiological blood-brain-barrier model using a microfluidic multicellular co-culture with TEER and fluorescent tracer permeability readouts. Detailed methodology corrected to MPS; Microfluidic; Barrier/permeability/transport assay; Analytical chemistry readout was removed. Because the public TSAR record does not disclose the technical reasons for the 'Not considered for validation' decision, no additional method-specific failure categories are inferred. case_study_method = 0 and External_evidence_step_stage = SUB_NOTVAL.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_NOTVAL","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2016-02","shortName":"Bioelution","title":"Bioaccessibility testing (Bioelution) of metals, inorganic metals compounds and metals-containing materials: simulated gastric fluid","organisation":"EURL ECVAM - European Union","description":"The bioelution test measures the fraction of a substance that dissolves under surrogate physiological conditions (i.e. simulated gastric fluid) and is potentially available for absorption into systemic circulation (bioaccessible concentration). This test method is not a toxicity test. The test submitter proposed to use the method in a compartive manner (target and reference material) to generate relative bioaccessible metal ion data for the oral route of exposure, which they consider relevant to systemic effects of metal-containing materials. The relative results obtained could be used to make predictions of how the test material will behave compared to the reference material, based on relative metal ion release. This assumes that the dissolved metal ion is the cause of toxicity. The test method was then proposed to support read across and grouping under REACH for systemic endpoints and to assign CLP classifications. In the context of hazard classification, the test method has been proposed as a refinement to the current approach to alloy classification. Alloys are defined as special preparations under REACH in recognition of the fact that they do not behave as simple mixtures (EC, 2006). Thus, the rationale is that the gastric bioaccessible concentration of a metal in an alloy appears more informative and then relevant for predicting the toxicity than simply using the concentration of the metal ingredient. The systemic toxicity of most metals and metalloids is associated to a large degree with the release of soluble metal ions and their uptake by the body and/or interaction at their target organ sites (i.e., the bioavailability of the metal ions). The simple presence of a metal or inorganic ion in a substance does not necessarily impart to that substance the biological properties of the metal/inorganic ion; it is the bioavailability of the ion at the site of action in the organism that is the most important factor determining toxicity for metals and minerals.","stepStage":"Regulatory acceptance/Standards > Stopped","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Stopped","topic":"Bioaccessibility","yearReceived":"2016","generalComments":"","protocolSop":"Bioelution Protocol - Feb 2025","lastUpdate":"Thursday, April 16, 2026 - 09:12","lastUpdateDate":"2026-04-16","stage":"Regulatory assessment","status":"Rejected","code":"REG_STOP","applicationDomain":"Pharmaceutical; Industrial chemicals","endpoint":"Bioaccessibility","methodology":"In chemico","specificMethodologies":"Analytical chemistry readout; Read-across/WoE; Bioaccessibility/bioelution assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert interpretation: Bioelution is an in chemico cell-free bioaccessibility assay measuring dissolution of metals/materials in simulated gastric fluid, typically followed by analytical quantification and use in comparative assessment/read-across. Core methodology corrected from mixed In silico/In chemico to In chemico. Detailed methodology corrected to Analytical chemistry readout; Read-across/WoE; Bioaccessibility/bioelution assay; the barrier/transport label was removed. ESAC considered the method scientifically valid and reproducible, but OECD Test Guideline standardisation later stopped amid unresolved protocol/applicability/regulatory-interpretation issues. Continued protocol/application use outside the stopped formal TG route supports case_study_method = 1, while External_evidence_step_stage remains REG_STOP.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_STOP","bottlenecks":"Validation readiness / evidence package; Applicability domain; Regulatory relevance / integration; Programme prioritisation / route selection; Standardisation / regulatory adoption","bottleneckCount":"5","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2018-01","shortName":"EpiSensA","title":"Epidermal Sensitization Assay","organisation":"JaCVAM - Japan","description":"The EpiSensA is an in vitro method for measuring the expression of four marker genes (ATF3, encoding Activating transcription factor 3; GCLM, encoding Glutamate-cysteine ligase, modifier subunit; DNAJB4, encoding DnaJ (Hsp40) homolog, subfamily B, member4; IL-8, encoding Interleukin-8) of the reconstructed human epidermis (RhE) following controlled exposure of test chemicals. The two main important keratinocyte responses that occur in the skin sensitization adverse outcome pathway are Inflammatory response and Induction of cytoprotective gene pathways. The assay is based on the induction of the multiple marker genes related to these two keratinocyte responses.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin sensitisation","yearReceived":"2018","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/JACVAM/EpiSensA%20SOP%20v2.6.pdf, https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/JACVAM/EpiSensA_Datasheet_en.xlsx, https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/JACVAM/EpiSensA%20SOP%20v2.6.pdf, https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/JACVAM/EpiSensA_Datasheet_en.xlsx","lastUpdate":"Monday, March 9, 2026 - 11:10","lastUpdateDate":"2026-03-09","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Omics; Organoid/3D tissue model","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Expert interpretation: EpiSensA is an in vitro reconstructed-human-epidermis gene-expression assay addressing keratinocyte activation in the skin-sensitisation AOP. Core methodology corrected to In vitro; the previous In chemico/Mixed coding was removed. Detailed methodology corrected to Omics; Organoid/3D tissue model; immunoassay/flow-cytometry and chemical-reactivity labels were removed. The method completed validation and was adopted into OECD TG 442D. The remaining issue is limited availability of the original LabCyte EPI-MODEL24 system, an access/implementation limitation rather than a scientific-performance failure. case_study_method = 0 and External_evidence_step_stage = REG_ADOPT.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Access / implementation","bottleneckCount":"1","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2020-02","shortName":"22Rv1/MMTV_GR-KO","title":"Androgen Receptor Transactivation Assay for Detection of androgenic Agonist and Antagonist Activity of Chemicals using the stably transfected human 22Rv1/MMTV_GR-KO cell line","organisation":"OECD - International Organisation","description":"The 22Rv1/MMTV_GR-KO AR-mediated stably transfected transcriptional activation (TA) assay was established to screen chemicals for endocrine activity via interaction with the AR using a human prostate cancer cell line, 22Rv1, that endogenously expresses the AR (1, 2). This test method is specifically designed to detect human AR-mediated TA and inhibition by measuring luciferase activity as the endpoint. The information of chemical dependent interference with luminescence signals is limited in a GR-knockout 22Rv1/MMTV cell line.","stepStage":"Regulatory acceptance/Standards > Published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Published","topic":"Endocrine disruption","yearReceived":"2020","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:58","lastUpdateDate":"2026-04-02","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_PUBL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert interpretation: 22Rv1/MMTV_GR-KO is an in vitro androgen-receptor transcriptional activation assay using a luciferase reporter in human 22Rv1 prostate cells with glucocorticoid-receptor knockout to improve AR specificity. Detailed methodology remains Reporter gene assay. Validation and inter-laboratory performance were strong and the method is published in OECD TG 458. The remaining documented issue is applicability-domain scope rather than lifecycle failure. case_study_method = 0 and External_evidence_step_stage = REG_PUBL.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_PUBL","bottlenecks":"Applicability domain","bottleneckCount":"1","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2016-09","shortName":"VM7Luc ER TA","title":"The The VM7Luc ER TA test method: An In Vitro Assay for Identifying Human Estrogen Receptor Agonist and Antagonist Activity of Chemicals","organisation":"ICCVAM/NICEATM - United States","description":"The VM7Luc ER TA test method (also known as the LUMI-CELL® test method) was developed by Xenobiotic Detection Systems, Inc., with support from NIEHS Small Business Innovation Research grant ES10533-03. The test method measures the extent to which a substance induces or inhibits transcriptional activity (TA) via ER-mediated pathways in recombinant VM7Luc4E2 cells. The VM7Luc4E2 cell line was derived from the MCF7 human breast cancer cell line that endogenously express both human ER forms, ERα and ERβ, and that have been stably transfected with the plasmid pGudLuc7.ERE. This plasmid contains four copies of a synthetic oligonucleotide containing the estrogen response element upstream of the mouse mammary tumor viral promoter and the firefly luciferase gene. VM7Luc4E2 cells emit measurable light in response to estrogen and estrogen-like substances. In 2016, NICEATM received new information regarding the LUMI-CELL® test. DNA testing has now shown that the original cell line used to develop the test was not the BG1 human ovarian carcinoma cell line. It was a variant of the MCF7 human breast cancer cell line. The cell line used in the test, originally referred to as BG1Luc4E2 (Rogers and Denison 2000), will now be designated as VM7Luc4E2 (\"V\" = variant; \"M7\" = MCF7 cells). Likewise, the test will now be generically referred to as the VM7Luc ER TA test. While this changes the origin of the cell line upon which the test is based, it does not affect published validation studies nor the use and application of this test for screening of estrogenic/anti-estrogenic chemicals.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Reproductive toxicity, Endocrine disruption","yearReceived":"2016","generalComments":"This test method was originally referred to as the BG1Luc ER TA method.","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=455","lastUpdate":"Monday, December 16, 2024 - 11:30","lastUpdateDate":"2024-12-16","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Access / implementation","bottleneckCount":"1","animalUseImpact":"Replacement","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2011-09","shortName":"GARD","title":"Genomic Allergen Rapid Detection test","organisation":"EURL ECVAM - European Union","description":"The Genomic Allergen Rapid Detection (GARD) is a transcriptomics-based in vitro assay proposed to assess the skin sensitisation potential/potency of chemicals. GARD addresses the third key event of the skin sensitisation Adverse Outcome Pathway (activation of dendritic cells), step 5 (biochemical pathways related to skin sensitisation) and step 6 (immune recognition of chemical allergens and maturation of dendritic cells (DCs)). The test method has two elements: the so-called GARDskin to assess skin sensitisation potential (first submission in October 2011) and GARDpotency to assess skin sensitisation potency (first submission in July 2018). The test method is based on the nCounter system and measures the expression level of a panel of genes in the human myeloid cell line MUTZ-3 exposed to chemicals. In GARDskin, the expression of a panel of 200 genes (the GARD Prediction Signature, GPS) is used as input to a prediction model based on a Support Vector Machine (SVM) trained with 38 chemicals. This model classifies chemicals as skin sensitising or non-sensitising. The GARDpotency can be considered as second-tier of a testing strategy, following GARDskin. Thus, in GARDpotency, the model sub-categorises sensitisers into GHS/CLP categories 1A (strong/extreme sensitisers) or 1B (weak/moderate sensitisers) based on the expression of a panel of 52 genes (the GARD Potency Prediction Signature, GPPS).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Sensitisation","yearReceived":"2011","generalComments":"Please note that the GARDskin Assay Protocol available in the link above is a revised version provided by the test method developer after completion of the ESAC peer review to address comments made by the ESAC.","protocolSop":"GARDskin Assay Protocol","lastUpdate":"Thursday, April 2, 2026 - 10:00","lastUpdateDate":"2026-04-02","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Sensitisation — unspecified","methodology":"Mixed","specificMethodologies":"Omics; AI/ML; Integrated testing strategy/battery","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert interpretation: GARD is a transcriptomics-based skin-sensitisation method combining a human MUTZ-3-derived in vitro exposure system with a computational Support Vector Machine prediction model and second-tier potency logic. Per project coding preference, Core_methodology is recorded as Mixed only; detailed methodology remains Omics; AI/ML; Integrated testing strategy/battery. Historical acceptance bottlenecks concerned proprietary software/source-code access, GLP/regulatory implementation of provider-controlled prediction software, patent/IP issues and programme progression, not failed predictive performance or reproducibility. These issues were subsequently resolved and GARDskin was adopted into OECD TG 442E. case_study_method = 0 and External_evidence_step_stage = REG_ADOPT.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package; Regulatory relevance / integration; Programme prioritisation / route selection; Access / implementation; Standardisation / regulatory adoption","bottleneckCount":"5","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2011-11","shortName":"SENS-IS","title":"SENS-IS","organisation":"EURL ECVAM - European Union","description":"The SENS-IS assay is a patent-protected gene expression-based test method proposed to discriminate between skin sensitisers, non-sensitisers and skin irritants by analysing the expression in Reconstructed human Epidermis (RhE) of a panel of 65 genes grouped in one gene set for irritancy (IRR) and two (SENS-IS and ARE) for sensitisation. In addition, the test method allows the classification of sensitisers into potency categories on the basis of the concentration of chemical needed to induce a positive response. A test substance is classified as sensitiser on the basis of the number of overexpressed genes (compared to solvent control) measured by qRT-PCR in Episkin RhE tissues. The biomarkers have been selected starting with data mining, followed by treatment with either sensitisers or irritants in the LLNA model, further refined using qPCR analysis of suction blisters on human volunteers sensitised to Nickel or fragrance mix in a controlled clinical trial, and final selection based on testing data in Episkin RhE tissues. The test system used is the commercially available EpiskinTM, a 3D RhE obtained by culturing adult human keratinocytes on a collagen substrate to permit their terminal differentiation and the reconstruction of an epidermis with a functional stratum corneum. According to the test submitter, this model can take account of skin metabolism and skin penetration and should be widely applicable to testing of chemicals, including pre and pro-haptens, solids and liquids.","stepStage":"Peer-review > Stopped","workflowStep":"Peer-review","workflowStage":"Stopped","topic":"Skin sensitisation","yearReceived":"2011","generalComments":"Under external validation","protocolSop":"","lastUpdate":"Thursday, May 5, 2022 - 11:59","lastUpdateDate":"2022-05-05","stage":"Validation","status":"Discontinued","code":"VAL_PEER_STOP","applicationDomain":"Cosmetics; Pharmaceutical; Industrial chemicals","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Omics; Organoid/3D tissue model","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Expert interpretation: SENS-IS is an in vitro reconstructed-human-epidermis gene-expression assay for skin sensitisation, using qRT-PCR biomarker panels to distinguish sensitising from non-sensitising responses and support potency classification. Detailed methodology corrected to Omics; Organoid/3D tissue model; the previous Barrier/permeability/transport label was removed because permeability is not the measured endpoint. The original EURL ECVAM/ESAC route was stopped because the evidence package was insufficient for reliable peer review, including remaining questions on reproducibility and predictive capacity. Later external validation, peer review and OECD Test Guideline development support case_study_method = 1 and External_evidence_step_stage = REG_DRAFT.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_DRAFT","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Programme prioritisation / route selection; Standardisation / regulatory adoption","bottleneckCount":"5","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals; Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2010-07","shortName":"AR-CALUX","title":"Transactivation assay for detection of androgenic activity of chemicals","organisation":"EURL ECVAM - European Union","description":"Androgen Receptor TransActivation assay (ARTA). This method makes use of the osteosarcoma celline U2-OS which has been transfected with the full cDNA for the human androgen receptor (pSG5-neo-hAR), and, a reporter gene for luciferase expression under control of a limited promoter and a triple tandem of upstream elements ARE (pGL3-3XAREtataLuc). This method provides information on the (anti-) androgenic activity of substances when the AR-CALUX cells are exposed, leading to luminescence. The measurements and the classification model allow to predict if substances have a positive or negative reponse for either the agonist or antagonist mode of the method. This method is intended for screening purposes.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Reproductive toxicity, Endocrine disruption","yearReceived":"2010","generalComments":"The AR-CALUX method was submitted by BioDetection Systems (The Netherlands) for a EURL ECVAM coordinated validation study. The experimental part was concluded by the end of 2018 and the report reviewed by ESAC in June 2019. The draft TG (TG458) was submitted to OECD mid June 2019, for commenting rounds to start at WNT. The TG458 was adopted (April 2020) and published(June 2020). This TG includes 3 validated ARTA methods: AR-EcoScreen from Japan, AR-CALUX from the Netherlands, 22Rv1/MMTV_GR-KO assay from Korea.","protocolSop":"https://publications.jrc.ec.europa.eu/repository/bitstream/JRC116993/JRC116993_02.pdf, https://publications.jrc.ec.europa.eu/repository/bitstream/JRC116993/JRC116993_02.pdf","lastUpdate":"Tuesday, September 2, 2025 - 14:02","lastUpdateDate":"2025-09-02","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Industrial chemicals","endpoint":"Reproductive toxicity; Endocrine disruption","methodology":"In vitro","specificMethodologies":"HTS; Reporter gene assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert interpretation: AR-CALUX is an in vitro human androgen-receptor transactivation assay using U2-OS cells with a luciferase reporter to detect AR agonism and antagonism. Validation and ESAC peer review demonstrated strong within- and between-laboratory reproducibility and good regulatory performance. Detailed methodology corrected to HTS; Reporter gene assay; the AI/ML label was removed. No unresolved lifecycle bottleneck is identified. case_study_method = 0 and External_evidence_step_stage = REG_ADOPT.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2022-01","shortName":"ProtReact","title":"ProtReact","organisation":"EURL ECVAM - European Union","description":"The ProtReact is an in chemico method that addresses the covalent binding of electrophilic chemicals with nucleophilic sites of amino acids in skin proteins (i.e., haptenation) which represents the molecular initiating event of the skin sensitisation Adverse Outcome Pathway. The test method measures reactivity of a test chemical by quantifying through fluorescence/absorbance, the depletion of lysine and cysteine peptides in 96 well-plates. It is proposed to contribute to the skin sensitisation hazard assessment of chemicals.","stepStage":"Submission > Not considered for validation","workflowStep":"Submission","workflowStage":"Not considered for validation","topic":"Skin sensitisation","yearReceived":"2022","generalComments":"","protocolSop":"","lastUpdate":"Monday, December 16, 2024 - 11:12","lastUpdateDate":"2024-12-16","stage":"Test Submission","status":"Discontinued","code":"SUB_NOTVAL","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Skin sensitisation","methodology":"In chemico","specificMethodologies":"HTS; Analytical chemistry readout; Chemical reactivity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Missing","verificationNote":"Expert interpretation: ProtReact is an in chemico high-throughput peptide-reactivity assay addressing protein haptenation, the molecular initiating event of the skin-sensitisation AOP. Chemical reactivity is quantified through fluorescence/absorbance in a 96-well format. Detailed methodology is corrected to HTS; Analytical chemistry readout; Chemical reactivity assay; the Binding/interaction label is removed because the endpoint is covalent chemical reactivity rather than non-covalent binding. EURL ECVAM considered the method mechanistically relevant but did not prioritise follow-up validation because additional within- and between-laboratory reproducibility and predictive-capacity evidence was required and established methods already addressed the same mechanistic event. Subsequent scientific publication further characterised the same method in 106 chemicals, supporting case_study_method = 1 as scientific continuation after the stopped TSAR route, while External_evidence_step_stage remains SUB_NOTVAL because no later formal validation or regulatory progression was identified.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_NOTVAL","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Programme prioritisation / route selection","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2021-01","shortName":"LUCS-VALITOX","title":"LUCS (Light-up Cell System)-VALITOX","organisation":"EURL ECVAM - European Union","description":"The LUCS test method (light-up cell system) measures general or basal cytotoxicity in cells of human origin. The test method uses thiazole orange (TO) as fluorescent dye that passively enters the cells and binds to nucleic acids. In homeostatic cells, efflux transport proteins quickly remove the dye limiting their access to the nucleic acids and keeping the fluorescent levels inside the cells low. Changes in cell homeostasis result in the dye entering the cell massively and binding to the nucleic acids, increasing the fluorescence levels. There is production of ROS inside live cells by light induction and the fluorescence before and after applying light, both in healthy (untreated) and treated cells is measured. The change in fluorescence levels are higher in untreated cells compared to treated cells, which have lost homeostasis. The test method is proposed as: 1) a method to describe cytotoxicity, and 2) a method to inform acute oral toxicity, in particular for providing the starting dose for the in vivo acute oral toxicity test as described in OECD GD 129.","stepStage":"Submission > Not considered for validation","workflowStep":"Submission","workflowStage":"Not considered for validation","topic":"Acute toxicity","yearReceived":"2021","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 11:37","lastUpdateDate":"2026-04-02","stage":"Test Submission","status":"Discontinued","code":"SUB_NOTVAL","applicationDomain":"Mixed/general toxicology","endpoint":"Acute toxicity","methodology":"In vitro","specificMethodologies":"HTS; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Missing","verificationNote":"Expert interpretation: LUCS-VALITOX is an in vitro human-cell basal cytotoxicity assay using thiazole-orange fluorescence and light-induced ROS to quantify loss of cellular homeostasis. Detailed methodology corrected to HTS; Cytotoxicity/cell viability assay; Binding/interaction and Barrier/permeability/transport labels were removed because these are not the measured endpoints. EURL ECVAM did not progress the method after pre-submission assessment because standalone basal-cytotoxicity information has limited regulatory value on its own and comparable approaches already existed; no specific failure of reproducibility or predictive performance was documented as the reason for the decision. TSAR explicitly identifies TM2014-05 as the preceding method, so the LUCS lineage is restored. case_study_method = 0 and External_evidence_step_stage = SUB_NOTVAL.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_NOTVAL","bottlenecks":"Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Pharmaceutical / human medicines; Industrial chemicals; Cosmetics","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM1994-01","shortName":"3T3NRU Phototoxicity","title":"The 3T3 neutral red uptake (NRU) phototoxicity assay","organisation":"EURL ECVAM - European Union","description":"The 3T3 Neutral Red Uptake (NRU) assay is based on an immortalised mouse fibroblast cell line called Balb/c 3T3. The method is based on a comparison of the cytotoxicity of a chemical when tested in the presence or absence of exposure to a non-cytotoxic dose of simulated solar light (i.e. ultra-violet light). Cytotoxicity in this test is expressed as a concentration-dependent reduction of the uptake of the vital dye neutral red when measured 24 hours after treatment with the test chemical and irradiation. The test chemical together with the irradiation may alter the cell surface and in effect may result in a decreased uptake and binding of the neutral red dye. Differences in this uptake can be measured with a spectrophotometer, which allows the distinction and quantification between viable, damaged or dead cells.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin irritation","yearReceived":"1994","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=78","lastUpdate":"Thursday, April 16, 2026 - 09:30","lastUpdateDate":"2026-04-16","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Phototoxicity","methodology":"In vitro","specificMethodologies":"Cytotoxicity/cell viability assay; Phototoxicity/photoreactivity assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: the complete TSAR lifecycle already records regulatory adoption of the 3T3 NRU phototoxicity assay, while later formal revision of OECD TG 432 demonstrates continued exact-method regulatory/standardisation progression beyond the captured TSAR lifecycle. Accordingly, case_study_method is set to 1, NEW_STEP_STAGE remains REG_ADOPT and External_evidence_step_stage is REG_ADOPT. Core methodology remains In vitro. The specific methodology is narrowed to Cytotoxicity/cell viability assay; Phototoxicity/photoreactivity assay because neutral-red uptake is a cell-viability readout rather than a barrier/permeability assay. Application domain is broadened to Cosmetics; Pharmaceutical; Industrial chemicals. Three-R and animal-use impact are coded as Replacement because the in vitro assay can replace live-animal phototoxicity testing for its validated intended uses.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain; Mechanistic relevance; Product / matrix qualification","bottleneckCount":"3","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM1997-02","shortName":"EpiDerm-PT","title":"Human 3-D Epidermis Model in Vitro Phototoxicity Test","organisation":"EURL ECVAM - European Union","description":"The test method is based on the commercially available EpiDerm™ model, a reconstructed human epidermal (RhE) model grown from human-derived epidermal keratinocytes, which are cultured to form a multilayered and highly differentiated model of the human epidermis. The SOP has been developed on the basis of the Skin2 test in 1997 and method validation conducted during 1997-1999. A follow-up study has been performed during 2002-2005 to access whether the method can also address the potency of the topically applied photo-toxins. The Phototoxicity of chemicals is assessed by the measurement cytotoxic response of irradiated and non-irradiated RhE model. The method can be used as stand-alone or in combination with OECD TG 432 and other assays depending on the outcomes and regulatory schemes. The test was accepted in 2015 into the ICH Guideline S10 Photosafety evaluation of pharmaceuticals.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Basal Cytotoxicity","yearReceived":"1997","generalComments":"","protocolSop":"http://cidportal.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/DBALM_docs/121_P_EpiDermTM%20Phototoxicity%20Assay.pdf","lastUpdate":"Thursday, April 2, 2026 - 12:34","lastUpdateDate":"2026-04-02","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Pharmaceutical","endpoint":"Basal cytotoxicity; Phototoxicity","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay; Phototoxicity/photoreactivity assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: the complete TSAR lifecycle already captures the formal progression of EpiDerm-PT through regulatory adoption, including OECD TG 498, so case_study_method remains 0 and NEW_STEP_STAGE remains REG_ADOPT. The method remains In vitro with Organoid/3D tissue model; Cytotoxicity/cell viability assay; Phototoxicity/photoreactivity assay. Application domain is broadened to Cosmetics; Pharmaceutical; Industrial chemicals because the validated method and OECD TG are not limited to pharmaceuticals. Three-R and animal-use impact are coded as Replacement because the reconstructed human epidermis method can replace live-animal phototoxicity testing for its validated intended uses. External_evidence_step_stage is set to REG_ADOPT to independently confirm the formal OECD milestone.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain; Product / matrix qualification","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2003-03","shortName":"BCOP","title":"Bovine corneal opacity and permeability test method","organisation":"ICCVAM/NICEATM - United States","description":"The Bovine Corneal Opacity and Permeability test method (BCOP) is an in vitro test method that can be used to identify chemicals (substances or mixtures) as either 1) causing “serious eye damage” (category 1 of the Globally Harmonised System for the Classification and Labelling of chemicals (GHS)), or 2) not requiring classification for eye irritation or serious eye damage according to the GHS. BCOP is an organotypic model that provides short-term maintenance of normal physiological and biochemical function of the bovine cornea in an isolated system. Damage by the test substance is assessed by quantitative measurements of changes in corneal opacity and permeability with an opacitometer and an ultraviolet/visible (UV/VIS) spectrophotometer, respectively. Both measurements are used to calculate an In Vitro Irritancy Score, which is used to assign an in vitro irritancy classification for prediction of the in vivo ocular irritation potential of a test substance. Although not part of the adopted OECD test guideline, histopathology can be useful to discriminate borderline cases (i.e., substances that produce results that preclude assignment to a single category) or to identify ocular damage that does not produce opacity or permeability changes in the isolated cornea. Histopathology can also be used where the mode of action cannot be easily predicted, when delayed effects might be anticipated, or when a more complete characterization of damage is needed","stepStage":"Regulatory acceptance/Standards > Published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Published","topic":"Serious eye damage/Eye irritation","yearReceived":"2003","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 18:14","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_PUBL","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Eye irritation/Serious eye damage","methodology":"Ex vivo","specificMethodologies":"Analytical chemistry readout; Barrier/permeability/transport assay; Ex vivo/tissue-based assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: the complete TSAR event history for BCOP progresses beyond the recommendation record to regulatory publication, so NEW_STEP_STAGE is corrected from REC_PUBL to REG_PUBL. The primary technical domain is Ex vivo because BCOP uses isolated bovine corneal tissue; opacity and fluorescein permeability are readouts rather than separate core domains. Specific methodology is narrowed to Analytical chemistry readout; Barrier/permeability/transport assay; Ex vivo/tissue-based assay. High-content imaging, organoid/3D tissue model and phototoxicity labels are removed. Later formal updates to OECD TG 437 after the last TSAR event demonstrate continued exact-method regulatory progression outside TSAR, supporting case_study_method = 1 and External_evidence_step_stage = REG_ADOPT. BCOP is coded as Replacement for its validated intended uses because it can replace the live rabbit eye test for defined hazard-classification decisions using slaughterhouse-derived corneas.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_PUBL","bottlenecks":"Predictive performance; Applicability domain; Product / matrix qualification","bottleneckCount":"3","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2003-02","shortName":"ICE","title":"Isolated Chicken Eye","organisation":"ICCVAM/NICEATM - United States","description":"The Isolated Chicken Eye test method (ICE) is an in vitro test method that can be used to identify chemicals (or substances or mixtures) as either 1) causing \"serious eye damage\" (Category 1 of the Globally Harmonized System for the Classification and Labelling of Chemicals (GHS)), or 2) not requiring classification for eye irritation or serious eye damage according to the GHS. ICE is an organotypic model that provides short-term maintenance of the chicken eye, a byproduct of processing plants. Damage caused by the test substance is assessed by quantitative determination of corneal swelling and qualitative assessment of opacity and fluroescein retention. Each measurement is either 1) converted into a quantitative score that is used to calculate an overall in vitro ocular irritation index or 2) assigned a qualitative categorization that is used to assign an in vitro ocular irritancy classification. Either outcome can then be used to predict the in vivo ocular irritation potential of a test substance.","stepStage":"Regulatory acceptance/Standards > Published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Published","topic":"Serious eye damage/Eye irritation","yearReceived":"2003","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 18:12","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_PUBL","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Eye irritation/Serious eye damage","methodology":"Ex vivo","specificMethodologies":"Ex vivo/tissue-based assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Predictive performance; Applicability domain","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2008-15","shortName":"STE","title":"Short Time Exposure Test","organisation":"ICCVAM/NICEATM - United States","description":"The Short Time Exposure (STE) test is an in vitro test method that identifies the eye injury hazard potential of test substances applied to cultured corneal epithelial cells with cell viability used as the endpoint for quantitation of the extent of injury.","stepStage":"Regulatory acceptance/Standards > Published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Published","topic":"Serious eye damage/Eye irritation","yearReceived":"2008","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 18:10","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_PUBL","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_PUBL","bottlenecks":"Validation readiness / evidence package; Predictive performance; Applicability domain","bottleneckCount":"3","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2008-16","shortName":"Antimicrobial Cleaning Product Testing Strategy","title":"Antimicrobial Cleaning Product Testing Strategy","organisation":"ICCVAM/NICEATM - United States","description":"Testing strategy uses the bovine corneal opacity and permeability (BCOP), Cytosensor microphysiometer (CM), and EpiOcular (EO) test methods to determine EPA hazard category and labeling requirements.","stepStage":"Regulatory acceptance/Standards > Published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Published","topic":"Serious eye damage/Eye irritation","yearReceived":"2008","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 18:08","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_PUBL","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Eye irritation/Serious eye damage","methodology":"Mixed","specificMethodologies":"Organoid/3D tissue model; Barrier/permeability/transport assay; Ex vivo/tissue-based assay; Integrated testing strategy/battery; Metabolic activity sensor assay; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package","bottleneckCount":"1","animalUseImpact":"Replacement","applicationDomainExpert":"Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM1998-05","shortName":"Murine Local Lymph Node Assay","title":"Murine Local Lymph Node Assay","organisation":"ICCVAM/NICEATM - United States","description":"Skin sensitizers induce a primary sensitization of lymphocytes in the auricular lymph nodes that drain the site of test chemical application. In the LLNA, lymphocyte proliferation is proportional to the dose of test chemical applied and is used as a measure of sensitization after weighing the lymph nodes, then extracting and labeling the cells with 3H-methyl thymidine and measuring disintegrations per minute (DPM).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Sensitisation","yearReceived":"1998","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:31","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Industrial chemicals","endpoint":"Sensitisation — unspecified","methodology":"In vivo","specificMethodologies":"In vivo reduction/refinement assay","review":"Expert-reviewed","threeR":"Refinement","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Access / implementation","bottleneckCount":"1","animalUseImpact":"Refinement","applicationDomainExpert":"Industrial chemicals; Cosmetics","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2013-04","shortName":"Ros Assay","title":"Ros (Reactive Oxygen Species) Assay for Photoreactivity","organisation":"JaCVAM - Japan","description":"Phototoxicity is defined as a toxic response is elicited by topically or systemically administered photoreactive chemicals after the exposure of the body to environmental light. The ROS assay was designed for qualitative photoreactivity assessment of chemicals, the principle of which is monitoring of type I (an electron or hydrogen transfer, resulting in the formation of free radical species) and type II (an energy transfer from excited triplet photosensitizer to the oxygen) photochemical reactions in test chemicals exposed to simulated sunlight. In the ROS assay, SO generation is detected by spectrophotometric measurement of p-nitrosodimethylaniline (RNO) bleaching, followed by decreased absorbance of RNO at 440 nm.","stepStage":"Regulatory acceptance/Standards > Published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Published","topic":"Skin irritation, Skin sensitisation, Genotoxicity/Mutagenicity","yearReceived":"2013","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 18:17","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_PUBL","applicationDomain":"Cosmetics; Environmental","endpoint":"Skin irritation; Skin sensitisation; Genotoxicity; Photoreactivity","methodology":"In chemico","specificMethodologies":"Analytical chemistry readout; Phototoxicity/photoreactivity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Predictive performance; Applicability domain","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2016-10","shortName":"IL-8 Luciferase assay for skin sensitization","title":"IL-8 Luciferase assay for skin sensitization","organisation":"JaCVAM - Japan","description":"The IL-8 Luc assay measures changes in IL-8 expression, a cytokine associated with the activation of dendritic cells (key event 3) for evaluating skin sensitisation potential of chemicals. In the THP-1-derived IL-8 reporter cell line, IL-8 expression is measured as luciferase activity.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin sensitisation","yearReceived":"2016","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:22","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Reproducibility / transferability; Predictive performance; Applicability domain","bottleneckCount":"3","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2011-15","shortName":"Vitrigel-Eye Irritancy Test","title":"Vitrigel-Eye Irritancy Test","organisation":"JaCVAM - Japan","description":"The Vitrigel-Eye Irritancy Test (EIT) method is an in vitro test method that allows the identification of test chemicals not requiring classification and labelling for eye irritation or serious eye damage (GHS No Category) as defined by the UN GHS without further testing. This method assesses the eye irritation potential of a test chemical based on its ability to induce damage to the barrier function of the human corneal epithelium (hCE) models. In this test method, time-dependent changes in the Transepithelial Electrical Resistance (TEER) values are indicative of damage to the barrier function of the corneal epithelium following exposure to a test chemical.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Serious eye damage/Eye irritation","yearReceived":"2011","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:22","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Barrier/permeability/transport assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Predictive performance; Applicability domain","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2012-07","shortName":"AR-Ecoscreen test","title":"Androgen Receptor TransActivation Assay using the stably transfected human AR-EcoScreen™ cell line","organisation":"JaCVAM - Japan","description":"The AR-EcoScreen™ method uses the AR-EcoScreenTM cell line to detect (anti)androgenic activity. This method exclusively addresses transactivation and inhibition of an androgen-regulated reporter gene by binding to the human AR, and therefore it should not be directly extrapolated to the complex in vivo situation of androgen regulation of cellular processes. This test method is specifically designed to detect human AR-mediated transactivation and inhibition by measuring luciferase activity as the endpoint. In addition, the assay is only likely to inform on the activity of the parent molecule bearing in mind the limited metabolising capacities of the in vitro cell systems.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Endocrine disruption","yearReceived":"2012","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 20:12","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package","bottleneckCount":"1","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2008-17","shortName":"ER-STTA assay","title":"Stably Transfected Human Estrogen Receptor-α Transactivation Assay using the (h) ERα-HeLa-9903 cell line","organisation":"JaCVAM - Japan","description":"This transactivation (TA) assay uses the (h) ERα-HeLa-9903 cell line to detect estrogenic agonist activity mediated through human estrogen receptor alpha ((h) ERα). This test method is specifically designed to detect (h) ERα-mediated TA by measuring chemiluminescence as the endpoint.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Endocrine disruption","yearReceived":"2008","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:23","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package; Predictive performance","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2016-12","shortName":"ADRA for skin sensitization","title":"In Chemico Skin Sensitisation: Amino acid Derivative Reactivity Assay","organisation":"JaCVAM - Japan","description":"The ADRA is proposed to address the molecular initiating event of the skin sensitisation AOP—namely, protein reactivity—by quantifying the reactivity of test chemicals towards model synthetic amino acid derivatives containing either lysine (NAL) or cysteine (NAC). The relative concentrations of NAC and NAL are measured by high-performance liquid chromatography (HPLC) with gradient elution and UV detection at 281 nm. Percent depletion values are then calculated for both NAC and NAL to discriminate between skin sensitisers and non-sensitisers.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin sensitisation","yearReceived":"2016","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:23","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Skin sensitisation","methodology":"In chemico","specificMethodologies":"Analytical chemistry readout; Chemical reactivity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2008-14","shortName":"LabCyte EPI-MODEL24 SIT","title":"LabCyte EPI-MODEL24 skin irritation test","organisation":"JaCVAM - Japan","description":"This method is based on the in vitro test system of reconstructed human epidermis (RhE), which closely mimics the biochemical and physiological properties of the upper parts of the human skin, i.e. the epidermis. The test chemical is applied topically to a three-dimensional RhE model, comprised of non-transformed human-derived epidermal keratinocytes, which have been cultured to form a multilayered, highly differentiated model of the human epidermis. Cell viability in RhE models is measured by enzymatic conversion of the vital dye MTT [3-(4,5-Dimethylthiazol-2-yl)-2,5-diphenyltetrazolium bromide, Thiazolyl blue; CAS number 298-93-1], into a blue formazan salt that is quantitatively measured after extraction from tissues (31). Irritant chemicals are identified by their ability to decrease cell viability below defined threshold levels.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin irritation","yearReceived":"2008","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:24","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Skin irritation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance","bottleneckCount":"3","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2017-03","shortName":"LabCyte EPI-MODEL24 SCT","title":"LabCyte EPI-MODEL24 skin corrosion test","organisation":"JaCVAM - Japan","description":"Skin corrosion refers to the production of irreversible damage to the skin manifested as visible necrosis through the epidermis and into the dermis, following the application of a test chemical. The test chemical is applied topically to a three-dimensional RhE model, comprised of non-transformed, human-derived epidermal keratinocytes, which have been cultured to form a multi-layered, highly differentiated model of the human epidermis. The RhE test method is based on the premise that corrosive chemicals are able to penetrate the stratum corneum by diffusion or erosion, and are cytotoxic to the cells in the underlying layers. Cell viability is measured by enzymatic conversion of the vital dye MTT [3-(4,5-Dimethylthiazol-2-yl)-2,5-diphenyltetrazolium bromide, Thiazolyl blue tetrazolium bromide; CAS number 298-93-1], into a blue formazan salt that is quantitatively measured after extraction from tissues. Corrosive chemicals are identified by their ability to decrease cell viability below defined threshold levels.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin Corrosion","yearReceived":"2017","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:24","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Skin corrosion","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Predictive performance","bottleneckCount":"1","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2015-04","shortName":"LabCyteCORNEAMODEL24 EIT","title":"LabCyteCORNEAMODEL24 eye irritation test","organisation":"JaCVAM - Japan","description":"This test method is based on commercial three-dimensional Human Cornea-Like Epithelium (RhCE) tissue constructs that are produced using either primary human epidermal keratinocytes. LabCyteCORNEAMODEL24 is used to evaluate the eye hazard potential of a test chemical based on its ability to induce cytotoxicity in a RhCE tissue construct, as measured by the tetrazolium dye.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Serious eye damage/Eye irritation","yearReceived":"2015","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:24","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2019-05","shortName":"TPO-LUM","title":"Thyroid method 2b: Thyroperoxidase (TPO) inhibition based on oxidation of Luminol","organisation":"EURL ECVAM - European Union","description":"This method evaluates the activity of the thyroperoxidase (TPO), a key enzyme for the synthesis of thyroid hormones. The method allows to identify TPO-inhibiting compounds by assessing the enzyme activity in prepared extracts from FTC-238 cells transfected with human recombinant TPO. TPO activity is measured through the oxidation of luminol, resulting in a decrease in luminescence. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Stopped","workflowStep":"Validation","workflowStage":"Stopped","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 12:36","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Discontinued","code":"VAL_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Enzyme/biochemical activity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_STOP","bottlenecks":"Validation readiness / evidence package; Mechanistic relevance","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2019-01","shortName":"ALIsens","title":"In vitro model for the prediction of respiratory sensitization of inhalable substances","organisation":"EURL ECVAM - European Union","description":"The test method is an in vitro assay intended for the prediction of respiratory sensitisation potential of airborne chemicals (including particulate matter and nano-materials). The method consists of a 3D in vitro system based on human cells cultured at the air-liquid interface (ALI). This system mimics the alveolar-capillary barrier and allows to assess substances with both low and high molecular weight (e.g. pollen or house dust mites).","stepStage":"Submission > Assessment of presubmission","workflowStep":"Submission","workflowStage":"Assessment of presubmission","topic":"Sensitisation","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Monday, June 21, 2021 - 14:21","lastUpdateDate":"2021-06-21","stage":"Test Submission","status":"Ongoing","code":"SUB_ASSESS","applicationDomain":"Mixed/general toxicology","endpoint":"Sensitisation — unspecified","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_ASSESS","bottlenecks":"Validation readiness / evidence package","bottleneckCount":"1","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Cosmetics","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2011-12","shortName":"2-TA","title":"Two-tiered approach to determine the skin sensitising capacity and potency of chemicals","organisation":"EURL ECVAM - European Union","description":"The 2-TA tiered approach addresses the capacity and the potency of a potentially sensitizing chemical on acute exposure to the chemical. Human-derived epidermal-like cells (NCTC2544) are used to distinguish skin sensitizers from respiratory sensitizers and non-sensitizers (including irritants). This is the so-called 1st Tier or also called 'NCTC-assay'. The 2nd Tier or also called 'EE-potency assay' is used to estimate the potency of the identified sensitizing chemical. Human reconstituted epidermal skin-equivalents are used in this step. The NCTC-assay is based on the effects of skin sensitizing chemicals on the production of pro-inflammatory intracellular IL-18 by human-derived NCTC2544 keratinocytes. The EE-assay is based on the inverse correlation between potency of a sensitizer and the viability of a human reconstituted epidermal model as determined by the MTT test and IL- 1 alpha release into the culture medium.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Sensitisation","yearReceived":"2011","generalComments":"Submission closed because an improved version of the test method has been submitted under TM2012-05","protocolSop":"","lastUpdate":"Wednesday, November 11, 2020 - 10:26","lastUpdateDate":"2020-11-11","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay; Integrated testing strategy/battery","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2004-07","shortName":"BALB/c 3T3 CTA","title":"In vitro BALB/c 3T3 Cell Transformation Assay","organisation":"EURL ECVAM - European Union","description":"The in vitro CTA using the BALB/c 3T3 cell line is aimed at detecting the carcinogenic potential of chemicals. The assay is based on the change of the phenotypic features of cells undergoing the first steps of the conversion from normal cells to neoplastic-like cell foci with oncogenic properties. Carcinogenesis is a complex multistage process by which normal cells are transformed into cancer cells characterised by an accumulation of changes at the cellular, genetic and epigenetic level. In vitro CTAs such as the BALB/c 3T3 CTA have been shown to recapitulate a multistage process that closely models some stages of in vivo carcinogenesis. Cell transformation in all the systems studied to-date involves changes at each stage in order for progression to the next stage in the transformation process to occur. A minimum of four phenotypic stages appears to be involved in cell transformation. These include (from primary to fully malignant cells): 1) a block in cellular differentiation, 2) acquisition of immortality, characterised by unlimited lifespan, an aneuploidy karyotype and a decreased genetic stability; 3) acquisition of tumorigenicity, which is closely associated with the in vitro phenotypes of foci formation, anchorage independent growth in semi-solid agar and autocrine growth factor production; 4) full malignancy, including metastasis when the cells are injected into a suitable host, supporting the biological relevance of in vitro transformation to in vivo carcinogenicity. The assay is based on the change of the phenotypic features of transformed foci undergoing the first steps of the conversion from normal cells to neoplastic-like cells with oncogenic properties.","stepStage":"Regulatory acceptance/Standards > Stopped","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Stopped","topic":"Carcinogenicity","yearReceived":"2004","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=137","lastUpdate":"Monday, October 26, 2020 - 15:26","lastUpdateDate":"2020-10-26","stage":"Regulatory assessment","status":"Rejected","code":"REG_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Carcinogenicity","methodology":"In vitro","specificMethodologies":"Cell transformation assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_STOP","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Standardisation / regulatory adoption","bottleneckCount":"3","animalUseImpact":"Reduction","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2000-01","shortName":"CFU-GM","title":"The Colony Forming Unit-Granulocyte/Macrophage Assay for predicting acute neutropenia in humans","organisation":"EURL ECVAM - European Union","description":"The CFU-GM in vitro test detects the direct adverse effects of xenobiotics on the proliferative capacities of the progenitors and should be able to predict the exposure level of xenobiotics that would cause clinical neutropenia after onset acute exposure. The assay is used in a screening mode to predict chemical induced myelosuppression, one of the haematological parameters to be considered for the assessment of the haematotoxic potential of chemical compounds of various kinds.","stepStage":"Submission > Assessment finalised","workflowStep":"Submission","workflowStage":"Assessment finalised","topic":"Acute toxicity","yearReceived":"2000","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=101","lastUpdate":"Saturday, October 24, 2020 - 09:03","lastUpdateDate":"2020-10-24","stage":"Validation","status":"Finalised","code":"SUB_FINAL","applicationDomain":"Pharmaceutical","endpoint":"Acute toxicity","methodology":"In vitro","specificMethodologies":"Colony-forming assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_PEER_FINAL","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Reduction","applicationDomainExpert":"Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2009-07","shortName":"Zebrafish assay","title":"Automated screening to detect cardiotoxicity in zebrafish","organisation":"EURL ECVAM - European Union","description":"Zebrafish embryos (48hpf) are exposed in a HTS system to test compounds and effects on heart rate, arrhythmia and death/fibrilation are automatically detected. The aim of the method is to identify compounds that induce arrhythmia and consequently present a potential risk of QT interval prolongation. In addition, compounds that induce non zERG-related cardiotoxicity should be identified, to be classified as generally cardiotoxic. The test is inteneded as screening method to detect cardiotoxicity of products in early stages of drug development.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Cardiotoxicity","yearReceived":"2009","generalComments":"Further information was requested, but was not provided.","protocolSop":"","lastUpdate":"Wednesday, October 21, 2020 - 16:22","lastUpdateDate":"2020-10-21","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Pharmaceutical","endpoint":"Cardiotoxicity","methodology":"In vivo","specificMethodologies":"HTS; Embryo/developmental model","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert reconciliation: an earlier BU review, based on the TSAR lifecycle record alone, classified TM2009-07 as case_study_method = 0 with Three_R_category = Unknown. The current user-approved review additionally incorporates post-TSAR exact-method evidence from Letamendia et al. (2012), which developed and validated the automated high-throughput zebrafish cardiotoxicity platform using 48-hpf embryos and reference compounds. Under the current case-study definition (material progression outside TSAR), case_study_method is therefore set to 1. Core methodology is In vivo and the application domain is Pharmaceutical. Three-R impact is coded as Reduction because the whole-organism embryo screen can reduce reliance on mammalian in vivo studies during early drug-development screening but is not itself a non-animal replacement. External_evidence_step_stage remains blank because no later formal EURL ECVAM/OECD lifecycle milestone for this exact cardiotoxicity method was identified.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"No external update recorded","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM1995-01","shortName":"TER","title":"Rat skin transcutaneous electrical resistance test","organisation":"EURL ECVAM - European Union","description":"The assay is based on determining the effects of a chemical on the electrical resistance of rat skin (i.e. TER). A second endpoint is the ability of a dye to penetrate through rat skin following exposure to a chemical. The test can be used to identify potential corrosive chemicals or mixtures. It can also be used to identify chemicals that are non-corrosive when used in combination with other methods. Evidence indicates that TER measurements are predictive of severe cutaneous effects in vivo. The (later) addition of the dye to the test reduces false positives.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin Corrosion","yearReceived":"1995","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=115","lastUpdate":"Monday, October 19, 2020 - 14:53","lastUpdateDate":"2020-10-19","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Skin corrosion","methodology":"Ex vivo","specificMethodologies":"Ex vivo/tissue-based assay; Barrier/permeability/transport assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert review: TER already reached regulatory adoption within the complete TSAR lifecycle, including completed validation, peer review, ECVAM recommendation and OECD TG 430 adoption. Accordingly, case_study_method remains 0 and NEW_STEP_STAGE remains REG_ADOPT. External OECD evidence independently confirms REG_ADOPT. Methodology is refined to include both an ex vivo/tissue-based assay and a barrier/permeability/transport readout. The previously flagged applicability issue is treated as a historical limitation resolved during method development rather than an unresolved bottleneck of the adopted method.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2008-06","shortName":"CAMVA","title":"Chorioallantoic membrane vascular assay","organisation":"EURL ECVAM - European Union","description":"The CAMVA assay assesses the possible detrimental effects which potential eye irritants have on the blood vessels of the embryo's CAM (chorioallantoic membrane). In preparation of the test a small opening is cut into the shell of the egg four days after fertilization and a small amount of albumen is removed to allow optimal growth of the CAM. The opening is resealed and the eggs are incubated for a further 6 days. The age of the CAM used in the test has been limited to 10 days in order to comply with the legislation in the EU countries which prohibits experiments on chick embryos that are older than 10 days (Bagley et al., 1992, 1994). On day 10 the test substance is applied directly onto a small area of the CAM. After exposure for 30 minutes the eggs are examined for any vascular change in the CAM, e.g. haemorrhaging, hyperaemia (capillary injection) or the occurrence of vessels devoid of blood flow (ghost vessels). The concentration of test materials eliciting such damaging effects in 50 % of the eggs is calculated as toxicological endpoint.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Serious eye damage/Eye irritation","yearReceived":"2008","generalComments":"On hold-pending further information (under external validation)","protocolSop":"","lastUpdate":"Friday, October 16, 2020 - 11:13","lastUpdateDate":"2020-10-16","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"Ex vivo","specificMethodologies":"Embryo/developmental model","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert review: CAMVA is retained as case_study_method = 0 because the key external validation work substantially predates the 2008 TSAR submission and later publications mainly demonstrate continued use rather than a new formal lifecycle milestone. Core coding remains Ex vivo with Embryo/developmental model. Application domain is broadened to Cosmetics; Industrial chemicals. Validation evidence supports reproducibility/transferability, predictive-performance, applicability and product/matrix bottlenecks. External_evidence_step_stage remains blank.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"No external update recorded","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Applicability domain; Product / matrix qualification; Programme prioritisation / route selection","bottleneckCount":"6","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2010-04","shortName":"IMOLA-IVD","title":"The IMOLA-IVD test method for eye irritation testing","organisation":"EURL ECVAM - European Union","description":"IMOLA-IVD is an automated platform for monitoring the vitality of living cells based on the Intelligent Mobile Lab In Vitro Diagnostics. It can detect changes in cellular metabolism after toxic exposure. It is an automatisation of the Cytosensor Microphysiometer (CM) toxicity test that was developed for the labeling of chemicals for eye corrosion/irritation and is an alternative to the Draize rabbit eye irritation test. The IMOLA-IVD consists of three elements: (i) the sensor system, (ii) the pumping and switching of fluids, (iii) a program which runs the protocol according to the CM toxicity test protocol and collects the data.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Serious eye damage/Eye irritation","yearReceived":"2010","generalComments":"On hold-pending further information","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 12:57","lastUpdateDate":"2026-04-02","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Metabolic activity sensor assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert review: TM2010-04 remained Submission > Stopped in TSAR, but the exact IMOLA-IVD eye-irritation application progressed outside TSAR through automated transfer of the Cytosensor protocol, additional impedance readouts and prediction-model development. This supports case_study_method = 1. No later formal validation, peer-review or OECD Test Guideline adoption of IMOLA-IVD itself was identified, so External_evidence_step_stage remains blank. Three-R impact is coded as Reduction because the underlying Cytosensor approach functions as a partial replacement within a tiered strategy rather than a complete stand-alone replacement for the full Draize eye test.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"No external update recorded","bottlenecks":"Validation readiness / evidence package; Predictive performance; Applicability domain; Programme prioritisation / route selection; Standardisation / regulatory adoption","bottleneckCount":"5","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2009-10","shortName":"VitroDerm","title":"THOR VitroDerm RhE test method for skin irritation testing","organisation":"EURL ECVAM - European Union","description":"The Thor Vitroderm model is a 3-d reconstructed human epidermis seeded on a polycarbonate filter and cultured at the air liquid interface. After 17 days, highly differentiated and stratified epidermis has developed which comprises a proliferating basal cell layer of columnar epithelial cells, giving rise to morphologically distinct suprabasal spinous and granular layers and a functional stratum corneum. The purpose of the test method is for the prediction of acute skin irritation of chemicals applied topically to the apical surface of a reconstructed human epidermal model, by the measure of cytotoxicity by the MTT viability assay. The principle of the RHE model test is based on the premise that irritant chemicals are able to penetrate the stratum corneum and are cytotoxic to the cells in the underlying layers. Cell viability is measured by dehydrogenase conversion of the vital dye MTT [3-(4,5-Dimethylthiazol-2-yl)-2,5-diphenyltetrazolium bromide, Thiazolyl blue; EINECS number 206-069-5, CAS number 298-93-1)] into a blue formazan salt that is quantitatively measured after extraction from tissues.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin irritation","yearReceived":"2009","generalComments":"On hold-pending further information","protocolSop":"","lastUpdate":"Friday, October 16, 2020 - 11:10","lastUpdateDate":"2020-10-16","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics","endpoint":"Skin irritation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Expert review: TM2009-10 remained Submission > Stopped in TSAR after a full submission was invited but not received. Later VitroDerm platform development and implementation support case_study_method = 1, but no later formal validation, peer-review or OECD adoption milestone for the exact submitted THOR VitroDerm method was identified; External_evidence_step_stage remains blank.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"No external update recorded","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2011-02","shortName":"SenCeetox","title":"In vitro Method for Identifying Skin Sensitisers Combining Peptide Binding with ARE/EpRE Mediated Gene Expression in Human Skin Cells","organisation":"EURL ECVAM - European Union","description":"The SenCeeTox is an in vitro approach in which data on chemical reactivity towards Glutathione (GSH), gene expression profiling and cell viability are generated in order to identify the sensitisation potential of chemicals and to assign them into potency categories. The method is addressing two biological mechanisms: a) the reactivity towards proteins and b) the activation of the ARE/EpRE signaling pathways in human keratinocytes, both of which are considered to be relevant steps in the inductions phase of skin sensitisation. Protein reactivity is measured in a cell-free system whereas gene induction is measured by qRT-PCR using mRNA isolated from 3D human epidermis models. Viability of cells is measured in parallel with the MTT assay. Such parameters are used in combination in a weighted algorithm to derive an in vitro toxicity index (IVTI) that is then used to predict a sensitiser potency category.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin sensitisation","yearReceived":"2011","generalComments":"On hold-pending further information","protocolSop":"","lastUpdate":"Friday, October 16, 2020 - 10:57","lastUpdateDate":"2020-10-16","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro; In chemico; Mixed","specificMethodologies":"Omics; Organoid/3D tissue model; Cytotoxicity/cell viability assay; Chemical reactivity assay; Integrated testing strategy/battery","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Expert review: SenCeeTox remained Submission > Stopped in TSAR, but subsequent work included inter-laboratory transfer, systematic Cosmetics Europe evaluation and medical-device extract applications. This supports case_study_method = 1. No later formal validation, peer-review or OECD Test Guideline adoption was identified, so External_evidence_step_stage remains blank. Methodology was corrected to remove reporter-gene, AI/ML and binding labels not specifically supported by the described assay and to retain the combined in vitro/in chemico battery.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"No external update recorded","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Product / matrix qualification; Programme prioritisation / route selection","bottleneckCount":"5","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2012-05","shortName":"RHE IL-18","title":"RHE IL-18 potency test for skin sensitization","organisation":"EURL ECVAM - European Union","description":"The RHE IL-18 potency test for skin sensitization is an integration of two test methods covering epidermal inflammation and cytotoxicity with the aim to measure skin sensitizing potential and potency. It represents an update of the two-tiered approach, (2-TA; TM-2011-12). The RHE-IL18 allows the quantification of the two readouts (IL-18 release and cytotoxicity) in the same test system (Reconstructed human Epidermis (RhE)). The skin sensitisation potential is tested based on the quantification of the release of intracellular pro-inflammatory IL-18 in keratinocytes by ELISA. Skin sensitiser potency is measured as inverse correlation of cell viability (expressed as EC50 value). RHE IL-18 can be performed using commercially available RhE as well as in-house developed RhE.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin sensitisation","yearReceived":"2012","generalComments":"Invitation to send a full submission","protocolSop":"","lastUpdate":"Friday, October 16, 2020 - 10:56","lastUpdateDate":"2020-10-16","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay; Immunoassay/flow cytometry","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Expert review: TM2012-05 remained Submission > Stopped in TSAR, but subsequent RhE IL-18 work continued through prediction-model refinement, broader RhE evaluation, potency modelling and application to metal sensitizers. This supports case_study_method = 1. No later formal validation, peer-review or OECD Test Guideline adoption was identified, so External_evidence_step_stage remains blank.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"No external update recorded","bottlenecks":"Validation readiness / evidence package; Predictive performance; Applicability domain; Product / matrix qualification; Programme prioritisation / route selection; Standardisation / regulatory adoption","bottleneckCount":"6","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2008-13","shortName":"Skin absorption RHE","title":"Skin absorption based on RHE models","organisation":"EURL ECVAM - European Union","description":"The mechanistic principles for the uptake of chemicals into and through human skin and reconstructed human epidermis (RHE) are almost identical, the stratum corneum being the major barrier. Regarding morphology, immunohistochemistry and lipid composition RHE at current state is close to human epidermis. In addition, blood circulation does not play a role until the corium. In contrast to the skin of furry animals, in humans the shunt pathway of absorption via the hair follicles is of little relevance due to the low number. They are absent in RHE. The endpoints assessed in the test method are the permeation of the respective test substance through RHE and skin into the receptor medium as quantified by cumulated amount, μg/cm² and %, after 6 and 24 h. Using the infinite dose approach (282.5 μ l aqueous solution of the test substance per cm² skin) permeation coefficient Papp (cm/s) and lag-time (h) as further endpoints are derived from the linear part of the respective absorption curves by linear regression. In addition, the finite dose approach (10 μl of the test substance per cm² skin) was used to quantify the penetration of the test substance into the skin.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin absorption/penetration","yearReceived":"2008","generalComments":"On hold-pending further information","protocolSop":"","lastUpdate":"Friday, October 16, 2020 - 11:01","lastUpdateDate":"2020-10-16","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Skin absorption/penetration","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Barrier/permeability/transport assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Expert review: TSAR records TM2008-13 as Submission > Stopped, but external evidence documents a formal multi-laboratory validation of RHE skin-absorption models. This supports case_study_method = 1 and External_evidence_step_stage = VAL_FINAL. The external validation did not establish broad regulatory adoption; performance/applicability limitations remained, particularly higher RHE permeability and evidence focused mainly on aqueous solutions.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_FINAL","bottlenecks":"Predictive performance; Applicability domain; Product / matrix qualification; Programme prioritisation / route selection","bottleneckCount":"4","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals; Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2011-08","shortName":"DC-SRM","title":"Multiplexed SRM (Selected Reaction Monitoring) Mass Spectrometric Assays for Targeted Quantification of Skin Sensitization Biomarkers in Dendritic Cell Models","organisation":"EURL ECVAM - European Union","description":"Multiplexed SRM (Selected Reaction Monitoring) is a Mass Spectrometric Assays for Targeted Quantification of Skin Sensitization Biomarkers in Dendritic Cell (DC) Models. The test is designed for dichotomous classification (Yes/No). The method comprises steps of contacting a relevant DC model, preferentially MUTZ-3 progenitor cells, with potential sensitizers, non-sensitizers and solvent controls, and measuring the change in protein expression using targeted mass spectrometric assays. MUTZ-3 are a human myelomonocytic cell line which was identified as the human dendritic cell (DC)-like cell line that is closest to human monocyte derived DC. The protein biomarker model for skin sensitization is based on detailed proteomic analysis of relevant cell lines. A panel of 15 most promising biomarkers allows discriminating between sensitizers and non-sensitizers. Additional 10 biomarkers allow to identify respiratory sensitizers in MUTZ-3 cells","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Sensitisation","yearReceived":"2011","generalComments":"On hold-pending further information","protocolSop":"","lastUpdate":"Friday, October 16, 2020 - 10:50","lastUpdateDate":"2020-10-16","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Sensitisation — unspecified","methodology":"In vitro","specificMethodologies":"Omics; Analytical chemistry readout; Biomarker/DNA damage assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Expert review: TSAR records DC-SRM as Submission > Stopped in 2020 because no further communication was received after additional information was requested. Outside TSAR, the assay progressed as SensiDerm™ TMT-SRM and was reported as pre-validated in two analytical laboratories. This supports case_study_method = 1 for progression beyond TSAR, but no later formal validation, peer-review or regulatory-adoption milestone was identified; External_evidence_step_stage therefore remains blank.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"No external update recorded","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2010-05","shortName":"IVM","title":"Bovine Oocyte Maturation Assay","organisation":"EURL ECVAM - European Union","description":"The bovine in vitro maturation test assesses oocyte maturation. The method is based on the use of immature oocytes from bovine animals. The physiology of the bovine reproductive cycle is more similar to humans than conventional laboratory animals for a number of reproductive parameters including kinetics of oocyte growth, oocyte size, mechanisms of ovulation and maturation, timing of fertilisation and first cleavage, kinetics of pre- and post-implantation development, mechanisms of gastrulation, cell cycle and gestation length. Finally, at the genetic level, the homologies between human and cattle are higher than human and rodent, The toxicological endpoint evaluated is the completion of meiosis up to the metaphase II stage, which is reached after 24h in in vitro culture. The analysis is based on microscopic inspection. Matured oocytes are characterised by the extrusion of the first polar body associated to the second metaphase stage. The assay investigates the potential for interaction of a chemical substance with meiosis and as such investigates events within an adverse outcome pathway (AOP) associated with perturbation of fertilisation. Such assay could be used within an Integrated Testing Strategy (ITS) or Integrated Approaches to Testing and Assessment (IATA) for identification of reproductive toxicants.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Reproductive toxicity, In vitro fertilisation","yearReceived":"2010","generalComments":"On hold-pending further information","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=129","lastUpdate":"Friday, October 16, 2020 - 10:48","lastUpdateDate":"2020-10-16","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity","methodology":"In vitro","specificMethodologies":"Embryo/developmental model","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert review: TSAR records the submission pathway as stopped in 2020 after no full submission followed the 2011 invitation. Post-TSAR evidence shows continued scientific development of the bovine oocyte maturation approach within FREIA/EURION, including expanded female reproductive endocrine-disruption endpoints. This is therefore flagged as a progression-beyond-TSAR case study. No later formal validation, peer-review or regulatory-adoption milestone was identified, so External_evidence_step_stage remains blank. The assay itself is coded as an in vitro embryo/developmental model rather than an integrated approach; its potential use within ITS/IATA is contextual rather than a primary technical domain.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"No external update recorded","bottlenecks":"Validation readiness / evidence package; Predictive performance; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2008-02","shortName":"SkinEthic RHE","title":"Skinethic Skin Irritation Test-42bis","organisation":"EURL ECVAM - European Union","description":"The SkinEthic™ Skin Irritation Test (42 minutes application + 42 hours post-incubation) is designed for the prediction of acute skin irritation potential of chemicals by measurement of their cytotoxic effect, as reflected by MTT assay, on the Reconstructed Human Epidermis (RHE).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin irritation","yearReceived":"2008","generalComments":"Validation finalised, OECD Test Guideline / EU Test Method available","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=135","lastUpdate":"Monday, October 12, 2020 - 09:03","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics; Pharmaceutical; Industrial chemicals","endpoint":"Skin irritation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: SkinEthic RHE completed external catch-up validation and ESAC peer review in 2008 and was subsequently incorporated into OECD TG 439. Historical evidence-readiness issues included requested retesting of diethyl phthalate, additional statistical analysis, formal submission corrections, and limitations in study planning/blinding/training documentation. Predictive-performance and applicability-domain limitations were documented, while MTT reproducibility and transferability were adequate. TSAR itself records the 2010 OECD TG 439 adoption; therefore this method is not flagged as a progression-beyond-TSAR case study.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package; Predictive performance; Applicability domain","bottleneckCount":"3","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2008-01","shortName":"Modified EpiDerm SIT","title":"Modified EpiDerm Skin Irritation Test for Hazard Identification and Labelling of Chemicals According to EU Classification System","organisation":"EURL ECVAM - European Union","description":"The Modified EpiDerm SIT is an in vitro method that has been developed and optimized to predict the skin irritation potential of chemicals according to EU classification system. The method utilizes a commercially available three-dimensional tissue construct EpiDermTM (EPI-200) produced by MatTek Corporation (US). The test consists of a topical exposure of the neat test article to a human reconstituted epidermis model for 60 min. During the 60 minute exposure period, the treated epidermis is first left at room temperature for 25 minutes and subsequently incubated for 35 min at 37°C. At the end of exposure, the test article is removed from the epidermis and the tissue is incubated for an additional 42h to express the resulting damage. Cell viability is measured by dehydrogenase conversion of MTT [(3-4,5-dimethyl thiazole 2-yl) 2,5-diphenyltetrazoliumbromide], taken up by cell mitochondria, into a blue formazan salt that is quantitatively measured after extraction from tissues. Relative tissue viability is determined against the concurrent negative control-treated tissues. Tissues treated with skin irritants (R38) are expected to show a relative viability of less than 50% while non-irritants show a viability greater than 50%. A concurrent positive control is used with each assay. The modified EpiDerm SIT has been adopted together with EpiSkinTM (SM), SkinEthic™ RHE, LabCyte EPI-MODEL24 SIT test methods, and included in OECD TG 439 which describes an in vitro procedure that may be used for the hazard identification of irritant chemicals (substances and mixtures) in accordance with the UN Globally Harmonized System of Classification and Labelling (GHS) Category 2.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin irritation","yearReceived":"2008","generalComments":"Validation finalised, OECD Test Guideline / EU Test Method available","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=138","lastUpdate":"Monday, October 12, 2020 - 09:03","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics; Pharmaceutical; Industrial chemicals","endpoint":"Skin irritation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: TSAR source-copy lifecycle fields retain Peer-review > Finalised / VAL_PEER_FINAL. The TSAR method record documents OECD TG 439 adoption in July 2010, and current OECD TG 439 continues to include EpiDerm SIT as a validated reference method. External lifecycle recorded as REG_ADOPT.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Predictive performance; Applicability domain","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2006-02","shortName":"Ocular Irritection","title":"Ocular Irritection","organisation":"EURL ECVAM - European Union","description":"The Ocular Irritection test method addresses the eye irritation and serious eye damage endpoint. It intends to identify chemicals potentially inducing eye irritation and/or serious eye damage on the basis of the United Nations (UN) Global Harmonized Systems for classification and labelling (GHS), as well as those not inducing ocular toxicity. The test system is composed of a macromolecular reagent containing a mixture of proteins and glycoproteins, carbohydrates, lipids and low molecular weight components. After rehydration, this reagent forms a macromolecular matrix, which mimics the cornea. The test chemical is applied on a membrane disc which delivers it to the matrix. Chemicals being ocular toxic will induce a turbidity of the macromolecular matrix by interacting with its components and disrupting its conformation. The Ocular Irritection protocol is intended to be potentially used for the prediction of acute eye irritation and serious eye damage in regulatory safety testing under the UN GHS, REACH, EU Classification, Labelling and Packaging of substances and mixtures (CLP) or Cosmetic Directive for chemicals. Currently, the sequential TD and BU approaches are considered for taking place in a wider strategy such as an Integrated Approach on Testing and Assessment (IATA). This IATA would be similar to the already validated one for skin irritation and corrosion. If validated—e.g., at the OECD—this ocular toxicity strategy may be included in a revised version of the \"REACH Guidance on Information Requirements and Chemical Safety Assessment\" published by ECHA.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Serious eye damage/Eye irritation","yearReceived":"2006","generalComments":"Revised Test Submission Template on the Ocular Irritection® test method proposed for Peer Review","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=157","lastUpdate":"Monday, October 12, 2020 - 09:08","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Eye irritation/Serious eye damage","methodology":"In chemico","specificMethodologies":"Binding/interaction assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package; Predictive performance; Applicability domain; Mechanistic relevance; Product / matrix qualification; Regulatory relevance / integration; Standardisation / regulatory adoption","bottleneckCount":"7","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2005-04","shortName":"EpiSkin™ - RHE","title":"Reconstructed Human Epidermis Model Test","organisation":"EURL ECVAM - European Union","description":"The EpiSkin™ model is a three dimensional reconstructed human epidermis that, once established, comprises of a main basal, supra basal, spinous and granular layers and a functional stratum corneum (the outer barrier layer of skin). The use of the model specifically for skin irritation testing involves the topical application of a test chemical followed by an assessment of cell viability, and specifically cytotoxicity (as measured via the MTT assay). Reductions in cell viability are then expressed as a % of the negative control. The % reduction is then used to predict the irritation potential of a chemical. A substance is considered to be irritating to skin (i.e. categorised as R38) if tissue viability after exposure and post incubation (see protocol, below) is less than or equal to 50%. Cell viability above 50% is considered a marker of a chemical being a non-irritant.","stepStage":"Recommendation > Not applicable","workflowStep":"Recommendation","workflowStage":"Not applicable","topic":"Skin irritation","yearReceived":"2005","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=131","lastUpdate":"Monday, October 12, 2020 - 09:09","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Not applicable","code":"REC_NA","applicationDomain":"Mixed/general toxicology","endpoint":"Skin irritation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Expert review: later authoritative evidence confirms regulatory adoption under OECD TG 439. In the 2025 update of TG 439, EpiSkin was removed as an available method because the model has not been commercially available since December 2024. This is treated as a post-adoption access/implementation barrier and does not reverse the historical REG_ADOPT lifecycle stage; previously generated EpiSkin data remain covered by OECD Mutual Acceptance of Data.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain; Access / implementation","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2009-13","shortName":"CryoHeps","title":"Cytochrome P450 (CYP) enzyme induction in vitro method using the cryopreserved human hepatocytes","organisation":"EURL ECVAM - European Union","description":"The human cytochrome P450 (CYP) enzyme induction method assesses the potential of test chemicals to induce the activity of three CYP enzymes (CYP1A2, CYP2B6 and CYP3A sub-family) in cryopreserved primary human hepatocytes. At the molecular level, CYP enzyme induction is a process controlled by a set of nuclear receptors associated with downstream signal transduction pathways. Experimentally, at the end of cell exposure to the test chemical, a cocktail of three specific CYP enzymatic substrate probes is applied to the cells and CYP enzyme induction is assessed through the measurement of of the specific metabolites formation by CYP1A2, 2B6 and 3A sub-family by analytical liquid chromatography/mass spectrometry (LC/MS) technique. The CYP enzyme induction in vitro methods (see also TM2009-14) are reliable and relevant methods for the generation of human metabolism data in animal-free testing strategies assessing adverse health effects of xenobiotics.","stepStage":"Regulatory acceptance/Standards > Stopped","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Stopped","topic":"Toxicokinetics","yearReceived":"2009","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=193","lastUpdate":"Tuesday, October 20, 2020 - 14:04","lastUpdateDate":"2020-10-20","stage":"Regulatory assessment","status":"Rejected","code":"REG_STOP","applicationDomain":"Pharmaceutical","endpoint":"Toxicokinetics","methodology":"In vitro","specificMethodologies":"Analytical chemistry readout; Enzyme/biochemical activity assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert interpretation: CryoHeps is an in vitro CYP-induction assay using cryopreserved primary human hepatocytes, with functional CYP1A2, CYP2B6 and CYP3A activity quantified through LC/MS measurement of probe-substrate metabolites. Detailed methodology is corrected to Analytical chemistry readout; Enzyme/biochemical activity assay; the Binding/interaction label is removed because receptor binding is not the measured assay endpoint. The method completed EURL ECVAM validation and ESAC peer review, but primary-hepatocyte donor and batch variability resulted in lower reproducibility and poorer standardisability than the parallel HepaRG system. OECD therefore prioritised the HepaRG route for Test Guideline development and stopped the CryoHeps-specific route. case_study_method = 0 and External_evidence_step_stage = REG_STOP.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_STOP","bottlenecks":"Reproducibility / transferability; Programme prioritisation / route selection; Access / implementation; Standardisation / regulatory adoption","bottleneckCount":"4","animalUseImpact":"Replacement","applicationDomainExpert":"Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2007-01","shortName":"Epics SCT","title":"Epidermal Skin Corrosion Test 1000","organisation":"EURL ECVAM - European Union","description":"The EpiCS (previously called EST-1000) Skin Corrosion Test (SCT) can be used to assess the potential of chemicals to cause skin corrosion. The epiCS model is a reconstructed epidermis consisting of proliferating and differentiating keratinocytes. The test is based on the notion that skin corrosion is in part due to cytotoxic effects of chemicals. As such, it involves the exposure of the cells to test chemicals and subsequent determination of cytotoxicity via the MTT assay. The MTT assay is used to determine cytotoxicity, which is then expressed as a % of the negative control. A positive control is also included in the assay. The test is available as a commercial kit.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin Corrosion","yearReceived":"2007","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:07","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Skin corrosion","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Expert interpretation: epiCS SCT (formerly EST-1000) is an in vitro reconstructed-human-epidermis skin-corrosion assay in which tissue viability after chemical exposure is quantified using the MTT assay. The existing detailed methodology coding of Organoid/3D tissue model; Cytotoxicity/cell viability assay is retained. External validation and ESAC peer review demonstrated adequate reliability and predictive capacity, and the method subsequently entered OECD TG 431 and remains included in the current guideline. The automatically derived applicability-domain signal is removed because the associated Recommendation 'Not applicable' event does not document a method-specific lifecycle bottleneck. Although the derived TSAR snapshot remains at Recommendation > Not applicable, the full TSAR event history documents a successful formal hand-off to the OECD Test Guidelines Programme, with TG 431 revision initiated in 2012 and the updated guideline incorporating epiCS adopted in 2016. This progression beyond the snapshot stage supports case_study_method = 1 and External_evidence_step_stage = REG_ADOPT. No documented bottleneck identified.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM1999-05","shortName":"ToBI TET","title":"Toxin Binding Inhibition test for batch potency testing of tetanus vaccines for human use","organisation":"EURL ECVAM - European Union","description":"The ToBI TET measures antibody levels against erysipelas in the serum of guinea pigs immunised with tetanus vaccine for human use. It is carried out for vaccine batch release to demonstrate the tested batch complies with the requirements set in the marketing authorisation for the given vaccine.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Quality control of vaccines","yearReceived":"1999","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:19","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Pharmaceutical","endpoint":"Vaccine quality control","methodology":"Ex vivo","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay","review":"Expert-reviewed","threeR":"Refinement","literature":"Complete","verificationNote":"Expert review: ToBI TET is an ex vivo serological potency method for human tetanus vaccines in which tetanus antitoxin levels are measured in serum from immunised guinea pigs using a toxin-binding inhibition immunoassay. Application_domain is corrected from Food safety to Pharmaceutical. The method retains guinea-pig immunisation but replaces the severe lethal/paralytic toxin-challenge component; under the project 3R convention this is classified as Refinement rather than full Replacement. Formal validation, ESAC peer review and European Pharmacopoeia adoption were completed, with inclusion in Ph. Eur. 2.7.8 in March 2003. The 2026 technical revision of 2.7.8 represents maintenance of an already adopted standard and does not constitute uncaptured exact-method lifecycle progression; therefore case_study_method remains 0 and External_evidence_step_stage is REG_ADOPT. No material lifecycle bottleneck was identified after full evidence review. The source TSAR description appears to contain an erroneous reference to “erysipelas”; the source-snapshot field is preserved unchanged.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Refinement","applicationDomainExpert":"Pharmaceutical / human medicines; Veterinary medicines / animal health","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM1999-04","shortName":"ELISA TET","title":"ELISA test for batch potency testing of tetanus vaccines for human use","organisation":"EURL ECVAM - European Union","description":"The ELISA TET measures antibody levels against tetanus in the serum of guinea pigs immunised with tetanus vaccine for human use. It is carried out for vaccine batch release to demonstrate the tested batch complies with the requirements set in the marketing authorisation for the given vaccine.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Quality control of vaccines","yearReceived":"1999","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:20","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Pharmaceutical","endpoint":"Vaccine quality control","methodology":"Ex vivo","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay","review":"Expert-reviewed","threeR":"Refinement","literature":"Complete","verificationNote":"Expert review: ELISA TET is an ex vivo serological potency method for human tetanus vaccines in which tetanus antitoxin levels are measured in serum from immunised guinea pigs using an ELISA immunoassay. Application_domain is corrected from Food safety to Pharmaceutical. The method retains guinea-pig immunisation but replaces the severe lethal/paralytic toxin-challenge component; under the project 3R convention this is classified as Refinement rather than full Replacement. Formal validation, ESAC peer review and European Pharmacopoeia adoption were completed, with inclusion in Ph. Eur. 2.7.8 in March 2003. Later technical maintenance of 2.7.8 does not constitute uncaptured exact-method lifecycle progression; therefore case_study_method remains 0 and External_evidence_step_stage is REG_ADOPT. No material lifecycle bottleneck was identified after full evidence review.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Refinement","applicationDomainExpert":"Pharmaceutical / human medicines; Veterinary medicines / animal health","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2002-02","shortName":"Cryo-WBT-IL1","title":"In Vitro Pyrogen Test using Human Cryopreserved Whole Blood/IL-1 Beta","organisation":"EURL ECVAM - European Union","description":"The In Vitro Pyrogen Test using Human Cryopreserved Whole Blood/IL-1 Beta Cryo-WBT-IL1) is a monocyte activation test (MAT) used to detect or quantify substances that activate human monocytes or monocytic cells to release pro-inflammatory cytokines, for example tumour necrosis factor alpha (TNFα), interleukin-1 beta (IL-1β) and interleukin-6 (IL-6). These cytokines have a role in fever pathogenesis. Consequently, the MAT can detect the presence of pyrogens in the test sample. The MAT is suitable, after a product-specific validation, as a replacement for the rabbit pyrogen test or the bacterial endotoxin test (Limulus amebocyte lysate assay).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Pyrogenicity","yearReceived":"2002","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=134","lastUpdate":"Monday, October 12, 2020 - 09:16","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Pharmaceutical","endpoint":"Pyrogenicity","methodology":"Ex vivo","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: Cryo-WBT-IL1 is an ex vivo monocyte-activation test using cryopreserved human whole blood with IL-1β as the inflammatory readout. Application_domain is corrected from Food safety to Pharmaceutical and Core_methodology from In vitro; Ex vivo; Mixed to Ex vivo. International validation demonstrated strong performance, while the 2006 ESAC assessment formally limited full validation to Gram-negative endotoxin-mediated pyrogenicity and required product-specific validation. Later European Pharmacopoeia developments broadened MAT implementation and ultimately supported complete removal of the rabbit pyrogen test, but product-specific suitability and interference assessment remain required. The method therefore retains applicability-domain and product/matrix-qualification bottleneck signals. The exact method had already reached regulatory adoption in the TSAR lifecycle, so case_study_method remains 0 and External_evidence_step_stage is REG_ADOPT.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain; Product / matrix qualification","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Pharmaceutical / human medicines; Medical devices","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2002-05","shortName":"WBT-IL6","title":"In Vitro Pyrogen Test using Human Whole Blood/IL-6","organisation":"EURL ECVAM - European Union","description":"The In Vitro Pyrogen Test using Human Whole Blood/IL-6(WBT-IL6) is a monocyte activation test (MAT) applied to detect or quantify substances that activate human monocytes or monocytic cells to release pro-inflammatory cytokines, for example tumour necrosis factor alpha (TNFα), interleukin-1 beta (IL-1β) and interleukin-6 (IL-6). These cytokines have a role in fever pathogenesis. Consequently, the MAT can detect the presence of pyrogens in the test sample. The MAT is suitable, after a product-specific validation, as a replacement for the rabbit pyrogen test or the bacterial endotoxin test (Limulus amebocyte lysate assay).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Pyrogenicity","yearReceived":"2002","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:16","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Pharmaceutical","endpoint":"Pyrogenicity","methodology":"Ex vivo","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: WBT-IL6 is an ex vivo monocyte-activation test using fresh human whole blood with IL-6 as the inflammatory readout. Application_domain is corrected from Food safety to Pharmaceutical and Core_methodology from In vitro; Ex vivo; Mixed to Ex vivo. ESAC confirmed scientific validation for Gram-negative endotoxin-mediated pyrogenicity while identifying insufficient evidence at that time for the complete broader pyrogen domain and requiring product-specific validation. Later European Pharmacopoeia development substantially broadened MAT implementation, while product-specific suitability and interference assessment remain required. Applicability-domain and product/matrix-qualification bottleneck signals are therefore retained. The method had already reached regulatory adoption in the TSAR lifecycle; case_study_method remains 0 and External_evidence_step_stage is REG_ADOPT.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain; Product / matrix qualification","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Pharmaceutical / human medicines; Medical devices","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2002-03","shortName":"MM6 IL6","title":"In Vitro Pyrogen Test using MonoMac 6 cells/IL-6","organisation":"EURL ECVAM - European Union","description":"The In Vitro Pyrogen Test using MonoMac 6 cells/IL-6 (MM6-IL6) is a monocyte activation test (MAT) applied to detect or quantify substances that activate human monocytes or monocytic cells (here the cell line MonoMac 6) to release pro-inflammatory cytokines, for example tumour necrosis factor alpha (TNFα), interleukin-1 beta (IL-1β) and interleukin-6 (IL-6). These cytokines have a role in fever pathogenesis. Consequently, the MAT can detect the presence of pyrogens in the test sample. The MAT is suitable, after a product-specific validation, as a replacement for the rabbit pyrogen test or the bacterial endotoxin test (Limulus amebocyte lysate assay).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Pyrogenicity","yearReceived":"2002","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:17","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Pharmaceutical","endpoint":"Pyrogenicity","methodology":"In vitro","specificMethodologies":"Immunoassay/flow cytometry","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: MM6 IL6 is an in vitro monocyte-activation test using the MonoMac 6 continuous monocytic cell line with IL-6 as the inflammatory readout. Application_domain is corrected from Food safety to Pharmaceutical; Core_methodology remains In vitro. ESAC confirmed scientific validation for Gram-negative endotoxin-mediated pyrogenicity while identifying insufficient evidence at that time for the complete broader pyrogen domain and requiring product-specific validation. Later European Pharmacopoeia development substantially broadened MAT implementation, while product-specific suitability and interference assessment remain required. Applicability-domain and product/matrix-qualification bottleneck signals are therefore retained. The method had already reached regulatory adoption in the TSAR lifecycle; case_study_method remains 0 and External_evidence_step_stage is REG_ADOPT.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain; Product / matrix qualification","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Pharmaceutical / human medicines; Medical devices","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2002-01","shortName":"WBT-IL1","title":"In Vitro Pyrogen Test using Human Whole Blood/IL-1 Beta","organisation":"EURL ECVAM - European Union","description":"The In Vitro Pyrogen Test using Human Whole Blood/IL-1 Beta (WBT-IL1) is a monocyte activation test (MAT) applied to detect or quantify substances that activate human monocytes or monocytic cells to release pro-inflammatory cytokines, for example tumour necrosis factor alpha (TNFα), interleukin-1 beta (IL-1β) and interleukin-6 (IL-6). These cytokines play a role in fever pathogenesis. Consequently, the MAT can detect the presence of pyrogens in the test sample. The MAT is suitable, after a product-specific validation, as a replacement of the rabbit pyrogen test or the bacterial endotoxin test (Limulus amebocyte lysate assay).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Pyrogenicity","yearReceived":"2002","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=133","lastUpdate":"Monday, October 12, 2020 - 09:17","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Pharmaceutical","endpoint":"Pyrogenicity","methodology":"Ex vivo","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: WBT-IL1 is an ex vivo monocyte-activation test using fresh human whole blood with IL-1β as the inflammatory readout. Application_domain is corrected from Food safety to Pharmaceutical and Core_methodology from In vitro; Ex vivo; Mixed to Ex vivo. ESAC confirmed scientific validation for Gram-negative endotoxin-mediated pyrogenicity while identifying insufficient evidence at that time for the complete broader pyrogen domain and requiring product-specific validation. Later European Pharmacopoeia development substantially broadened MAT implementation, while product-specific suitability and interference assessment remain required. Applicability-domain and product/matrix-qualification bottleneck signals are therefore retained. The method had already reached regulatory adoption in the TSAR lifecycle; case_study_method remains 0 and External_evidence_step_stage is REG_ADOPT.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain; Product / matrix qualification","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Pharmaceutical / human medicines; Medical devices","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2002-04","shortName":"PBMC-IL6","title":"In Vitro Pyrogen Test using Peripheral Blood Mononuclear Cells/IL-6","organisation":"EURL ECVAM - European Union","description":"The In Vitro Pyrogen Test using Peripheral Blood Mononuclear Cells/IL-6 (PBMC-IL6) is a monocyte activation test (MAT) applied to detect or quantify substances that activate human monocytes or monocytic cells to release pro-inflammatory cytokines, for example tumour necrosis factor alpha (TNFα), interleukin-1 beta (IL-1β) and interleukin-6 (IL-6). These cytokines have a role in fever pathogenesis. Consequently, the MAT can detect the presence of pyrogens in the test sample. The MAT is suitable, after a product-specific validation, as a replacement for the rabbit pyrogen test or the bacterial endotoxin test (Limulus amebocyte lysate assay).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Pyrogenicity","yearReceived":"2002","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:17","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Pharmaceutical","endpoint":"Pyrogenicity","methodology":"Ex vivo","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: PBMC-IL6 is an ex vivo monocyte-activation test using primary human peripheral blood mononuclear cells with IL-6 as the inflammatory readout. Application_domain is corrected from Food safety to Pharmaceutical and Core_methodology from In vitro; Ex vivo; Mixed to Ex vivo. ESAC confirmed scientific validation for Gram-negative endotoxin-mediated pyrogenicity while identifying insufficient evidence at that time for the complete broader pyrogen domain and requiring product-specific validation. Later European Pharmacopoeia development substantially broadened MAT implementation, while product-specific suitability and interference assessment remain required. Applicability-domain and product/matrix-qualification bottleneck signals are therefore retained. The method had already reached regulatory adoption in the TSAR lifecycle; case_study_method remains 0 and External_evidence_step_stage is REG_ADOPT.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain; Product / matrix qualification","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Pharmaceutical / human medicines; Medical devices","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2005-05","shortName":"THRESH FISH","title":"Threshold approach for acute fish toxicity testing","organisation":"EURL ECVAM - European Union","description":"The Threshold Approach for Acute Fish Toxicity testing is a tiered testing strategy and is based on the fact that the LC50/EC50 value of the most sensitive of the three test species (fish, algae and invertebrates) is commonly used for hazard and risk assessment and that fish is often not the most sensitive test species. When fish acute toxicity data need to be generated, the fish limit test as described in OECD TG 203 / C.1 should be carried out at a threshold concentration using far less fish than the full LC50 test. The threshold concentration corresponds to the lowest LC50/EC50 derived from reliable acute invertebrate (e.g. Daphnia, OECD TG202) and algae (e.g. OECD TG 201) data. If no fish mortality is observed at the threshold concentration, it demonstrates that that the fish is not the most sensitive test species. No further testing is required and the TC value can be used as LC50 fish (LC50 fish is greater than TC with 99% of confidence). If mortality occurs at the threshold concentration, a full LC50 test should be conducted.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Fish acute toxicity","yearReceived":"2005","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:09","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Environmental","endpoint":"Aquatic toxicity","methodology":"In vivo","specificMethodologies":"Integrated testing strategy/battery; In vivo reduction/refinement assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert review: THRESH FISH is a tiered in vivo acute fish toxicity strategy designed to reduce animal use by deriving a threshold concentration from algae and acute invertebrate toxicity data before performing a fish limit test. Core_methodology is corrected from Integrated approach; In vivo; Mixed to In vivo because integrated testing strategy/battery is a Specific_methodology architecture marker and is not a Core_methodology domain. Cytotoxicity/cell viability assay is removed from Specific_methodologies as it does not describe the method. ESAC endorsed the strategy as scientifically valid and estimated substantial reductions in fish use, followed by adoption as OECD Guidance Document 126. No material lifecycle bottleneck was identified. NEW_STEP_STAGE remains REG_ADOPT, case_study_method remains 0 and External_evidence_step_stage is REG_ADOPT.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Reduction","applicationDomainExpert":"Environmental; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM1998-03","shortName":"EpiDerm™","title":"EpiDerm™ skin corrosivity test","organisation":"EURL ECVAM - European Union","description":"The test method is based on the commercially available EpiDerm™ model, a reconstructed human epidermal model grown from human-derived epidermal keratinocytes which are cultured to form a multilayered and highly differentiated model of the human epidermis. The corrosivity potential of chemicals is assessed with the measurement of their citotoxic effects on EpiDerm™ model.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin Corrosion","yearReceived":"1998","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=119","lastUpdate":"Monday, October 12, 2020 - 09:22","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Skin corrosion","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: EpiDerm™ is an in vitro reconstructed human epidermis skin-corrosion method using MTT-based cell viability as the principal readout. Application_domain is corrected from Cosmetics to Mixed/general toxicology because the method has broad regulatory use for chemical skin-corrosion hazard assessment. Specific_methodologies is expanded to Organoid/3D tissue model; Cytotoxicity/cell viability assay. The method constitutes full Replacement and requires no live animals or animal tissue. The TSAR source snapshot is preserved: NEW_STEP_STAGE remains REC_NA even though the complete TSAR event history documents subsequent regulatory progression, including OECD TG 431 adoption in 2004 and EU implementation. Current OECD TG 431 continues to recognise EpiDerm™ SCT as a validated reference method. Therefore External_evidence_step_stage is REG_ADOPT, while case_study_method remains 0 because the later progression is already documented in the full TSAR lifecycle history. No material lifecycle bottleneck was identified.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM1998-02","shortName":"EpiSkin™","title":"EpiSkin™ skin corrosivity test","organisation":"EURL ECVAM - European Union","description":"The EpiSkin™ skin corrosivity test can be used to identify whether (or not) a chemical has the potential to corrode skin. Skin corrosion is generally defined as full thickness destruction of skin tissue but can also include any irreversible alterations to skin. The method uses a 3D human skin model and involves topical application of a test substance and subsequent assessment of cell viability and cytotoxicity. The method is based on the EpiSkin™ standard model, which is a three-dimensional human skin model that is comprised of a reconstructed epidermis and a functional stratum corneum (i.e. the outer layer of skin). For the purposes of testing for skin corrosion potential, substances are applied topically to the surface of the model and then cell viability is assessed. Specifically, cytotoxicity is assessed through the MTT assay.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin Corrosion","yearReceived":"1998","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=118","lastUpdate":"Monday, October 12, 2020 - 09:22","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Skin corrosion","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: EpiSkin™ is an in vitro reconstructed human epidermis skin-corrosion method using MTT-based cell viability as the principal readout. Application_domain is corrected from Cosmetics to Mixed/general toxicology. The method constitutes full Replacement. The TSAR source snapshot is preserved: NEW_STEP_STAGE remains REC_NA even though the complete TSAR event history documents subsequent regulatory progression, including OECD TG 431 adoption in 2004 and EU implementation. OECD removed the EpiSkin™ model from the 2025 revision of TG 431 because it is no longer commercially available; this is therefore coded as a current access/implementation barrier. External_evidence_step_stage is REG_ADOPT and case_study_method remains 0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Access / implementation","bottleneckCount":"1","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM1998-01","shortName":"Corrositex®","title":"In Vitro Membrane Barrier Test Method for Skin Corrosion","organisation":"EURL ECVAM - European Union","description":"The Corrositex® method was originally established to predict the skin corrosivity potential of chemicals and to rank them according to their degree of corrosive effect. The assay is based on the determination of the time needed for a test material to pass through a biobarrier membrane. The membrane is a reconstituted collagen matrix with physical properties that are similar to rat skin. The end-point is the time required to cause a colour change in an underlying 'chemical detection system'. The colour change is visually scored and therefore a subjective measurement (i.e. there is a potential variation in measurement outcomes due to operator variability). The test method has received regulatory approval as a replacement of in vivo skin corrosivity tests (i.e. the Draize rabbit skin test) for specific classes of chemicals (i.e. acids, bases and certain derivatives) which meet the technical requirements of the assay.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin Corrosion","yearReceived":"1998","generalComments":"In the 1990s, the Corrositex® method was evaluated on a number of occasions by agencies in the US. They concluded that in specific testing circumstances, the method would be useful as a stand-alone assay for evaluating skin corrosion potential.","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=116","lastUpdate":"Monday, October 12, 2020 - 09:23","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Skin corrosion","methodology":"In chemico","specificMethodologies":"Barrier/permeability/transport assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: Corrositex® is a cell-free membrane-barrier skin-corrosion method using a synthetic proteinaceous macromolecular barrier and chemical detection system. Core_methodology is corrected from In vitro; Ex vivo; In chemico; Mixed to In chemico, and Specific_methodologies from Ex vivo/tissue-based assay to Barrier/permeability/transport assay. Application_domain is corrected from Cosmetics to Mixed/general toxicology. The method is a Replacement method for its validated uses. ECVAM/ESAC validation established a restricted applicability domain, and current OECD TG 435 continues to require an initial test-chemical compatibility assessment; applicability-domain and product/matrix-qualification bottleneck signals are therefore retained, while the validation-readiness signal is removed. The source snapshot is preserved with NEW_STEP_STAGE = REC_NA, while the complete TSAR lifecycle and OECD TG 435 adoption support External_evidence_step_stage = REG_ADOPT. case_study_method remains 0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain; Product / matrix qualification","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2008-10","shortName":"EpiOcular EIT","title":"EpiOcular™ Human Cell Construct EIT","organisation":"EURL ECVAM - European Union","description":"The EpiOcular™ Eye Irritation Test (EIT) consists of a reconstructed human cornea-like epithelium (RhCE) tissue construct, a non-keratinized multi-layered epithelium prepared from non-transformed, human-derived epidermal keratinocytes which show a cornea-like structure analogous to that found in in vivo. The test chemical is applied topically to a minimum of two RhCE tissue constructs. Following the exposure and post-treatment incubation periods, tissue viability is assessed by MTT assay.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Serious eye damage/Eye irritation","yearReceived":"2008","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=164","lastUpdate":"Monday, October 12, 2020 - 09:04","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":"Expert review confirmed outside-TSAR progression beyond the REC_NA source snapshot. EpiOcular EIT progressed through validation/peer review to regulatory guideline adoption (OECD TG 492). Product/matrix qualification evidence was initially limited for representative labelled products and mixtures and was subsequently strengthened, including formulation datasets. The assay identifies chemicals not requiring classification but does not independently discriminate all UN GHS eye-hazard categories, so classified responses require complementary information or a defined/integrated approach. case_study_method = 1; External_evidence_step_stage = REG_ADOPT. TSAR source-copy lifecycle fields remain unchanged.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package; Product / matrix qualification; Regulatory relevance / integration","bottleneckCount":"3","animalUseImpact":"Unknown","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2015-03","shortName":"SkinEthic HCE EIT","title":"SkinEthic™ HCE Eye Irritation Test","organisation":"EURL ECVAM - European Union","description":"The SkinEthic™ Human Corneal Epithelium (HCE) Eye Irritation Test (EIT) method is an in vitro assay used for assessing eye irritation/serious eye damage. The method uses a reconstructed human cornea-like epithelium (RhCE) consisting of a multilayered epithelium prepared from immortalized human corneal epithelial cells which reproduce the multi-layer organization of the human cornea. The tissues are exposed to the test chemicals according to two possible protocols, depending on the physical state of the test chemical either solid \"EITS\" protocol (see DB-ALM protocol No.191), or liquid/viscous \"EITL\" protocol ( see DB-ALM protocol No.190).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Serious eye damage/Eye irritation","yearReceived":"2015","generalComments":"External validation performed. Report submitted for peer-review as full test submission.","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:10","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model","review":"Expert-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":"Expert review confirmed outside-TSAR progression of the revised SkinEthic HCE EIT beyond the REC_NA source snapshot through validation/peer review and regulatory guideline adoption within the RhCE eye irritation framework (OECD TG 492). This supports case_study_method = 1 and External_evidence_step_stage = REG_ADOPT. TSAR source-copy lifecycle fields remain unchanged.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package; Predictive performance; Regulatory relevance / integration; Standardisation / regulatory adoption","bottleneckCount":"4","animalUseImpact":"Unknown","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM1997-01","shortName":"TABST","title":"Deletion of Target Animal Batch Safety Test","organisation":"EURL ECVAM - European Union","description":"Since 1st April 2013, the TABST is no longer required in Europe and has been deleted from the European Pharmacopoeia monographs for veterinary vaccines. Since 2005, the target animal batch safety test could be waived when a sufficient number (e.g. 10) of batches had been found to comply with the test. International - VICH: Two VICH guidelines on harmonisation of criteria to waive target animal batch safety testing for inactivated (VICH GL50R) and live (VICH GL55) vaccines for veterinary use are in force since in May 2017 and should be implemented by May 2018. An earlier version of VICH GL50R had been in force since 2013. By meeting the requirements outlined in VICH GL50R and 55, vaccine manufacturers can now apply for a waiver of the TABST by their national competent authorities.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Quality control of vaccines","yearReceived":"1997","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:24","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Food safety","endpoint":"Vaccine quality control","methodology":"In vivo","specificMethodologies":"In vivo reduction/refinement assay","review":"Expert-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":"Borderline case study. TABST is not a classical NAM-development pathway involving validation and adoption of a new non-animal method, but it documents a regulatory transition beyond TSAR through removal/waiver of an animal-based batch-safety requirement. It therefore informs barriers and drivers of animal-free regulatory transformation. case_study_method = 2. External regulatory implementation/removal is treated as completed; TSAR source-copy lifecycle fields remain unchanged.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package; Regulatory relevance / integration","bottleneckCount":"2","animalUseImpact":"Regulatory waiver/removal","applicationDomainExpert":"Veterinary medicines / animal health","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2005-01","shortName":"MNvit","title":"In vitro mammalian cell micronucleus test","organisation":"EURL ECVAM - European Union","description":"The in vitro micronucleus (MNvit) test is a short-term genotoxicity assay for the detection of micronuclei in the cytoplasm of interphase cells. Micronuclei may originate from acentric chromosome fragments (i.e. lacking a centromere), or whole chromosomes that are unable to migrate to the poles during the anaphase stage of cell division. Therefore the MNvit test is an in vitro method that provides a comprehensive basis for investigating chromosome damaging potential in vitro because both aneugens and clastogens can be detected in cells that have undergone cell division during or after exposure to the test chemical. Micronuclei represent damage that has been transmitted to daughter cells.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Genotoxicity/Mutagenicity","yearReceived":"2005","generalComments":"This study represents the first retrospective validation carried out by ECVAM","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:09","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Genotoxicity","methodology":"In vitro","specificMethodologies":"Micronucleus/genotoxicity assay","review":"Expert-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":"Expert review confirmed MNvit as a direct case study of NAM progression beyond TSAR. The in vitro micronucleus assay progressed through validation, international harmonisation and regulatory guideline adoption (OECD TG 487). This supports case_study_method = 1 and External_evidence_step_stage = REG_ADOPT. TSAR source-copy lifecycle fields remain unchanged.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package; Predictive performance; Regulatory relevance / integration; Standardisation / regulatory adoption","bottleneckCount":"4","animalUseImpact":"Unknown","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2001-01","shortName":"ELISA ERY","title":"ELISA test for batch potency testing of swine erysipelas vaccines","organisation":"EURL ECVAM - European Union","description":"The ELISA ERY measures antibody levels against erysipelas in the serum of mice immunised with inactivated swine erysipelas vaccine. It is carried out for vaccine batch release to demonstrate that the given vaccine batch complies with the requirements set in the marketing authorisation for the given vaccine.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Quality control of vaccines","yearReceived":"2001","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:18","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Food safety","endpoint":"Vaccine quality control","methodology":"Mixed","specificMethodologies":"Immunoassay/flow cytometry; In vivo reduction/refinement assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Missing","verificationNote":"Mouse immunisation with inactivated swine erysipelas vaccine induces antibodies measured by indirect serum ELISA for batch potency. The method combines substantive in-vivo immunisation and in-vitro immunoassay; serum sampling is not an ex-vivo tissue assay. Core_methodology is stored as standalone Mixed by expert direction. It reduces animal numbers and avoids lethal challenge, while mice remain necessary. A product-specific reproducibility issue with reference-batch testing was documented by CVMP in 2007. NEW_STEP_STAGE=REG_ADOPT is the TSAR snapshot derivation. Pharmacopoeial adoption in 2004 is already recorded in the complete TSAR history; case_study_method=0 and External_evidence_step_stage=REG_ADOPT.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Reproducibility / transferability","bottleneckCount":"1","animalUseImpact":"Reduction","applicationDomainExpert":"Veterinary medicines / animal health","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2015-02","shortName":"Ashland RhE SIT","title":"Ashland Skin Irritation Test","organisation":"EURL ECVAM - European Union","description":"This test is based on the in vitro test system of Reconstructed Human Epidermis (RHE), which closely mimics the biochemical and physiological properties of the upper parts of the human skin. Cells used are primary keratinocytes isolated from human skin. Irritant compounds induced reversible cell damage which can be measured after short time application (42 minutes) and long post incubation (42 hours). Cell viability in RHE models is measured by enzymatic conversion of the vital dye MTT 3-(4,5- Dimethylthiazol-2-yl)-2,5-diphenyltetrazolium bromide. After solubilisation Thiazolyl blue is measured by optical density. Cell viability of compound is compared to negative control (DPBS) to define percent of viability (end point). Compound is classified irritant if viability is under 50%. This test allows testing of chemical compounds to class them into 2 subgroups (irritant and non irritant) for cosmetics and pharmaceutical application. There is an impact in terms of the Three Rs principle because this method avoids using animal to test irritant compounds. It’s an alternative method to cutaneous Draize test so it replaces animal testing.","stepStage":"Submission > Not considered for validation","workflowStep":"Submission","workflowStage":"Not considered for validation","topic":"Skin irritation","yearReceived":"2015","generalComments":"Similar test method to already validated and accepted ones. Not considered for follow-up","protocolSop":"","lastUpdate":"Wednesday, October 14, 2020 - 09:08","lastUpdateDate":"2020-10-14","stage":"Test Submission","status":"Discontinued","code":"SUB_NOTVAL","applicationDomain":"Cosmetics; Pharmaceutical","endpoint":"Skin irritation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Ashland RhE SIT uses primary-human-keratinocyte reconstructed epidermis, a 42-minute exposure and 42-hour post-incubation, and MTT viability (<50% versus control) to classify skin irritation. Specific methodologies are 3D tissue model and cell-viability assay; MTT detection is not a separate enzyme-activity assay. Intended 3R role is Replacement of the live-animal skin-irritation test for the defined decision, without implying regulatory acceptance of this submission. TSAR ends at Not considered for validation (Dec 2015); EURL ECVAM described presubmission shortcomings and suggested a possible OECD route, with no documented completion. A 2018 Ashland RhE study tested 20 OECD reference chemicals, but exact-platform continuity with TM2015-02 is unverified. Case-study code 2 is the researcher-approved borderline route-selection classification, not evidence of direct external progression or OECD adoption. External_evidence_step_stage=SUB_NOTVAL.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_NOTVAL","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2004-04","shortName":"RBC","title":"Red Blood Cell haemolysis","organisation":"EURL ECVAM - European Union","description":"The Red Blood Cell (RBC) test is used to examine ocular irritants by measuring lysis of erythrocytes (haemolysis) and denaturation of released oxyhaemoglobin. The RBC test is a cell-based cytotoxicity assay, which allows assessing membrane damage of erythrocytes (haemolysis) and changes of the oxyhaemoglobin configuration (protein denaturation). To determine haemolysis, the haemoglobin leakage is measured spectrophotometrically.","stepStage":"Peer-review > Finalised","workflowStep":"Peer-review","workflowStage":"Finalised","topic":"Serious eye damage/Eye irritation","yearReceived":"2004","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=99","lastUpdate":"Friday, October 16, 2020 - 10:42","lastUpdateDate":"2020-10-16","stage":"Validation","status":"Finalised","code":"VAL_PEER_FINAL","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"Ex vivo","specificMethodologies":"Cytotoxicity/cell viability assay; Analytical chemistry readout; Ex vivo/tissue-based assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert review: RBC is an ex vivo eye-irritation screening method using freshly isolated mammalian erythrocytes, with haemolysis/haemoglobin leakage and oxyhaemoglobin denaturation as principal endpoints. Under the project taxonomy, Core_methodology is corrected from In vitro; Ex vivo; Mixed to Ex vivo. Specific_methodologies is corrected to Cytotoxicity/cell viability assay; Analytical chemistry readout; Ex vivo/tissue-based assay, and the erroneous Phototoxicity/photoreactivity assay label is removed. The retrospective ECVAM validation and ESAC peer review identified substantial evidence-readiness, reproducibility/transferability, predictive-performance, applicability-domain, regulatory-integration and standardisation limitations, and the method was not supported for regulatory use. OECD guidance in 2024 continues to report the need for further work before scientific validity can be established. The method is classified as Reduction because its intended role was as a component of a tiered strategy to minimise animal use rather than as a demonstrated stand-alone replacement. No meaningful exact-method progression beyond peer review was identified; therefore case_study_method = 0 and External_evidence_step_stage = VAL_PEER_FINAL. Application_domain_expert is Mixed/general toxicology because the ocular-hazard context spans multiple product and chemical sectors without one defensible primary regulatory domain. TSAR source-snapshot fields are preserved unchanged.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_PEER_FINAL","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Applicability domain; Regulatory relevance / integration; Standardisation / regulatory adoption","bottleneckCount":"6","animalUseImpact":"Reduction","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2004-03","shortName":"NRR","title":"Neutral Red Release Assay","organisation":"EURL ECVAM - European Union","description":"The Neutral Red Release (NRR) assay is a quantitative colorimetric cytotoxicity test using cell lines to measure the immediate toxic effect of a test substance on the cell membrane, resulting in a leakage of intracellular contents. If cells in culture are preloaded with vital dye (neutral red [NR]) and then exposed to a toxic substance, the amount of dye released from the cells will reveal the degree of membrane damage. The result of the test is expressed as the concentration of test substance that gives rise to the release of 50% of the NR from preloaded cells. Cell membrane damage is one of the principal events that lead to chemical-induced eye irritation, and it can be modelled using the NRR assay.","stepStage":"Peer-review > Finalised","workflowStep":"Peer-review","workflowStage":"Finalised","topic":"Serious eye damage/Eye irritation","yearReceived":"2004","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=54","lastUpdate":"Friday, October 16, 2020 - 10:42","lastUpdateDate":"2020-10-16","stage":"Validation","status":"Finalised","code":"VAL_PEER_FINAL","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert review: NRR is an in vitro cytotoxicity/cell-viability assay measuring acute membrane damage through release of preloaded neutral red dye. Core_methodology = In vitro and Specific_methodologies = Cytotoxicity/cell viability assay are retained; Application_domain_expert = Cosmetics. ECVAM retrospective validation was completed in 2008 and ESAC peer review was finalised in 2009, but the evidence was insufficient for a general regulatory recommendation. Evidence-supported bottlenecks concerned evidence-package maturity, reproducibility/transferability, predictive performance, restricted applicability domain, regulatory integration and standardisation. Under the project taxonomy the method is classified as Reduction because it was supported mainly as a screening/tiered component rather than a full Draize replacement. Outside the captured TSAR route, regulatory use is documented in France for cosmetics and NRR is included in the US EPA New Chemicals eye-irritation decision framework; therefore case_study_method = 1 and External_evidence_step_stage = REG_ADOPT. Source TSAR snapshot fields remain unchanged.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_PEER_FINAL","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Applicability domain; Regulatory relevance / integration; Standardisation / regulatory adoption","bottleneckCount":"6","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2009-05","shortName":"MUSST","title":"Myeloid U937 Skin Sensitisation Test","organisation":"EURL ECVAM - European Union","description":"The MUSST assay supports the discrimination between sensitizing and non-sensitizing chemicals. It addresses one of the biological mechanisms described under key event 3 (events in dendritic cells (DC)) of the skin sensitization Adverse Outcome Pathway (AOP) by measuring the induction of the CD86 protein marker in U937 cells. The U937 cells are human myeloid cells used as surrogate model for DCs. U937 is a cell line established from a diffuse histiocytic lymphoma with the advantage of higher stability and the easiness of maintenance compared to human-blood derived DCs. The CD86 protein marker is a costimulatory factor which is upregulated in mature DCs and plays a pivotal role in antigen presentation and subsequent T cell priming. In the MUSST test method, the modulation of the FITC-labeled anti-CD86 in U937 cells is measured by flow cytometry after a 48 hours exposure to test chemicals.","stepStage":"Validation > Stopped","workflowStep":"Validation","workflowStage":"Stopped","topic":"Skin sensitisation","yearReceived":"2009","generalComments":"Validation stopped. New submission with new protocol received under TM2013-02 (U-Sens)","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:59","lastUpdateDate":"2020-10-12","stage":"Validation","status":"Discontinued","code":"VAL_STOP","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Immunoassay/flow cytometry","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert review: MUSST is an in vitro U937-cell assay measuring sensitiser-induced CD86 surface-marker upregulation by flow cytometry and addresses dendritic-cell activation (Key Event 3) of the skin-sensitisation AOP. Core_methodology = In vitro and Specific_methodologies = Immunoassay/flow cytometry are retained. Application_domain_expert = Cosmetics; Industrial chemicals. The original EURL ECVAM validation was stopped because the three-outcome prediction model produced inconclusive classifications that adversely affected reproducibility, supporting validation/readiness and reproducibility/transferability bottlenecks. TSAR explicitly identifies TM2013-02 (U-SENS™) as the succeeding revised submission. The original TM2009-05 itself did not progress beyond Validation > Stopped; therefore External_evidence_step_stage = VAL_STOP. The revised successor TM2013-02 subsequently progressed within TSAR through validation, peer review, recommendation and OECD TG 442E adoption. Because regulatory success occurred through a separate resubmitted successor rather than progression of TM2009-05 itself, this method is classified as a borderline case study (case_study_method = 2). Three_R_category = Reduction because the assay supplies one component of skin-sensitisation evidence for use in integrated or defined approaches rather than functioning as a universal stand-alone replacement. Source TSAR snapshot fields remain unchanged.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_STOP","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2009-11","shortName":"ERalpha-CALUX","title":"Prediction of the in vivo estrogenic activity of chemicals ERalpha-CALUX","organisation":"EURL ECVAM - European Union","description":"The ERalpha-CALUX test is an estrogen receptor transactivation assay, assessing the activity of (anti-)estrogenic compounds. The test is based on the human osteocarcinoma cell line (U2OS). The cells are stably co-transfected with the full length human ERα and a luciferase gene. The test assesses the transcription of the luciferase gene, through the measurement of luminescence, and allows the discrimination between agonists and antagonists. This assay investigates the potential for interaction of a chemical substance with nuclear receptors for endogenous hormones and as such investigate early events within an adverse outcome pathway (AOP) associated with perturbation of the endocrine system. It could be used within an Integrated Testing Strategy (ITS) or Integrated Approaches to Testing and Assessment (IATA) for identification of endocrine disruptors.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Reproductive toxicity, Endocrine disruption","yearReceived":"2009","generalComments":"Not prioritised for validation by ECVAM. External validation performed.","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:00","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert review: ER\\u03b1-CALUX is a human U2OS-cell-based in vitro estrogen-receptor transactivation assay in which ER\\u03b1-mediated transcription is quantified through a luciferase reporter. Core_methodology is corrected to In vitro only. Specific_methodologies is corrected to Reporter gene assay; the method is not itself an integrated testing strategy and does not directly measure receptor binding. Endpoint_category = Reproductive toxicity; Endocrine disruption is retained. Historical prevalidation identified a transferability issue that was resolved by development of a more stable cell clone, after which formal validation demonstrated high within- and between-laboratory reproducibility. OECD TG 455 nevertheless defines important applicability and regulatory-integration limitations, including limited metabolic capacity and use primarily for screening, prioritisation and weight-of-evidence assessment. EURL ECVAM determined that the method qualified for performance-standards-based validation but did not prioritise it for EURL ECVAM-coordinated validation; validation therefore proceeded externally. The same TM subsequently progressed to OECD TG 455 adoption in 2016. Accordingly, External_evidence_step_stage = REG_ADOPT and case_study_method = 1, while the source snapshot NEW_STEP_STAGE = VAL_FINAL remains unchanged. Three_R_category = Reduction because the assay primarily reduces reliance on animal testing through mechanistic screening and integrated evidence rather than independently replacing all relevant in-vivo endocrine evidence. Application_domain_expert = Industrial chemicals; Environmental.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Reproducibility / transferability; Applicability domain; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2004-01","shortName":"Cytosensor","title":"The cytosensor microphysiometer toxicity test","organisation":"EURL ECVAM - European Union","description":"The cytosensor microphysiometer toxicity test method is a cell-based in vitro assay that was developed as a partial replacement of the Draize rabbit eye irritation test. The method consists of a monolayer of adherent mouse L929 fibroblast cells that are cultured on a polycarbonate cell culture insert. Within the system there is also a light-sensitive pH sensor. The ocular toxicity of test substances is evaluated according to reductions in metabolic rate of the cells following exposure (as assessed by changes in the rate of reduction of pH in the cell culture medium). The cells have a natural rate of metabolism that results in the production of extra-cellular acids. This rate is expected to vary following exposure to potentially toxic substances.","stepStage":"Regulatory acceptance/Standards > Stopped","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Stopped","topic":"Serious eye damage/Eye irritation","yearReceived":"2004","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=130","lastUpdate":"Thursday, April 2, 2026 - 13:04","lastUpdateDate":"2026-04-02","stage":"Regulatory assessment","status":"Rejected","code":"REG_STOP","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Metabolic activity sensor assay; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: The Cytosensor Microphysiometer is a cell-based in vitro eye-irritation assay using L929 fibroblasts and a pH-sensitive microphysiometer to quantify toxicant-induced reductions in cellular metabolic activity. Core_methodology = In vitro is retained; Specific_methodologies is expanded to Metabolic activity sensor assay; Cytotoxicity/cell viability assay. The method was scientifically validated for defined Top-Down and Bottom-Up eye-hazard decisions but showed important predictive-performance and applicability-domain limitations and could not independently classify the full range of ocular irritation. The OECD Test Guideline programme subsequently stopped because the validated Cytosensor technology was no longer commercially available, supporting access/implementation and standardisation bottlenecks rather than programme-prioritisation failure. Despite the stopped OECD route recorded by TSAR, the exact CM method received US agency acceptance and was subsequently implemented within the US EPA non-animal eye-irritation framework for antimicrobial cleaning products. Therefore case_study_method = 1 and External_evidence_step_stage = REG_ADOPT, while source TSAR lifecycle fields remain unchanged. Three_R_category = Replacement is retained because within its validated intended uses the assay can substitute for live-animal ocular testing. Application_domain_expert = Cosmetics; Industrial chemicals.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Predictive performance; Applicability domain; Regulatory relevance / integration; Access / implementation; Standardisation / regulatory adoption","bottleneckCount":"5","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2009-12","shortName":"OPIV","title":"In vitro approach for organophosphorous compounds-induced neurotoxicity (OP Neurotox Assay)","organisation":"EURL ECVAM - European Union","description":"In vitro test system based on in SH-SY5Y human neuroblastoma cell line was proposed for evaluation of organophosphorus compounds (OPs) induced neurotoxicity. The assay is based on the measurements of acetylcholineesterase (AChE) and neuropathy target esterase (NTE) activity since OPs exert neurotoxicities following inhibition of these two critical esterases: AChE for acute toxicity and neurotoxic esterase NTE for delayed neuropathy. To be effective insecticides, AChE needs to be inhibited, but NTE does not. The relationship between AChE and NTE inhibition provides information on which OP compounds could be expected to be effective as insecticides without them causing progressive, irreversible delayed neuropathy in humans and susceptible animals. Concentration-responses of AChE and NTE activities can be measured in cultured neuronal cells, plotted against the log of their concentrations, and a ratio of the concentrations responsible for 50% inhibition (IC50) determined by dividing the NTE IC50 by the AChE IC50. Ratios >100 suggest that NTE inhibition and subsequent delayed neuropathy are unlikely because test compound concentrations would need to be 100-fold higher than those causing acute toxicity. Protoxicants can be tested in this system following incubation with 0.05% bromine solution or rat liver microsomes. NTE and AChE inhibition can be measured following either a single exposure or exposures for up to 28 days. Use of this in vitro system would decrease the need to dose animals and collect brain and spinal cord for esterase measurements. Evaluated organophosphorus compounds were chosen based on animal studies that identified them as active toxicants capable of producing delayed neuropathy (n=6), protoxicants capable of producing delayed neuropathy (n=3), active AChE inhibitors not producing delayed neuropathy in unprotected animals (n=5), and protoxicants not producing delayed neuropathy in unprotected animals (n=5). The in vitro test comparing the NTE inhibition with the AChE inhibition produced by the 19 compounds tested matched the in vivo results 100% of the time.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Neurotoxicity","yearReceived":"2009","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:00","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Neurotoxicity","methodology":"In vitro","specificMethodologies":"Enzyme/biochemical activity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert review: OPIV is an in vitro human SH-SY5Y neuroblastoma-cell assay designed to discriminate organophosphorus neurotoxicity through inhibition of acetylcholinesterase (AChE) and neuropathy target esterase (NTE). Core_methodology = In vitro is retained. Specific_methodologies is narrowed to Enzyme/biochemical activity assay because AChE and NTE activities are the primary classification endpoints; cytotoxicity can be measured as supporting information but is not the defining assay endpoint. The available evidence showed promising concordance with in vivo classifications, but the approach had not undergone formal inter-laboratory validation and retained important applicability limitations related to metabolic bioactivation and restriction to AChE/NTE-mediated organophosphorus neurotoxicity. Its intended role was primarily screening/ranking within a broader testing strategy, supporting regulatory-relevance/integration and Reduction classifications. Following full-submission assessment and stakeholder consultation, EURL ECVAM stopped the submission in February 2012. During expert verification, the stored Part-A lifecycle was identified as internally inconsistent with the underlying TSAR record: the workbook contained Submission > Assessment of full submission / SUB_ASSESS although the same TSAR record already contained the later Submission > Stopped event. With explicit user approval, this is treated as an exceptional source-extraction correction: step_stage = Submission > Stopped, workflow_stage = Stopped and NEW_STEP_STAGE = SUB_STOP. This exception must not be generalised to other TMs. External_evidence_step_stage = SUB_STOP is also recorded for consistency with the complete documented lifecycle. No later formal validation or regulatory progression of the exact method was identified; therefore case_study_method = 0. Application_domain_expert = Mixed/general toxicology.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Applicability domain; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2010-06","shortName":"DRG","title":"Embryonic Rat Dorsal Root Ganglia Organotypic Culture","organisation":"EURL ECVAM - European Union","description":"Rat Dorsal Root Ganglia (DRG) explants from 15-day-old embryos (E15) were proposed as a model for studying peripheral neuropathy induced by drugs belonging to different classes. The parameter measured at each time point (24 hours after the drug treatment) was the length of longest neurite of each DRG evaluated by the program Image J in the control culture and after exposure to a drug. Drug-induced neurotoxicity assessment was based on the ability of E15 DRG explants to measure an outgrowth of neurites (length) when exposed to NGF and at the same time to a toxic substance (drug). E15 DRG represents a suitable model for assessing the neurotoxicity of antineoplastic drugs because in vivo DRG are the main target of several neurotoxic drugs and the concentrations of the drugs used to elicit changes in this in vitro model were, in general, comparable to those achievable in vivo. The model has been tested treating DRG cultures with two antineoplastic drugs (paclitaxel and oxaliplatin) belonging to two different classes of antineoplastic agents and known to be both neurotoxic in clinical use and in animal models. DRG has been treated with concentrations comparable to those achievable in vivo. Neurotoxic drug concentrations induced a reduction of neurite length higher than 50% respect to control that represents the cut-off value of the test. The results obtained confirmed the neurotoxicity evidenced with the same drugs in published rat and mouse in vivo models. Intended purpose of the test method could be relevant to regulatory and scientific neurotoxicity testing for antineoplastic drugs in industry-driven compounds early screening and discovery.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Neurotoxicity","yearReceived":"2010","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:53","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Pharmaceutical","endpoint":"Neurotoxicity","methodology":"Ex vivo","specificMethodologies":"Ex vivo/tissue-based assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert review: TM2010-06 uses dorsal root ganglion explants obtained from E15 rat embryos and cultured outside the organism to quantify drug-induced inhibition of NGF-supported neurite outgrowth. Under the project taxonomy, Core_methodology is corrected to Ex vivo because intact animal tissue is removed from the organism and subsequently tested ex vivo; In vitro, In vivo and Mixed are removed. Specific_methodologies is corrected to Ex vivo/tissue-based assay. The use of ImageJ for a single morphometric neurite-length endpoint does not constitute high-content imaging, the explant is not an organoid, and embryonic tissue origin alone does not make the assay an embryo/developmental model. The available evidence showed encouraging discrimination of a small set of antineoplastic reference drugs and good agreement across researchers and two laboratories, so no reproducibility or predictive-performance failure is coded. However, the evidence package remained limited, the demonstrated applicability domain was primarily antineoplastic-drug-induced peripheral neurotoxicity, and the assay was positioned mainly for early screening rather than as a complete stand-alone regulatory neurotoxicity assessment. Following full-submission assessment, EURL ECVAM stopped the submission in July 2012 without publicly identifying a specific technical failure. Therefore validation/readiness, applicability-domain, regulatory-relevance/integration and programme-route bottlenecks are coded. Standardisation/adoption is not coded merely because the submission stopped. The complete TSAR lifecycle confirms SUB_STOP; no later formal validation or regulatory progression of the exact method was identified, so case_study_method = 0 and External_evidence_step_stage = SUB_STOP. Three_R_category = Reduction is retained. Application_domain_expert = Pharmaceutical / human medicines. Later scientific uptake was identified: embryonic rat DRG culture systems were subsequently used in US EPA research, including evaluation of additional chemicals using neurite length together with cytotoxicity and neurophysiological endpoints. However, this later work cannot be demonstrated to represent continued validation or implementation of the exact TM2010-06 protocol/prediction model; the assay configuration and endpoints were expanded and the evidence represents scientific method development rather than formal regulatory progression. Therefore this scientific uptake does not meet the project definition for either a direct (1) or borderline (2) case study.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Applicability domain; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2014-04","shortName":"devTOXqP","title":"devTOX qp (Stemina) devTOX quick Predict","organisation":"EURL ECVAM - European Union","description":"This is an in vitro developmental toxicity method that could be used to evaluate whether a test compound may have the potential for teratogenicity in humans. The test method measures changes in a ration between two metabolic biomarkers (cystine and ornithine) present in cell culture media of human induced undifferentiated pluripotent stem (hiPS) cells exposed to a compound. Changes in two metabolites, ornithine and cystine, are measured in response to treatment and then used in a ratio (o/c ratio) across an 8-point dose response curve. The teratogenicity potential is the interpolated exposure level (concentration) of a test compound where the dose response curve crosses a defined teratogenicity threshold. Exposure levels greater than this concentration are associated with teratogenicity. Its performance suggests that the assay is amenable to predicting teratogens regardless of their classification as weak or strong. Cytotoxicity is provided as a secondary endpoint at the same eight concentrations as those tested for the o/c ratio. The design and sensitivity of the assay allows for identification of teratogenic potential at non-cytotoxic levels of the test compound, by negating the confounding effects of changes in metabolite abundance due solely to cytotoxicity. The assay is performed with undifferentiated human iPS cells, providing an opportunity to evaluate disruptions in human development.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Teratogenicity","yearReceived":"2014","generalComments":"Not considered for validation studies based on PARERE consultation opinion.","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:37","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Industrial chemicals","endpoint":"Teratogenicity","methodology":"In vitro","specificMethodologies":"Omics; Analytical chemistry readout; Embryo/developmental model","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert review: devTOX quickPredict is a human pluripotent-stem-cell-based in vitro developmental-toxicity assay that predicts developmental toxicity potential from exposure-dependent changes in the extracellular ornithine/cystine metabolic-biomarker ratio measured by LC-MS. Core_methodology = In vitro is retained. Specific_methodologies is corrected to Omics; Analytical chemistry readout; Embryo/developmental model. Cytotoxicity/cell viability is removed as a primary methodology because cell viability is explicitly a secondary interpretative endpoint and is not used to calculate the developmental-toxicity prediction. The original EURL ECVAM submission was stopped in 2015 following PARERE consultation regarding potential regulatory relevance. The same assay subsequently progressed outside TSAR through large-scale US EPA/ToxCast evaluation and into the FDA Biomarker Qualification Program. FDA accepted the biomarker into the qualification pathway but narrowed its proposed context of use to developmental-toxicity assessment as part of a weight-of-evidence approach. Independent assay transfer and interlaboratory reproducibility work is ongoing as part of the qualification programme. Accordingly, case_study_method = 1 and External_evidence_step_stage = VAL_ONGO, while the source TSAR lifecycle remains SUB_STOP. Evidence-supported bottlenecks concern validation readiness, transferability, predictive performance, applicability domain, mechanistic coverage, regulatory integration and programme route selection. Three_R_category = Reduction because current demonstrated use is primarily screening, prioritisation and weight-of-evidence support rather than complete replacement of the standard in-vivo EFD evidence. Application_domain_expert = Industrial chemicals; Pharmaceutical / human medicines.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_ONGO","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Applicability domain; Mechanistic relevance; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"7","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2012-02","shortName":"Skin PAMPA","title":"Skin PAMPA Permeability System","organisation":"EURL ECVAM - European Union","description":"The Skin PAMPA is a method that measures the passive permeation of a substance, applied in solution or as a formulation, through an artificial membrane mimicking the human skin. The test is performed in a 96 well plate and the membrane is placed between a donor compartment, to which the test solution/formulation is applied, and a receptor compartment filled with buffer solution at pH 7.4 (simulation of blood pH). The permeation (passive diffusion) through the membrane is measured by determining the portion of substance appearing in the receptor compartment after incubation. Quantification is done with a suitable analytical method, such as UV-Vis spectrophotometry or Liquid-chromatography. The applied artificial membrane has been specifically designed to mimic the human stratum corneum (SC) that forms the major barrier of skin. It contains a synthetic structural analogue similar to the ceramide component of the skin-lipid matrix and other components such as cholesterol and free fatty acids. The manufacturing technology used for the artificial membrane aims at creating a similar hydrophilic/lipophilic balance as found in the natural SC lipid matrix. The production of the membrane does not require human or animal tissue.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin permeability/penetration","yearReceived":"2012","generalComments":"Submission on hold.","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:43","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Skin permeability/penetration","methodology":"In chemico","specificMethodologies":"HTS; Analytical chemistry readout; Barrier/permeability/transport assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: Skin PAMPA is a cell- and tissue-free in chemico permeability system using a 96-well donor/acceptor format and an artificial lipid membrane designed to mimic the barrier properties of the human stratum corneum. Core_methodology = In chemico is retained. Specific_methodologies is corrected to HTS; Analytical chemistry readout; Barrier/permeability/transport assay; the Phototoxicity/photoreactivity assay label is removed because light-induced toxicity or photoreactivity is not measured. Application_domain_expert = Cosmetics; Pharmaceutical / human medicines. The TSAR submission was placed on hold pending broader toxicokinetics/ADME work and subsequently stopped in 2014; the source lifecycle therefore remains SUB_STOP. Later evidence demonstrates substantial continued development and implementation of the same Skin PAMPA platform in pharmaceutical and cosmetic research, including transdermal-patch testing, formulation optimisation, chemical screening and industrial collaboration. This constitutes progression toward practical implementation beyond the TSAR snapshot and supports case_study_method = 1. However, no formal OECD/EURL ECVAM regulatory validation or adoption of Skin PAMPA as a stand-alone dermal-absorption method was identified, so External_evidence_step_stage remains SUB_STOP. Evidence-supported bottlenecks concern validation readiness, context-dependent predictive performance, restricted applicability relative to biological skin, product/formulation compatibility, regulatory integration and programme route selection. The standardisation/adoption signal is removed because the method never entered a documented standardisation process. Three_R_category = Replacement because, for its demonstrated screening purpose, the fully artificial membrane can substitute animal-derived skin or live-animal permeability testing components without requiring animal tissue.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Predictive performance; Applicability domain; Product / matrix qualification; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"6","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2013-03","shortName":"SS Predictor","title":"Skin Sensitizer Predictor","organisation":"EURL ECVAM - European Union","description":"The Skin Sensitizer Predictor is a test method proposed for skin sensitisation hazard assessment. The expression levels of mRNA transcripts for a set of four genes and of proteins involved in three different intracellular signalling pathways are quantified following treatment of a mouse foetal skin-derived dendritic cell (DC) line (FSDC) with test chemicals. Readouts are then used in a prediction model based on linear discriminant analysis to derive a Prediction Score for distinguishing between sensitising and non-sensitising chemicals. The FSDC cell line used is reported to possess antigen presenting capacity and to have a surface phenotype consistent with immature myeloid DC precursors. The quantitative analysis of m-RNA expression levels for the four genes investigated is performed by real time reverse transcription polymerase chain reaction (RT-PCR) and the protein levels are determined by chemiofluorescence analysis following separation with western blotting. Of the four genes measured, the expression of three of them (TRXR1, HMOX1 and NQO1) is controlled by the Nrf2/ARE/EpRE pathway which is a relevant pathway involved in skin sensitisation as documented in the scientific literature. The fourth gene investigated encodes the CXCL10 chemokine which plays an important role in T-cell mediated immune responses. The intracellular signalling proteins measured are reported to be involved in the p38, MAPK and JNK signalling pathways which have been shown to be activated in DC and keratinocytes upon exposure to protein binding chemicals.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin sensitisation","yearReceived":"2013","generalComments":"Not considered for follow-up","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:40","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Skin sensitisation","methodology":"Mixed","specificMethodologies":"Omics; AI/ML; Immunoassay/flow cytometry","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert review: The Skin Sensitizer Predictor is a mixed in vitro/in silico method in which a mouse fetal skin-derived dendritic cell line is exposed to test chemicals, targeted mRNA and intracellular-signalling protein responses are quantified, and the resulting biological variables are integrated through a linear-discriminant classifier to predict sensitiser versus non-sensitiser status. Per project coding rules, Core_methodology is recorded as the single value Mixed; the subordinate In vitro and In silico components are not separately stored in Core_methodology. Specific_methodologies is narrowed to Omics; AI/ML; Immunoassay/flow cytometry. Omics is retained as the closest available controlled-vocabulary label for the targeted multi-gene expression signature and does not imply genome-wide transcriptomics. Reporter gene assay is removed because endogenous transcript expression rather than a reporter construct is measured, and Binding/interaction assay is removed because molecular binding is not an assay endpoint. The method is best interpreted as a non-animal evidence component for integration into a broader test battery or weight-of-evidence approach rather than as a complete stand-alone skin-sensitisation assessment. The method itself is not coded as Integrated testing strategy/battery because it is one assay/prediction component rather than the full testing architecture. Initial blinded performance was promising but based on a limited chemical set and no independent multi-laboratory validation of the complete method was identified, supporting a validation-readiness bottleneck. The intended role as an integrated evidence component supports a regulatory-relevance/integration bottleneck. EURL ECVAM stopped the presubmission route in February 2014 and did not consider the method for follow-up. The standardisation/adoption signal is removed because no standardisation process was reached. Outside TSAR, the same named Sensitizer Predictor technology was patented and deployed by ToxFinder as proprietary skin-sensitisation technology, supporting practical implementation beyond the stopped TSAR route and therefore case_study_method = 1. No subsequent formal validation or regulatory lifecycle progression of the exact method was identified, so External_evidence_step_stage remains SUB_STOP. Three_R_category = Reduction because the current evidence supports its role as a non-animal component of an integrated/test-battery/weight-of-evidence assessment rather than a demonstrated stand-alone regulatory replacement. Application_domain_expert = Cosmetics; Industrial chemicals.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"3","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2008-03","shortName":"PorCORA","title":"Porcine corneal opacity reversibility assay","organisation":"EURL ECVAM - European Union","description":"Porcine corneal opacity reversibilitThe Porcine Corneal Opacity Reversibility Assay (PorCORA) evaluates recovery of ocular irritation in excised, cultured, porcine corneas. Like the Draize rabbit eye test, substances are applied directly to the corneal surface and then corneal recovery is evaluated over a period of 21 days. Corneal injury and reversibility are determined by scoring the area of sodium fluorescein (NaFL) stain retention 1, 2, 3, 7, 10, 14, and 21 days post-exposure. NaFL retention is a well-characterized indicator of tissue damage and, more specific to the cornea, loss of the surface epithelial layer integrity. The endpoint of this assay is a time to corneal recovery score (days). A test substance can therefore be characterized as causing reversible or irreversible corneal damage. Re-epithelialization is the primary method of corneal healing. Because this multi-layered epithelial process is driven by replenishment of cells from the corneal periphery, a replacement test using whole, intact corneas is critical to an accurate assessment of corneal recovery and reversibility. In addition, the PorCORA air-interface culture technique is imperative for maintenance of normal in vivo corneal physiology. PorCORA has been developed for the purpose of replacement of the reversibility component of the Draize rabbit eye test. In combination with in vitro tests that quantify the severity of ocular injury and vascular effects, PorCORA could replace in vivo ocular irritation tests.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Serious eye damage/Eye irritation","yearReceived":"2008","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:04","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"Ex vivo","specificMethodologies":"Ex vivo/tissue-based assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"Expert review: PorCORA is an ex vivo ocular-irritation/reversibility assay using intact porcine corneas obtained as slaughterhouse by-products and maintained in long-term air-interface culture. Per the project single-value rule, Core_methodology is corrected from In vitro; Ex vivo; Mixed to Ex vivo. Specific_methodologies = Ex vivo/tissue-based assay is retained. The assay follows sodium-fluorescein retention over time to determine recovery from corneal epithelial injury and specifically supplies the reversibility component of ocular-hazard assessment. It is best interpreted as a complementary component of a broader test battery or weight-of-evidence approach rather than as the complete testing architecture itself; therefore Integrated testing strategy/battery remains 0. The complete TSAR record ends in March 2009 at Submission > Stopped, when EURL ECVAM decided not to consider the method for coordinated validation, so the protected TSAR snapshot remains SUB_STOP. Importantly, the direct-case-study decision is not based merely on later routine implementation: after the TSAR route stopped, the exact PorCORA method underwent documented validation-oriented method development outside TSAR, including a 2011 32-compound evaluation against historical rabbit-eye data and subsequent internal validation on a 56-chemical dataset, followed by later industrial application alongside BCOP in a weight-of-evidence assessment. This exact-method, post-TSAR validation-oriented progression supports case_study_method = 1 under the current project definition. No subsequent formal independent validation programme, OECD Test Guideline, or regulatory adoption of PorCORA itself was identified, so External_evidence_step_stage remains SUB_STOP. Evidence-supported bottlenecks concern validation readiness, non-universal predictive performance, regulatory integration and programme route selection. The standardisation/adoption signal is removed because no documented standardisation process was reached. Three_R_category and animal_use_impact_category = Replacement are retained because PorCORA can replace the live-rabbit reversibility component using slaughterhouse-derived corneal tissue. Application_domain_expert = Cosmetics; Industrial chemicals.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Predictive performance; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"4","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2014-07","shortName":"CORNiPSC","title":"iPSC-derived corneal epithelial cells for ocular toxicity tests","organisation":"EURL ECVAM - European Union","description":"The CORNiPSC is intended to be used for eye irritation testing. It is an in vitro method that applies corneal epithelial cells produced from human induced pluripotent stem cell (iPSC) lines and grown in a two-dimensional cell culture. The endpoint measurement is done by determination of cell viability. This test method is in a presubmission stage. Further refinement of the testing protocol in the light of the addressed key endpoint, will show, if this test method could be useful in the initial step of either a Bottom-Up or a Top-Down approach to be used in an integrated testing strategy.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Serious eye damage/Eye irritation","yearReceived":"2014","generalComments":"Not considered for follow-up","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:37","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert review: CORNiPSC is an in vitro eye-irritation method using human iPSC-derived corneal epithelial cells in two-dimensional culture, with loss of cell viability as the principal toxicity readout. Under the project single-value rule, Core_methodology is corrected from In vitro; Integrated approach; Mixed to In vitro. Specific_methodologies is narrowed to Cytotoxicity/cell viability assay. Integrated testing strategy/battery is removed because CORNiPSC is an individual assay proposed as a potential initial component of a Bottom-Up or Top-Down integrated testing strategy, not the complete testing architecture itself. The complete TSAR history ends in May 2015 at Submission > Stopped, when the method was not considered for follow-up; the protected source lifecycle therefore remains SUB_STOP. JRC documentation identifies the Shalom-Feuerstein 2012 human-iPSC corneal differentiation platform as the basis of CORNiPSC and noted that further refinement of the eye-irritation protocol was required and that applicability was expected mainly for water-soluble chemicals. In 2017, investigators from the same technology lineage published a substantially improved iPSC-derived limbal/corneal epithelial platform and demonstrated comparative ocular cytotoxicity testing with model irritants. Per the user's expert decision, this is classified as case_study_method = 2 (borderline): the later work is transition-relevant and clearly related to the CORNiPSC technology lineage, but the refined LiPSC platform is not demonstrated to be the exact unchanged TM2014-07 assay/protocol required for a direct case-study code 1. No formal independent validation, peer review, OECD project or regulatory adoption of CORNiPSC/LiPSC as an eye-irritation test was identified, so External_evidence_step_stage remains SUB_STOP. Evidence-supported bottlenecks concern validation readiness, water-soluble-chemical applicability, regulatory integration, programme route selection and implementation/scalability of consistent iPSC-derived cell production. Standardisation/adoption is not coded because no documented standardisation process was reached. Three_R_category = Reduction because the assay supplies a non-animal component of an integrated ocular-hazard assessment rather than a demonstrated stand-alone regulatory replacement. Application_domain_expert = Cosmetics; Pharmaceutical / human medicines.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Applicability domain; Regulatory relevance / integration; Programme prioritisation / route selection; Access / implementation","bottleneckCount":"5","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2004-02","shortName":"FL","title":"The fluorescein leakage test method","organisation":"EURL ECVAM - European Union","description":"Various cell types can form tight junctions when cultured in vitro. In the case of the fluorescein leakage test method, Madin Derby Canine Kidney (MDCK) cells can do this in a manner that is very similar to tight junctions found in epithelial cells in the eye and specifically the cornea. This creates a largely impermeable barrier that most chemicals cannot cross. This is also applies to fluorescein, which is a dye that is normally blocked by MDCK cells. In the method, the MDCK cells are grown to confluence (i.e. there are tight junctions between cells) on porous filters and then exposed to a test chemical. Leakage is then assessed by measuring how much fluorescein passes through the cell layer. As such the method tries to model the disruption of the integrity. The test method can be used to assess chemicals and substances that might disrupt tight junctions between epithelial cells that make up the cornea and similar constructs within the eye.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Serious eye damage/Eye irritation","yearReceived":"2004","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=71","lastUpdate":"Monday, October 12, 2020 - 09:13","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Barrier/permeability/transport assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Expert review: The Fluorescein Leakage (FL) test is an in vitro barrier/permeability assay using a confluent MDCK epithelial monolayer. Chemical-induced disruption of tight and desmosomal junctions increases fluorescein permeability, and the FL20 value is used to identify severe ocular irritants/corrosives. Core_methodology = In vitro and Specific_methodologies = Barrier/permeability/transport assay are retained. EXCEPTIONAL PART-A CORRECTION: the uploaded raw TSAR export 'test-methods 240826.csv' contains Step and Stage = 'Validation > Finalised' for TM2004-02 and Last Update = 'Monday, October 12, 2020 - 09:13'. However, the authoritative TSAR event history for the same method records Regulatory acceptance/Standards progression and adoption/publication of OECD TG 460 in October 2012; OECD documentation independently confirms that TG 460 was adopted in 2012. The raw summary field therefore under-represents the established lifecycle. With explicit user approval, this method is treated as a narrowly scoped upstream source/raw-data lifecycle inconsistency and the Part-A lifecycle fields are exceptionally corrected from Validation > Finalised / VAL_FINAL to Regulatory acceptance/Standards > Adopted/published / REG_ADOPT in both TSAR_data and Helper variables. This exception must not be generalised to other TMs without equivalent method-specific evidence. The timing of when the TSAR website event history was populated cannot be established from the available files, so this correction does not claim that the 2020 raw export was necessarily incorrect at the exact moment it was generated; it records that the raw summary is inconsistent with the authoritative lifecycle now established for the method. External_evidence_step_stage = REG_ADOPT. Because the regulatory adoption is part of the TSAR lifecycle rather than external post-TSAR progression, case_study_method = 0 is retained. Historical validation identified readiness, reproducibility/transferability and predictive-performance limitations, including high variability, poor transferability and incomplete predictive performance across broader ocular-irritation categories. These limitations were subsequently managed through standardisation and restriction of regulatory use to identification of Category 1 ocular hazards within a defined applicability domain. The applicability domain remains restricted primarily to water-soluble chemicals, with additional exclusions and limitations for several chemical classes and physical properties. Regulatory relevance/integration remains a bottleneck because FL is intended for use within a tiered/IATA approach rather than as a stand-alone method covering the complete eye-irritation spectrum. Three_R_category = Replacement and animal_use_impact_category = Replacement for the defined regulatory Category 1 decision, because an in-domain positive FL result can replace further animal testing for that classification; this does not imply complete replacement of the Draize test across all ocular-hazard categories. Application_domain_expert = Mixed/general toxicology. Literature_completeness_check is set to Partial because the current OECD TG 460 itself is not stored locally in the TM2004-02 evidence folder.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Applicability domain; Regulatory relevance / integration","bottleneckCount":"5","animalUseImpact":"Replacement","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM1999-01","shortName":"EST","title":"Embryonic Stem Cell Test","organisation":"EURL ECVAM - European Union","description":"The embryonic stem cell system has been developed as a screening test for potentially embryotoxic substances. Disturbances of embryonic stem cell differentiation following treatment of xenobiotics indicate a potential of embryotoxicity for early pre-implantation stages of mammalian development.","stepStage":"Peer-review > Finalised","workflowStep":"Peer-review","workflowStage":"Finalised","topic":"Reproductive toxicity, Embryotoxicity","yearReceived":"1999","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=113","lastUpdate":"Wednesday, October 21, 2020 - 16:12","lastUpdateDate":"2020-10-21","stage":"Validation","status":"Finalised","code":"VAL_PEER_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Embryotoxicity","methodology":"In vitro","specificMethodologies":"Embryo/developmental model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert review: TM1999-01 is the classical mouse Embryonic Stem Cell Test (EST), an in vitro developmental-toxicity assay combining inhibition of embryonic stem-cell differentiation with cytotoxicity measurements in embryonic stem cells and 3T3 fibroblasts. Core_methodology = In vitro is retained. Specific_methodologies is expanded from Embryo/developmental model to Embryo/developmental model; Cytotoxicity/cell viability assay because cytotoxicity measurements are substantive components of the prediction model rather than incidental controls. EXCEPTIONAL PART-A CORRECTION: the uploaded raw TSAR export 'test-methods 240826.csv' contains Step and Stage = 'Submission > Not applicable' for TM1999-01 and Last Update = 'Wednesday, October 21, 2020 - 16:12'. The complete TSAR event history for the same method documents Validation > Finalised in May 2000 and Peer-review > Finalised in October 2001. With explicit user approval, this is treated as a narrowly scoped upstream source/raw-data lifecycle inconsistency and the Part-A lifecycle fields are exceptionally corrected from Submission > Not applicable / SUB_NA to Peer-review > Finalised / VAL_PEER_FINAL in both TSAR_data and Helper variables. This exception must not be generalised without equivalent method-specific evidence. The timing of any later TSAR website backfill cannot be established from the available files, so the correction records the currently established lifecycle rather than claiming that the raw export was necessarily incorrect at the exact time it was generated. Regulatory_stage = Validation and Regulatory_status_detail = Finalised in Helper variables are retained. The original multi-laboratory validation showed good reproducibility and approximately 78% overall accuracy, with excellent detection of strongly embryotoxic chemicals. Subsequent post-TSAR validation-oriented/follow-up work on the classical EST and its use within ReProTect exposed important limits in predictive robustness and broader applicability. This supports case_study_method = 1 because the exact classical EST continued to undergo validation-oriented evaluation outside the complete TSAR record; however, no later formal OECD/regulatory lifecycle stage for the exact method was identified, so External_evidence_step_stage remains VAL_PEER_FINAL. Evidence-supported bottlenecks concern validation readiness, predictive performance, applicability domain, mechanistic coverage, regulatory integration and implementation/throughput. Reproducibility/transferability is not coded as a bottleneck because the formal validation showed acceptable/high reproducibility. Three_R_category and animal_use_impact_category are set to Reduction: EST can reduce animal use as a screening/prioritisation component but does not replace reproductive/developmental toxicity testing as a whole. Application_domain_expert = Mixed/general toxicology. Literature_completeness_check = Partial because key post-TSAR follow-up evidence used in this expert review is not stored in the local TM1999-01 core folder.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_PEER_FINAL","bottlenecks":"Validation readiness / evidence package; Predictive performance; Applicability domain; Mechanistic relevance; Regulatory relevance / integration; Access / implementation","bottleneckCount":"6","animalUseImpact":"Reduction","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM1999-02","shortName":"MM","title":"Micromass Embryotoxicity Assay","organisation":"EURL ECVAM - European Union","description":"The micromass test is based on detecting the ability of toxic chemical compounds to inhibit the formation of cell foci. Embryonic limb mesenchyme or Central Nervous System (CNS) cells (usually mid-brain, which form foci of neurons) from chicken, mouse or rat can be used for the micromass test. The primary culture of limb bud cells of mammalian origin reproduces cartilage histogenesis, a fundamental step in the morphogenesis of the skeleton. When cultured at high cell densities, the cells differentiate to form foci of chondrocytes and neurones, respectively. Various functions, including cell proliferation, cell differentiation, cell to cell communication and cell to extracellular matrix interactions are implicated in this developmental process and the differentiation in vitro and in vivo is very similar both in terms of cell morphology and the specific macromolecules synthesised. The inhibition of mammalian embryogenesis and cell differentiation in vitro is an indication of a potential risk of teratogenicity in vivo. Thus, these cultures were used as a short-term assay system for the prediction of an embryotoxic potential in presence or in absence of a metabolic activating system.","stepStage":"Peer-review > Finalised","workflowStep":"Peer-review","workflowStage":"Finalised","topic":"Reproductive toxicity, Embryotoxicity","yearReceived":"1999","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=122","lastUpdate":"Wednesday, October 21, 2020 - 16:11","lastUpdateDate":"2020-10-21","stage":"Validation","status":"Finalised","code":"VAL_PEER_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Embryotoxicity","methodology":"In vitro","specificMethodologies":"Embryo/developmental model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert review: TM1999-02 is the validated rat limb-bud Micromass Embryotoxicity Assay (MM), an in vitro developmental-toxicity assay using primary embryonic mesenchymal cells cultured at high density. Differentiation is assessed through chondrogenic focus formation/Alcian-blue staining and cell growth/viability can be assessed by neutral-red uptake. Core_methodology = In vitro is retained. Specific_methodologies is corrected from High-content imaging; Embryo/developmental model to Embryo/developmental model; Cytotoxicity/cell viability assay: the assay does not use high-content imaging, while cytotoxicity/cell-growth measurement is an explicit experimental component. EXCEPTIONAL PART-A CORRECTION: the uploaded raw TSAR export 'test-methods 240826.csv' contains Step and Stage = 'Submission > Not applicable' for TM1999-02 and Last Update = 'Wednesday, October 21, 2020 - 16:11'. The complete TSAR event history for the same method documents Validation > Finalised in May 2000 and Peer-review > Finalised in October 2001. With explicit user approval, this is treated as a narrowly scoped upstream source/raw-data lifecycle inconsistency and the Part-A lifecycle fields are exceptionally corrected from Submission > Not applicable / SUB_NA to Peer-review > Finalised / VAL_PEER_FINAL in both TSAR_data and Helper variables. This exception must not be generalised without equivalent method-specific evidence. The timing of any later TSAR website backfill cannot be established from the available files. Regulatory_stage = Validation and Regulatory_status_detail = Finalised are retained. The formal validation showed acceptable reproducibility for the selected limb-bud protocol but revealed materially weaker predictive performance for non-embryotoxic and weakly embryotoxic chemicals than for strongly embryotoxic chemicals. Later ECVAM/ZEBET practical-regulatory review discussed the exact validated embryotoxicity methods and identified further requirements before broad regulatory use. Per the user's expert decision, this is classified as case_study_method = 2 (borderline): the post-TSAR work is clearly acceptance-oriented and directly relevant to MM, but it is better characterised as a regulatory-application/workshop follow-up than as a distinct formal validation or lifecycle-progression event for the exact method. No later formal OECD/regulatory lifecycle stage was identified, so External_evidence_step_stage remains VAL_PEER_FINAL. Evidence-supported bottlenecks concern validation readiness, historical reproducibility/transferability of the broader micromass approach, predictive performance, applicability domain, mechanistic coverage, regulatory integration and implementation. Three_R_category and animal_use_impact_category = Reduction because MM can reduce animal use within a testing strategy but itself still requires primary embryonic material from pregnant rats and does not replace developmental/reproductive toxicity testing as a whole. Application_domain_expert = Mixed/general toxicology. Literature_completeness_check = Partial because the post-TSAR practical-regulatory workshop evidence used here is not stored in the local core folder.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_PEER_FINAL","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Applicability domain; Mechanistic relevance; Regulatory relevance / integration; Access / implementation","bottleneckCount":"7","animalUseImpact":"Reduction","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM1999-03","shortName":"WEC","title":"Postimplantation Rat Whole-Embryo Culture Assay","organisation":"EURL ECVAM - European Union","description":"Rat embryos with 1 to 5 somites are used in this method. In general, these embryos are relatively sensitive for xenobiotics as compared to older embryos. During 48 hours of culture, major aspects of organogenesis occur, including e.g. heart development, closure of the neural tube, development of ear and eye, brachial bars and limb buds. Interference during this period may lead to general retardation of growth and development or to specific malformations in one or several organ anlagen. Embryos are cultured in rotating containers, thus facilitating the exchange of the culture medium with the gaseous phase above. The latter is essential for optimal oxygenation of the culture medium in view of the increasing demand for oxygen of the embryo. After culture, the morphology of the embryos is carefully assessed. Comparison of control embryos with exposed embryos forms the basis for conclusions regarding the embryotoxicity of tested compounds.","stepStage":"Peer-review > Finalised","workflowStep":"Peer-review","workflowStage":"Finalised","topic":"Reproductive toxicity, Embryotoxicity","yearReceived":"1999","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=123","lastUpdate":"Wednesday, October 21, 2020 - 16:10","lastUpdateDate":"2020-10-21","stage":"Validation","status":"Finalised","code":"VAL_PEER_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Embryotoxicity","methodology":"Ex vivo","specificMethodologies":"Embryo/developmental model; Ex vivo/tissue-based assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert review: TM1999-03 is the Postimplantation Rat Whole-Embryo Culture Assay (WEC). Intact postimplantation rat embryos are removed from pregnant animals and cultured ex vivo during a major period of organogenesis, after which growth, morphology, malformations and embryonic viability/death are assessed. Under the project single-value rule, Core_methodology is corrected from In vitro; Ex vivo; Mixed to Ex vivo. Specific_methodologies is corrected from High-content imaging; Embryo/developmental model to Embryo/developmental model; Ex vivo/tissue-based assay because the validated method uses systematic morphological scoring rather than high-content imaging. EXCEPTIONAL PART-A CORRECTION: the uploaded raw TSAR export 'test-methods 240826.csv' contains Step and Stage = 'Submission > Not applicable' for TM1999-03 and Last Update = 'Wednesday, October 21, 2020 - 16:10'. The complete TSAR event history for the same method documents Validation > Finalised in May 2000 and Peer-review > Finalised in October 2001. With explicit user approval, this is treated as a narrowly scoped upstream source/raw-data lifecycle inconsistency and the Part-A lifecycle fields are exceptionally corrected from Submission > Not applicable / SUB_NA to Peer-review > Finalised / VAL_PEER_FINAL in both TSAR_data and Helper variables. This exception must not be generalised without equivalent method-specific evidence. The timing of any later TSAR website backfill cannot be established from the available files. Regulatory_stage = Validation and Regulatory_status_detail = Finalised are retained. The formal validation showed good performance for the combined PM2 model, but the WEC-only PM1 performed less strongly and the original elaborate morphological scoring system required refinement for reproducible use. Post-TSAR evidence includes acceptance-oriented ECVAM/ZEBET review and further validation-oriented application of the same WEC methodology, including category/kinetic investigations. Per the user's expert approval, case_study_method = 1. This represents direct post-TSAR validation-oriented continuation of the exact WEC methodology, although no later formal OECD or regulatory lifecycle stage was identified; External_evidence_step_stage therefore remains VAL_PEER_FINAL. Evidence-supported bottlenecks concern validation readiness, historical reproducibility/transferability, predictive performance, applicability domain, mechanistic context, regulatory integration and implementation. Three_R_category and animal_use_impact_category = Reduction because WEC can reduce the number of whole-animal developmental-toxicity studies within a tiered strategy but itself requires embryos from pregnant rats and does not replace reproductive/developmental toxicity testing as a whole. Application_domain_expert = Mixed/general toxicology. Literature_completeness_check = Partial because key post-TSAR evidence used in this expert review is not stored in the local TM1999-03 core evidence folder.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_PEER_FINAL","bottlenecks":"Validation readiness / evidence package; Reproducibility / transferability; Predictive performance; Applicability domain; Mechanistic relevance; Regulatory relevance / integration; Access / implementation","bottleneckCount":"7","animalUseImpact":"Reduction","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2009-02","shortName":"MELN","title":"Transactivation assay for detection of compounds with (anti)estrogenic potential using MELN cells","organisation":"EURL ECVAM - European Union","description":"The MELN test is an estrogen receptor transactivation assay, assessing the activity of (anti-)estrogenic compounds. The test is based on the human mammary adenocarcinoma cell line (MCF-7). The cells endogenously express the estrogen receptor alpha (ERα), and are stably transfected with a luciferase reporter gene. The test assesses the transcription of the luciferase gene, through the measurement of luminescence, and allows the discrimination between agonists and antagonists. This assay investigates the potential for interaction of a chemical substance with estrogenic nuclear receptors for endogenous hormones and as such investigates early events within an adverse outcome pathway (AOP) associated with perturbation of the endocrine system. Such assay could be used within Integrated Testing Strategy (ITS) or Integrated Approaches to Testing and Assessment (IATA) for identification of endocrine disruptors.","stepStage":"Validation > Stopped","workflowStep":"Validation","workflowStage":"Stopped","topic":"Reproductive toxicity, Endocrine disruption","yearReceived":"2009","generalComments":"Validation stopped after consultation with test submitter","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:01","lastUpdateDate":"2020-10-12","stage":"Validation","status":"Discontinued","code":"VAL_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Expert review: TM2009-02 MELN is an in vitro estrogen-receptor transactivation assay using MCF-7-derived MELN cells that endogenously express ERalpha and carry an estrogen-responsive luciferase reporter. Under the project single-value rule, Core_methodology is corrected from In vitro; Integrated approach; Mixed to In vitro. Specific_methodologies is corrected from Reporter gene assay; Binding/interaction assay; Integrated testing strategy/battery to Reporter gene assay; Cytotoxicity/cell viability assay. The assay measures functional receptor-mediated transcription rather than direct ligand-receptor binding, and although it can contribute to an IATA it is not itself an integrated testing strategy. Cytotoxicity/cell-viability assessment is retained as a substantive supporting assay component because cytotoxicity can otherwise confound apparent anti-estrogenic activity. The protected TSAR lifecycle fields are retained unchanged at Validation > Stopped / VAL_STOP; no Part-A correction is required because the raw summary is consistent with the complete TSAR validation history. The validation route was stopped after consultation with the submitter, with TSAR documenting lack of agreement on conditions for material transfer. Earlier interlaboratory work showed the MELN assay to be transferable, robust and reproducible, so reproducibility/transferability is not coded as a bottleneck. The unfinished validation package nevertheless left the prediction model/application domain incompletely characterised for broad regulatory use. Post-TSAR, the exact MELN method entered OECD Test Guidelines Programme Project 4.64 for intended integration into OECD TG 455. That project was later suspended because of cell-contamination problems. This constitutes direct formal regulatory-standardisation progression outside the TSAR event history and supports case_study_method = 1 and External_evidence_step_stage = REG_DRAFT. No evidence was identified that MELN itself was ultimately adopted as a reference method in TG 455. Evidence-supported bottlenecks concern validation readiness, applicability domain, regulatory integration, programme route selection, access/material-transfer requirements and failed standardisation/adoption progression. Three_R_category and animal_use_impact_category = Reduction because MELN can reduce animal use as a mechanistic screening/IATA component but does not by itself replace endocrine-hazard assessment as a whole. Application_domain_expert = Mixed/general toxicology. Literature_completeness_check = Partial because key external validation and OECD standardisation evidence used in this expert review is not stored in the local TM2009-02 core folder.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_DRAFT","bottlenecks":"Validation readiness / evidence package; Applicability domain; Regulatory relevance / integration; Programme prioritisation / route selection; Access / implementation; Standardisation / regulatory adoption","bottleneckCount":"6","animalUseImpact":"Reduction","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2009-09","shortName":"epiCS SIT","title":"epiCS Skin Irritation Test","organisation":"EURL ECVAM - European Union","description":"The epiCS RHE SIT test method addresses the skin irritation endpoint. It intends to make predictions of skin irritancy potential on the basis of the United Nations (UN) Global Harmonized Systems for classification and labelling (GHS). The test system is composed of Reconstructed human Epidermis (RhE) tissues. This model constitutes a three dimensional structure which reproduces the typical multi-layer cell organization of the epidermis. The tissues are exposed to the test chemicals during 20 minutes. This is followed by a post-exposure period of 24±2 hours in order to derive the cell viability of the tissues. Mitochondrial dehydrogenases of living cells are able to reduce the MTT reagent into blue formazan. The Sterlab RHE SIT protocol measures the optical density (OD) of the blue formazan in the treated tissues. The OD is normalised to the one of the negative control in order to express cell viability values in percentages. Test chemicals lead to a positive response when the cell viability values are below or equal to 50%, while a negative response is found when cell viability values are above 50%. On the basis of the UN GHS a positive response should be labelled as \"Classified\" whereas a negative response should be labelled as \"Not Classified\". A prediction as \"Classified\" means that the test chemical could be either a skin irritant or a skin corrosive. The epiCS RHE SIT protocol is intended to be potentially used for the prediction of acute skin irritation in regulatory safety testing under the UN GHS, REACH, EU Classification, Labelling and Packaging of substances and mixtures (CLP) or Cosmetic Directive for chemicals. The OECD published an \"Integrated Approach on Testing and Assessment (IATA) for Skin Corrosion and Skin Irritation\" which shows how proper interpretation of skin irritation and skin corrosion tests should be performed and how additional tests should be eventually conducted to evaluate the skin irritation and corrosion potential of chemicals. The ECHA published the \"REACH Guidance on Information Requirements and Chemical Safety Assessment\" which makes reference to this OECD IATA and includes a testing strategy based on it.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin irritation","yearReceived":"2009","generalComments":"ESAC peer review requested additional testing","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:02","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Skin irritation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). The epiCS Skin Irritation Test (epiCS SIT) is an in vitro test method utilizing a 3D reconstructed human epidermis (RhE) model composed of normal human epidermal keratinocytes. Following 20 minutes topical chemical exposure and a 24-hour post-incubation, tissue viability is measured via mitochondrial MTT reduction into blue formazan (tissue viability <= 50% classifies as skin irritant, UN GHS Category 2; > 50% as non-irritant). Core methodology is corrected from In vitro; Integrated approach; Mixed to In vitro (the contextual mention of OECD IATA in the description does not make this standalone tissue model Mixed). Specific methodologies are corrected to Organoid/3D tissue model; Cytotoxicity/cell viability assay (2 labels), removing the AI artifact Integrated testing strategy/battery. Application domain is confirmed as Cosmetics; Industrial chemicals. 3R impact is classified as Replacement (Three_R_category and animal_use_impact_category) because OECD TG 439 provides full standalone replacement for the Draize rabbit skin irritation test (OECD TG 404). Lineage is confirmed as an original standalone submission (is_resubmission = 0, TM_family_id = TM2009-09, generation = 0, Original submission), distinct from TM2007-01 which addresses skin corrosion. Bottleneck audit: validation readiness signal is confirmed (1) due to 2012 variability criteria gap (resolved); predictive performance signal is confirmed (1) due to 2014 ESAC supplementary testing requirement (resolved); applicability domain signal is corrected from 1 to 0 (AI false positive on Recommendation: Not applicable); regulatory relevance signal is corrected from 1 to 0 (AI false positive on IATA mention); standardisation signal is confirmed as 0. Case study status is coded as case_study_method = 0 with External_evidence_step_stage = REG_ADOPT, reflecting formal adoption under OECD Test Guideline 439 in June 2019.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package; Predictive performance","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2013-02","shortName":"U-SENS™","title":"U-SENS™ - Myeloid U937 Skin Sensitisation Test","organisation":"EURL ECVAM - European Union","description":"The U-SENS assay supports the discrimination between sensitizing and non-sensitizing chemicals. It addresses one of the biological mechanisms described under key event 3 (events in dendritic cells (DC)) of the skin sensitization Adverse Outcome Pathway (AOP) by measuring the induction of the CD86 protein marker in U937 cells. The U937 cells are human myeloid cells used as surrogate model for DCs. U937 is a cell line established from a diffuse histiocytic lymphoma with the advantage of higher stability and the easiness of maintenance compared to human-blood derived DCs. Although being of monocytic origin, U937 cells have shown DC-like responses following exposure to sensitizers including the up-regulation of surface marker (e.g. CD86) and cytokine production (e.g. TNF-a). The up-regulation of CD86 plays important roles in the induction of Allergic Contact Dermatitis (ACD). The CD86 protein marker is a costimulatory factor which is upregulated in mature DCs and plays a pivotal role in antigen presentation and subsequent T cell priming. It is one of the most frequently used biomarkers in in vitro assays indicating DC activation and has been shown to be the most suitable and robust marker in U937 cells. In the U-SENS™ test method, the modulation of the CD86 membrane marker in U937 cells is measured by flow cytometry after a 45 hours exposure to test chemicals.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin sensitisation","yearReceived":"2013","generalComments":"The U-SENS™ test method was formely called Myeloid U937 Skin Sensitisation Test (MUSST) (TM 2009-05).","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=183","lastUpdate":"Monday, October 12, 2020 - 08:41","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Immunoassay/flow cytometry","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). U-SENS™ (Myeloid U937 Skin Sensitisation Test) is an in vitro test method measuring the induction of the costimulatory protein marker CD86 on human myeloid U937 cells by flow cytometry after 45 hours exposure to test chemicals. It addresses Key Event 3 of the Skin Sensitisation AOP. Core methodology is confirmed as In vitro; specific methodologies confirmed as Immunoassay/flow cytometry (1 label). Application domain is expanded to Cosmetics; Industrial chemicals in alignment with OECD TG 442E and REACH. 3R impact is classified as Reduction (Three_R_category and animal_use_impact_category) because individual in vitro KE3 testing screens/reduces animal use (LLNA) and serves as an essential building block in Defined Approaches (OECD GL 497) but cannot standalone replace the complete in vivo testing battery. Lineage is confirmed as Gen 1 successor to TM2009-05 (MUSST) within TM_family_id TM2009-05. Bottlenecks: all 10 signals are confirmed as 0 as the method completed validation, ESAC peer review (2016-03), EURL ECVAM recommendation (2017), and global adoption under OECD TG 442E (October 2017). User explicitly instructed to update NEW_STEP_STAGE to REG_ADOPT due to snapshot omission; External_evidence_step_stage is REG_ADOPT, case_study_method = 0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2010-02","shortName":"PALM cell assay","title":"Transactivation assay for detection of compounds with (anti)androgenic potential using PALM cells","organisation":"EURL ECVAM - European Union","description":"The \"PALM\" test is an androgen receptor transactivation assay, assessing the activity of (anti-)androgenic compounds. The test is based on a human prostate cancer cell line (PC-3). The cells are stably co-transfected with the full length human androgen receptor (AR) and a luciferase reporter gene. The test assesses the transcription of the luciferase gene, through the measurement of luminescence, and allows the discrimination between agonists and antagonists. These assays investigate the potential for interaction of a chemical substance with nuclear receptors for endogenous hormones and as such investigate early events within an adverse outcome pathway (AOP) associated with perturbation of the endocrine system. Such assays could be used within an Integrated Testing Strategy (ITS) or Integrated Approaches to Testing and Assessment (IATA) for identification of endocrine disruptors.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Reproductive toxicity, Endocrine disruption","yearReceived":"2010","generalComments":"Not prioritised for validation by ECVAM due to issues regarding the material transfer agreement","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:54","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). The PALM cell assay is an in vitro human prostate cancer (PC-3) cell line reporter gene assay stably co-transfected with full-length human androgen receptor (AR) and a luciferase reporter gene. It functionally discriminates androgen agonists and antagonists. Core methodology is corrected from In vitro; Integrated approach; Mixed to In vitro, as PALM is a single in vitro cell assay; the contextual mention of possible use within an ITS/IATA does not make the assay an integrated testing strategy or Mixed. Specific methodologies are corrected to Reporter gene assay (1 label), removing AI artifacts Binding/interaction assay and Integrated testing strategy/battery. Application domain is assigned as Industrial chemicals; Mixed/general toxicology. 3R impact is classified as Reduction (Three_R_category and animal_use_impact_category) because AR transactivation screening identifies endocrine disruptors and reduces animal use (e.g. Hershberger bioassay, OECD TG 441) but cannot standalone replace in vivo mammalian reproductive toxicity testing. Lineage is confirmed as an original standalone submission (is_resubmission = 0, TM_family_id = TM2010-02, generation = 0, Original submission). Bottleneck audit: standardisation signal is corrected to 0 as the method ended at submission; validation readiness signal is confirmed (1); access/implementation barrier signal is corrected to 1 because unresolved Material Transfer Agreement (MTA) issues with the test system owner explicitly prevented validation; programme prioritisation signal is confirmed (1) as EURL ECVAM formally closed the submission in June 2013. Case study status is coded as case_study_method = 0 with External_evidence_step_stage = SUB_STOP.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection; Access / implementation","bottleneckCount":"3","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2010-01","shortName":"ARBA","title":"Rat recombinant androgen receptor binding assay for the detection of compounds with (anti)androgenic potential","organisation":"EURL ECVAM - European Union","description":"The Androgen Receptor Binding Assay (ARBA) uses a rat recombinant protein, comprising the hinge region and Ligand Binding Domain (LBD) of the receptor, tagged with thioredoxin. It should be noted that the amino acid sequence of the rat receptor is homologous to the human one. This test measures the capability of a chemical to bind to the androgen receptor, by using a radioactive readout. The binding assays do not allow discrimination between agonists and antagonists. The assay is a non-cell based assay. These assays investigate the potential for interaction of a chemical substance with nuclear receptors for endogenous hormones and as such investigate early events within an adverse outcome pathway (AOP) associated with perturbation of the endocrine system. Such assays could be used within an Integrated Testing Strategy (ITS) or Integrated Approaches to Testing and Assessment (IATA) for identification of endocrine disruptors.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Reproductive toxicity, Endocrine disruption","yearReceived":"2010","generalComments":"Not prioritised for validation by ECVAM","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:54","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Endocrine disruption","methodology":"In vitro","specificMethodologies":"Binding/interaction assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). The Rat recombinant androgen receptor binding assay (ARBA) is a cell-free biochemical ligand-binding assay using a recombinant rat androgen receptor fragment (hinge region and LBD tagged with thioredoxin) with a radioactive displacement readout. It addresses the Molecular Initiating Event (MIE) of the endocrine disruption AOP (binding to AR). Core methodology is corrected from In vitro; Integrated approach; Mixed to In vitro, as ARBA is a single biochemical assay; the contextual mention of possible use within an ITS/IATA does not make the assay an integrated testing strategy or Mixed. Specific methodologies are corrected to Binding/interaction assay (1 label), removing the AI artifact Integrated testing strategy/battery. Application domain is assigned as Industrial chemicals; Mixed/general toxicology. 3R impact is classified as Reduction (Three_R_category and animal_use_impact_category) because receptor binding screening identifies AR interaction and reduces animal use (e.g. Hershberger assay, OECD TG 441) but cannot standalone replace in vivo reproductive toxicity testing. Lineage is confirmed as an original standalone submission (is_resubmission = 0, TM_family_id = TM2010-01, generation = 0, Original submission). Bottleneck audit: standardisation signal is corrected to 0 as the method ended at submission; validation readiness signal is confirmed (1) due to absence of a standardized multi-laboratory validation dossier; programme prioritisation signal is confirmed (1) as EURL ECVAM formally communicated non-prioritisation in August 2012. Case study status is coded as case_study_method = 0 with External_evidence_step_stage = SUB_STOP.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2014-01","shortName":"RTgill-W1","title":"Fish cell line acute toxicity test","organisation":"EURL ECVAM - European Union","description":"The rainbow trout gill (RTgill-W1) cell line assay is a cytotoxicity test which has the potential to predict fish acute toxicity. Gill cells were chosen for this assay since gills are one of the main barriers between the fish and its surrounding water. Therefore fish gills are a major target site for environmental toxicants. RTgill-W1 cells are seeded into 24-well plates and are incubated for 24 hours to attach and form a monolayer. Then they are exposed to a series of test chemical concentrations for a period of 24 hours. Exposure is performed with a minimal essential medium (L-15/ex) not containing bovine serum whereas normal L-15 cell culture medium containing bovine serum is used for the initial incubation. Cytotoxicity is determined using a combination of three endpoints representing cell viability: cellular metabolic activity measured with AlamarBlue, cell membrane integrity measured with 5-carboxyfluorescein diacetate acetoxymethyl ester (CFDA-AM) and lysosomal membrane integrity measured with Neutral Red. Cell viability is expressed in % of the negative control. The respective EC50 value is calculated for each endpoint and EC50 calculation is based on measured exposure concentration. The most sensitive of the three endpoints is used for prediction of fish acute toxicity (based on 35 chemicals tested at the time of the submission EC50 would correspond to LC in fish). Acute fish toxicity tests are e.g. part of the data requirements for REACH (10t or more) and are often required for safety testing of effluents. The RTgill-W1 cell line assay should support prediction of acute fish toxicity. Chemicals with a specific neurotoxic mode of action and compounds that may be activated via metabolism were found to cause less toxicity in RTgill-W1 cells compared to fish.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Fish acute toxicity","yearReceived":"2014","generalComments":"","protocolSop":"","lastUpdate":"Wednesday, October 14, 2020 - 09:52","lastUpdateDate":"2020-10-14","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Environmental; Industrial chemicals","endpoint":"Aquatic toxicity","methodology":"In vitro","specificMethodologies":"HTS; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). The rainbow trout gill cell line assay (RTgill-W1) is an in vitro cytotoxicity test using a permanent gill epithelial cell line exposed in protein-free L-15/ex medium for 24 hours across a chemical concentration series. Viability is assessed multiparametrically using AlamarBlue (metabolic activity), CFDA-AM (membrane integrity), and Neutral Red (lysosomal integrity) to derive EC50 values predictive of acute fish lethality (LC50 equivalent to OECD TG 203). Core methodology is In vitro; specific methodologies are confirmed as HTS; Cytotoxicity/cell viability assay (2 labels). Application domain is confirmed as Environmental; Industrial chemicals. 3R impact is classified as Replacement (Three_R_category and animal_use_impact_category) because it directly substitutes live fish in acute aquatic lethality testing under REACH and environmental effluent monitoring. Lineage is confirmed as an original standalone submission (is_resubmission = 0, TM_family_id = TM2014-01, generation = 0, Original submission). Bottleneck audit: standardisation signal is corrected to 0 because the assay successfully achieved regulatory adoption; validation readiness signal is confirmed (1) due to historical completeness check gaps in 2018; programme prioritisation signal is confirmed (1) due to strategic transfer from the ECVAM track to the OECD Test Guidelines Programme in April 2019. Coded as a prime Level 1 Case Study (case_study_method = 1) with External_evidence_step_stage = REG_ADOPT, reflecting full regulatory adoption as OECD Test Guideline 249 in June 2021 despite closure of the TSAR submission track.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Environmental; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2011-07","shortName":"DCMA","title":"Dendritic Cell Migration Assay for distinguishing sensitizers from non-sensitizers (including irritants)","organisation":"EURL ECVAM - European Union","description":"The Dendritic Cell Migration Assay (DCMA) is an in vitro method for the identification of sensitisers based on the evaluation of Denditric Cells migration. It is designed for dichotomous classification (S/NS) and does not provide additional information on potency. DCMA addresses the migration of Langerhans Cells (LC) from the epidermis to the regional lymph nodes which is considered to be one of the key events involved in the induction of skin sensitization. The migration is associated with increased levels of the CXCR4 receptor and decreased levels of the CCR5 receptor on maturing LC, and with increased secretion of the chemokine CXCL12 by dermal fibroblasts. Driven by the CXCR4-CXCL12 interaction, the maturing LCs eventually travel from the dermis to the lymph nodes where they prime T cells and induce sensitization. This process is mimicked in vitro using human keratinocyte and fibroblast cultures in a two compartment test system, and is simplified by replacing the fibroblasts by the recombinant counterparts of the chemokines involved (CXCL12 and CCL5). The test is based on the human myelomonocytic cell line MUTZ-3 which was identified as the human dendritic cell-like cell line that is closest to human monocyte derived DC (high functional relevance). MUTZ-3 cells are differentiated into immature MUTZ-LC. They are then fluorescently labelled with CSFE. On the basis of the differential migration (amount of fluorescent MUTZ-LC entering the lower transwell) skin and lung sensitisers are discriminated from non-sensitisers and irritants. If the chemical is a sensitizer, MUTZ-LC will mature, up-regulate CXCR4 and preferentially migrate towards CXCL12. If the chemical is an irritant, no up-regulation of CXCL12 occurs, CCR5 expression is maintained and MUTZ-LC preferentially migrate towards CCL5.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Sensitisation","yearReceived":"2011","generalComments":"Not considered for follow-up","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:50","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Cytotoxicity/cell viability assay; Immunoassay/flow cytometry","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). The Dendritic Cell Migration Assay (DCMA) is an in vitro method using the human myelomonocytic cell line MUTZ-3 differentiated into Langerhans cell-like dendritic cells (MUTZ-LC) in a two-compartment transwell system. It addresses Key Event 3 of the Skin Sensitisation AOP (dendritic cell activation and migration) based on differential chemotactic migration towards CXCL12 vs. CCL5 driven by chemokine receptor switching (CXCR4 upregulation / CCR5 downregulation). Endpoint category is corrected from Sensitisation — unspecified to Skin sensitisation (with skin_sensitisation_endp set to 1) in alignment with the precedent of TM2011-12. Core methodology is confirmed as In vitro. Specific methodologies are corrected from Organoid/3D tissue model to Cytotoxicity/cell viability assay; Immunoassay/flow cytometry (2 labels), reflecting the cell-viability threshold monitoring and fluorescence-based migrated cell counting. Application domain is confirmed as Cosmetics; Industrial chemicals. 3R impact is classified as Reduction (Three_R_category and animal_use_impact_category) because standalone dichotomous in vitro KE3 testing screens/reduces animal use but cannot replace the full in vivo testing battery without an integrated Defined Approach. Lineage is confirmed as an original standalone pre-submission (is_resubmission = 0, TM_family_id = TM2011-07, generation = 0, Original submission). Bottleneck audit: standardisation signal is corrected to 0 as the method ended at pre-submission; validation readiness signal is confirmed (1) due to insufficient inter-laboratory evidence package in 2013; programme prioritisation signal is confirmed (1) as EURL ECVAM closed the track in Feb 2013 due to prioritisation of alternative KE3 assays (h-CLAT, MUSST). Case study status is coded as case_study_method = 0 with External_evidence_step_stage = SUB_STOP.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2008-11","shortName":"CPA-I test","title":"CPA-I test","organisation":"EURL ECVAM - European Union","description":"The CPA-I test aims to identify the proteins associated with type I (IgE mediated) hypersensitivity reactions. The immune response in hypersensitivity reactions towards proteins are mainly of IgE/Th2 cell type (i.e. the type I hypersensitivity reaction). The CPA-I exploits inherent characteristics of proteins, which enable them to polarize the subsequent immune response- as demonstrated by the production of neopterin, a specific immune modulator. The test utilizes a human myleomonocytic cell line, that is cultivated for 48 hrs in the presence of serial dilutions (within the range of non- toxic concentrations) of the test substance. Supernatants are collected and the concentration of neopterin is measured using ELISA. For each substance, a dose response curve is established. The cells are cultivated in serum free media. Cell viability is determined by propidium iodide (PI). The potential allergens to be tested can be tested as component of extracts or in pure native form.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin sensitisation","yearReceived":"2008","generalComments":"Not considered for follow-up","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:06","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Cytotoxicity/cell viability assay; Immunoassay/flow cytometry","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). The CPA-I test (Cellular Phenotypic Assay Type I) is an in vitro assay utilizing a human myelomonocytic cell line cultivated in serum-free medium for 48 hours to assess protein-induced type I (IgE-mediated) hypersensitivity. Test substances are evaluated across serial non-cytotoxic concentrations with viability monitored by propidium iodide (PI). Immune polarization is quantified by measuring secreted neopterin in supernatants using ELISA. The method serves as a mechanistic screening tool to reduce animal use (Three_R_category and animal_use_impact_category assigned as Reduction), though it cannot stand alone as a full replacement for in vivo sensitisation testing batteries. Core methodology is confirmed as In vitro; specific methodologies are confirmed as Cytotoxicity/cell viability assay; Immunoassay/flow cytometry (2 labels). Application domain is expanded to Cosmetics; Food safety; Pharmaceutical / human medicines. Lineage is verified as an original standalone pre-submission (is_resubmission = 0, TM_family_id = TM2008-11, generation = 0, Original submission). Bottleneck audit: standardisation signal is corrected to 0 as the method ended at pre-submission; validation readiness signal is confirmed (1) due to absence of a standardized multi-laboratory package; programme prioritisation signal is confirmed (1) as EURL ECVAM formally communicated non-prioritisation in November 2008. Case study status is coded as case_study_method = 0 with External_evidence_step_stage = SUB_STOP as the lifecycle concluded in TSAR without external standardisation under this dossier.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Food safety; Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2011-14","shortName":"In vitro STS","title":"In vitro sensitisation testing strategy","organisation":"EURL ECVAM - European Union","description":"In vitro STS describes the use of a testing strategy based on existing methods that has a sufficient predictive capacity to be used as a stand-alone method for sensitisation testing. It addresses the first three key events (KE) of the of the skin sensitization Adverse Outcome Pathway (AOP). These key events are measured by formally validated and peer-reviewed methods, i.e. KE1 protein binding: DPRA (OECD TG 442C), KE2 keratinocyte activation: KeratinosensTM (OECD TG 442D), LuSens (ESAC reviewed) and KE3 dentritic cell activation: h-CLAT (OECD TG 442E), MUSST (ESAC reviewed). These methods constitute the main components of the testing strategy.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin sensitisation","yearReceived":"2011","generalComments":"Not considered for follow-up, skin sensitisation IATAs are currently being addressed in the OECD Task Force on Hazard Assessment","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:51","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Skin sensitisation","methodology":"Mixed","specificMethodologies":"Binding/interaction assay; Chemical reactivity assay; Integrated testing strategy/battery","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). In vitro STS is an integrated skin sensitisation testing strategy combining validated test methods across the first three Key Events of the Skin Sensitisation AOP: KE1 protein reactivity (DPRA), KE2 keratinocyte activation (KeratinoSens/LuSens), and KE3 dendritic cell activation (h-CLAT/MUSST). The strategy was designed to serve as a stand-alone replacement for in vivo animal tests (LLNA, OECD TG 429; GPMT, OECD TG 406) for hazard identification (serving an intended 3R role of Replacement). Core methodology is set to 'Mixed' as the strategy integrates distinct in chemico and in vitro domains. Specific methodologies are confirmed as 'Binding/interaction assay; Chemical reactivity assay; Integrated testing strategy/battery' (3 labels). Application domain is assigned as 'Cosmetics; Industrial chemicals'. Lineage is confirmed as an original standalone pre-submission (is_resubmission = 0, TM_family_id = TM2011-14, generation = 0, relationship = Original submission) without predecessor or successor strategies in TSAR. Bottlenecks evaluated: standardisation signal is corrected to 0 as the review ended at pre-submission; signals are confirmed for validation readiness (lack of standardized validation package for the combined decision logic), regulatory relevance / integration (need for international framework for Defined Approaches), and programme prioritisation / route selection (EURL ECVAM formally closed the submission in June 2013 because skin sensitisation IATAs were transferred to the OECD Task Force on Hazard Assessment, which later culminated in OECD Guideline 497 in 2021). Case study status is coded as case_study_method = 0 (External_evidence_step_stage = SUB_STOP) because the pre-submission lifecycle concluded within TSAR without direct external standardisation under this dossier.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"3","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2008-12","shortName":"Valitox","title":"Valitox an alternative in vitro toxicity assay","organisation":"EURL ECVAM - European Union","description":"Fluorescent method that allows for analysis of cell death through plasma membrane permeation detection. The cell impermeant SYTOX DNA binding dye was used. In dying or dead cells the dye crosses the plasma membrane, reaches the nucleus and binds DNA leading to an increase of fuorescent signal. The concentration of a chemical that is lethal to 50% of HeLa cells (LC50) is calculated. The ultimate aim is to predict acute human toxicity. This method was later officially submitted as DAP (Dequenching after photobleaching cytotoxicity test). See TM2011-01","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Acute toxicity","yearReceived":"2008","generalComments":"This method was later officially submitted as DAP (Dequenching after photobleaching cytotoxicity test). See TM2011-01","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:06","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Acute toxicity","methodology":"In vitro","specificMethodologies":"Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). Valitox is an in vitro basal cytotoxicity assay utilising human HeLa cells cultured in microplates to evaluate cell death via plasma membrane permeabilisation. The assay uses the cell-impermeant nucleic acid dye SYTOX, which enters dead or dying cells with compromised membranes, binds nuclear DNA, and emits a strong fluorescent signal. By measuring fluorescence across chemical concentrations, the 50% lethal concentration (LC50) is derived to predict human acute systemic toxicity (serving an intended 3R role of Reduction). Core methodology is corrected from 'In vitro; In chemico; Mixed' to 'In vitro' as this is a cellular cell-viability assay with no independent abiotical in chemico step. Specific methodologies are corrected from 'Cytotoxicity/cell viability assay; Phototoxicity/photoreactivity assay; Bioaccessibility/bioelution assay' to 'Cytotoxicity/cell viability assay' (1 label), eliminating erroneous AI tags for phototoxicity and bioelution. Application domain is assigned as 'Pharmaceutical / human medicines; Industrial chemicals; Cosmetics'. Lineage is confirmed as the founding submission (generation 0, is_resubmission = 0, TM_family_id = TM2008-12, relationship = Original submission) of the Valitox/DAP/LUCS family; it was formally closed in April 2011 upon being officially resubmitted as TM2011-01 (generation 1), and later succeeded by TM2014-05 (generation 2) and TM2021-01 (generation 3). Bottlenecks evaluated: standardisation signal is corrected to 0 as the review ended at pre-submission; signals are confirmed for validation readiness (initial informal report lacked official form and complete validation data) and programme prioritisation / route selection (closure due to formal replacement by TM2011-01). Case study status is coded as case_study_method = 0 (External_evidence_step_stage = SUB_STOP) because the submission lifecycle concluded fully within TSAR without external standardisation.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Pharmaceutical / human medicines; Industrial chemicals; Cosmetics","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2006-01","shortName":"ZFET","title":"Zebrafish embryo acute toxicity test for acute fish toxicity testing","organisation":"EURL ECVAM - European Union","description":"The zebrafish embryo acute toxicity test method (ZFET) is carried out with newly fertilised eggs from zebrafish (Danio rerio). It is an acute test that uses short-term exposure (96 hours) and determines the concentration of a chemical that is lethal to 50% of zebrafish embryos (LC50) as a prediction of acute fish toxicity. The following observations indicate death of an embryo: coagulation of the embryo, lack of somite formation, non-detachment of the tail and/or lack of heartbeat.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Fish acute toxicity","yearReceived":"2006","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=140","lastUpdate":"Monday, October 12, 2020 - 09:08","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Environmental","endpoint":"Aquatic toxicity","methodology":"In vivo","specificMethodologies":"Embryo/developmental model","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). The Zebrafish Embryo Acute Toxicity Test (ZFET) is an acute aquatic ecotoxicity test method utilizing newly fertilised eggs of the zebrafish (Danio rerio) exposed individually in 24-well plates for 96 hours to derive a median lethal concentration (LC50) based on four apical lethality markers (coagulation of embryos, lack of somite formation, non-detachment of tail-bud, and absence of heartbeat). The test was coordinated by EURL ECVAM on behalf of the OECD and formally adopted in July 2013 as OECD Test Guideline 236 (OECD TG 236). Core methodology is confirmed as In vivo (reflecting whole-organism embryonic testing in environmental ecotoxicology, although legally non-animal under EU Directive 2010/63/EU as non-independently feeding forms < 120 hpf). Specific methodologies are corrected from 'Cytotoxicity/cell viability assay; Embryo/developmental model' to 'Embryo/developmental model' (1 label), removing the erroneous cytotoxicity tag as ZFET measures whole-embryo developmental mortality, not cellular cytotoxicity in culture. Application domain is assigned as 'Environmental; Industrial chemicals'. Lineage is confirmed as an original standalone submission (is_resubmission = 0, TM_family_id = TM2006-01, generation = 0, relationship = Original submission). 3R classification is assigned as Replacement (serving the intended regulatory role of replacing the adult fish acute toxicity test, OECD TG 203, for acute aquatic hazard classification and labelling under GHS/CLP; under REACH, it is often implemented within a Weight of Evidence approach achieving Reduction). Bottlenecks evaluated: signals are confirmed for applicability domain (chorion permeability barrier for bulky/high-MW molecules and immature Phase I metabolic activation) and regulatory relevance / integration (ECHA restrictions under REACH requiring WoE rather than direct standalone 1-to-1 replacement of TG 203). Case study status is coded as case_study_method = 0 (External_evidence_step_stage = REG_ADOPT) because the full trajectory from validation to formal OECD TG 236 adoption in 2013 is already documented and contained within the complete TSAR event history.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain; Regulatory relevance / integration","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Environmental; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2015-01","shortName":"HAD BoNT","title":"Hemi-Diaphragm Assay (HDA) for detection and quantification of botulinum neurotoxins (BoNT)","organisation":"EURL ECVAM - European Union","description":"The Hemi-Diaphragm Assay (HDA) is an ex vivo assay using phrenical hemidiaphragm preparations from mice for detection and quantification of botulinum neurotoxins (BoNT). BoNT inhibit the release of acetylcholine from peripheral nerve endings and this inhibition can be detected in isolated nerve-muscle preparations, e.g. phrenical hemidiaphragm preparations. The tissue preparation is maintained in an organ bath. Via ring electrodes the nerve is stimulated by an electric pulse followed by muscle contraction. The contraction amplitude is recorded and decreases when BoNT acts in the nerve endings. The time period between application of toxin and half maximum contraction amplitude (inflection point) is read out parameter. The variants of BoNT can be identified by specific antibodies. The submitter claims that the HDA test is applicable to analyse food and environmental samples for contamination with BoNT, human or veterinarian samples (blood and stool) in case of suspicious intoxications (e.g. bioterrorism), to test cosmetic and pharmaceutical products containing BoNT for batch release, to analyse human sera for specific anti-BoNT antibodies that may appear after treatment with BoNT and the test is a valuable tool in research. In many cases, mice are used for this purpose, developing Botulism disease in the presence of BoNT and subsequently die due to respiratory failure. The phrenical hemidiaphragm preparations are derived from humanely killed mice. Apart from the refinement aspect, the submitter claims that the HDA has reduction potential.","stepStage":"Submission > Not considered for validation","workflowStep":"Submission","workflowStage":"Not considered for validation","topic":"Detection of contaminations","yearReceived":"2015","generalComments":"Not considered for follow-up","protocolSop":"","lastUpdate":"Wednesday, October 14, 2020 - 09:14","lastUpdateDate":"2020-10-14","stage":"Test Submission","status":"Discontinued","code":"SUB_NOTVAL","applicationDomain":"Cosmetics; Environmental; Pharmaceutical; Food safety","endpoint":"Contamination detection","methodology":"Ex vivo","specificMethodologies":"Ex vivo/tissue-based assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). The Hemi-Diaphragm Assay (HDA / HAD BoNT) is an ex vivo neuromuscular physiological assay utilising isolated mouse phrenic nerve–hemidiaphragm preparations mounted in an organ bath under continuous electrical stimulation (typically 1 Hz) to detect and quantify biologically active botulinum neurotoxins (BoNT serotypes A, B, E, etc.). The assay measures the time-dependent decrease in isometric muscle contraction amplitude (with the inflection point or time to half-maximum contraction amplitude, t50, serving as the quantitative readout parameter), reflecting BoNT-induced inhibition of vesicular acetylcholine release at the motor endplate. Core methodology is confirmed as Ex vivo. Specific methodologies are corrected from 'Immunoassay/flow cytometry; Ex vivo/tissue-based assay' to 'Ex vivo/tissue-based assay' (1 label), removing the erroneous immunoassay/flow cytometry tag as the readout is electro-mechanical muscle force displacement, not an antibody-based optical detection. Application domain is assigned as 'Pharmaceutical / human medicines; Cosmetics; Food safety; Environmental'. Lineage: verified as an original standalone pre-submission (is_resubmission = 0, TM_family_id = TM2015-01, resubmission_generation = 0, relationship = Original submission) with no predecessors or successors in TSAR; no re-submission was ever submitted to TSAR. Outside TSAR, the assay is widely known as the MPN / mPNHD assay (Mouse Phrenic Nerve Hemidiaphragm assay, established by Bigalke / Toxogen/Toxologics), referenced in Ph. Eur. monograph 2113 since 2005 and used for reference characterisation (EQuATox) and clinical neutralizing antibody testing. 3R classification is confirmed as Reduction (and animal_use_impact_category = Reduction), because while humanely euthanizing mice eliminates the severe distress of in vivo botulism lethality (LD50) testing (providing substantial refinement), it still requires animal-derived neuromuscular tissue (subsequent regulatory Replacement for BoNT batch release was achieved via cell-based potency assays directly with medicines agencies). Bottlenecks evaluated: signals are confirmed for validation readiness (lack of a standardized multi-laboratory validation dossier) and programme prioritisation / route selection (EURL ECVAM formally concluded in June 2015 that the method was not considered for follow-up validation). Case study status is coded as case_study_method = 0 (External_evidence_step_stage = SUB_NOTVAL) because the pre-submission lifecycle concluded fully within TSAR without external standardisation arising from this dossier.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_NOTVAL","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Pharmaceutical / human medicines; Cosmetics; Food safety; Environmental","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2014-05","shortName":"LUCS","title":"Light Up Cell Systems","organisation":"EURL ECVAM - European Union","description":"In vitro test method designed to predict and classify acute and geno-toxicity. The test method measures nucleic acid alteration in live cells through fluorescence readout in 96- or 384-well plates. The underlying cellular mechanism involves DNA and/or RNA damage by Reactive Oxygen Species (ROS). It takes advantage of the ROS-induced variations in fluorescence intensities in cells incubated with a membrane-permeant nucleic acid sensor of the cyanine asymmetrical family. It is proposed as a replacement of the 3T3-NRU assay in all its applications including phototoxicity and applicable also to skin corrosion and irritation regulatory testing under REACH cosmetics and biocides.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Acute toxicity","yearReceived":"2014","generalComments":"Not prioritised for validation by ECVAM since it has not fulfilled ECVAM requirements.","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:35","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Acute toxicity","methodology":"In vitro","specificMethodologies":"HTS; Cytotoxicity/cell viability assay; Biomarker/DNA damage assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). Light Up Cell Systems (LUCS) is an in vitro high-throughput cytotoxicity screening method (implemented in 96- and 384-well microplates) evaluating intracellular oxidative stress (ROS-induced homeostasis disruption) and nucleic acid alterations via photo-induced fluorescence dequenching of an asymmetric cyanine dye (such as Thiazole Orange). The assay derives IC50 values to predict acute systemic toxicity (serving an intended 3R role of Reduction). Core methodology is confirmed as In vitro; Specific methodologies are refined from 'Omics; HTS; Cytotoxicity/cell viability assay; Phototoxicity/photoreactivity assay' to 'HTS; Cytotoxicity/cell viability assay; Biomarker/DNA damage assay' (3 labels), removing non-applicable Omics and Phototoxicity tags. Application domain is assigned as 'Cosmetics; Industrial chemicals; Pharmaceutical / human medicines'. Lineage is verified as a direct member of the Valitox/DAP/LUCS family: TM2014-05 represents generation 2 (is_resubmission = 1, predecessor_TM_id = TM2011-01, TM_family_id = TM2008-12, relationship = Successor version), succeeding TM2011-01 and later followed by TM2021-01 (generation 3). Bottlenecks evaluated: standardisation signal is corrected to 0 as the review ended at pre-submission; signals are confirmed for validation readiness (EURL ECVAM explicitly concluded that submitted data did not fulfil validation criteria), applicability domain (overly broad claim as universal replacement for 3T3-NRU across phototoxicity, irritation, and corrosion without supporting evidence), and programme prioritisation / route selection (ECVAM discontinuation). Because the lifecycle is fully concluded within TSAR without external standardisation, the method is coded as case_study_method = 0 (External_evidence_step_stage = SUB_STOP).","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Applicability domain; Programme prioritisation / route selection","bottleneckCount":"3","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals; Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2011-01","shortName":"DAP assay","title":"Dequenching after photobleaching cytotoxicity test","organisation":"EURL ECVAM - European Union","description":"DAP assay is a quantitative live cell cytotoxicity assay based on measurements on DNA alterations, which are assessed by the ability of DNA fluorophobes to establish different toxicity-dependent quenching levels in cells. The technology used is based on fluorescence Dequenching After Photobleaching. Therefore, DAP is a mechanistic-based assay that addresses DNA alterations in association (or not) with cell death. The protocol used is straightforward (single-step, no washings) and has been set up in HTS cell culture formats (96/384 well microplates). Mammalian or fish cell models (suspension or adherent) have been used e.g. HepG2, Caco-2 and primary cells. The results are expressed as IC50 values calculated from the concentration response curves using the following sigmoidal dose-response regression model: Y=Bottom + (Top-Bottom)/[1+10^(LogIC50-X)]. The following prediction model was established: Log(human blood LC50) = 0.967 x Log(DAP IC50) - 0.824. The DAP technology is presented as potentially applicable to several toxicological areas such as acute toxicity, genotoxicity, chronic toxicity and carcinogenicity. The immediate application could be for human acute toxicity, although this has not been explicitly shown. For the other areas of application experimental data are lacking.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Acute toxicity, Chronic toxicity, Genotoxicity/Mutagenicity","yearReceived":"2011","generalComments":"Submission closed because replaced by another version of the test method in subsequent submission (TM2014-05)","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:52","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Environmental","endpoint":"Acute toxicity; Chronic toxicity; Genotoxicity","methodology":"In vitro","specificMethodologies":"HTS; Cytotoxicity/cell viability assay; Biomarker/DNA damage assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). The Dequenching after photobleaching cytotoxicity test (DAP assay) is an in vitro high-throughput cytotoxicity screening method (set up in 96- and 384-well microplates) evaluating live-cell DNA and membrane alterations using fluorescence dequenching of asymmetric cyanine DNA fluorophores (such as Thiazole Orange) following light activation. The assay derives IC50 values to estimate human acute systemic blood concentrations (serving an intended 3R role of Reduction). Core methodology is corrected from \"In vitro; In silico; In chemico; Mixed\" to \"In vitro\". Specific methodologies are refined from \"HTS; AI/ML; Cytotoxicity/cell viability assay; Phototoxicity/photoreactivity assay; Bioaccessibility/bioelution assay\" to \"HTS; Cytotoxicity/cell viability assay; Biomarker/DNA damage assay\" (3 labels), removing erroneous phototoxicity, bioaccessibility, and AI/ML tags (sigmoidal regression curve fitting does not constitute AI/ML). Application domain is corrected from Environmental to \"Industrial chemicals; Pharmaceutical / human medicines\". Lineage is confirmed within the Valitox/DAP/LUCS family: TM2011-01 is a formal resubmission (is_resubmission = 1, generation = 1, relationship = Revised/resubmitted test method) of TM2008-12 (Valitox), submitted on the official ECVAM form with clarifications, and was formally closed in May 2012 when the submitter replaced it with a subsequent version (TM2014-05, LUCS). Bottlenecks evaluated: standardisation signal is corrected to 0 as the review ended during pre-submission; signals are confirmed for validation readiness (lack of an experimental validation package for multiple claimed endpoints), applicability domain (overly broad scope across acute, chronic, geno-, and carcinogenicity), and programme prioritisation / route selection (closure due to replacement by TM2014-05). Because the lifecycle is fully concluded within TSAR without external standardisation, the method is coded as case_study_method = 0 (External_evidence_step_stage = SUB_STOP).","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Applicability domain; Programme prioritisation / route selection","bottleneckCount":"3","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals; Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2010-08","shortName":"GGA","title":"Transcriptomics based Genomics-Genotox assay","organisation":"EURL ECVAM - European Union","description":"The Genomics-genotox assay is a transcriptomics-based in vitro test performed in HepG2 cells to accurately predict the in vivo genotoxic properties of chemicals. Mechanistic relevance of the classifier genes is represented by the fact that many of those genes are regulated by relevant transcription factors, such as the DNA damage response-related SP1 gene for the Ames-positive classifiers, and the involvement in stress response pathways for the Ames-negative classifiers. Stratification of the compounds based on the Ames- test, further adds mechanistic relevance, as it grossly separates compounds that are DNA-reactive (either direct or after metabolic activation) from those that are not reactive.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Genotoxicity/Mutagenicity","yearReceived":"2010","generalComments":"Does not qualify for entering validation","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:55","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Genotoxicity","methodology":"In vitro","specificMethodologies":"Omics; AI/ML; Biomarker/DNA damage assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). The Transcriptomics based Genomics-Genotox assay (GGA) is an in vitro toxicogenomic method developed in human HepG2 hepatoma cells to predict in vivo chemical genotoxicity. Following exposure, whole-genome microarray gene expression profiling is combined with an initial Ames test stratification (separating DNA-reactive from non-reactive compounds); machine learning algorithms then evaluate differentially expressed classifier gene signatures (e.g. SP1 and p53 DNA damage response pathways) to discriminate in vivo genotoxins from non-genotoxins and resolve in vitro false-positive results (Three_R_category = Reduction). Core methodology is corrected from \"In vitro; In silico; Mixed\" to \"In vitro\" (the computational classification is captured under specific methodologies). Specific methodologies are confirmed as \"Omics; AI/ML; Biomarker/DNA damage assay\" (3 labels). Application domain is assigned as \"Pharmaceutical / human medicines; Industrial chemicals\". TSAR records assessment of the full submission in May 2011 and formal discontinuation in September 2013 (\"Not considered for validation\", External_evidence_step_stage = SUB_STOP). Bottlenecks evaluated: standardisation signal is corrected to 0 as the review ended during submission evaluation; signals are confirmed for validation readiness (lack of a standardized multi-laboratory validation package for the microarray/bioinformatic pipeline), regulatory relevance/integration (absence of a regulatory acceptance framework for transcriptomic classifiers under OECD or REACH genotoxicity testing schemes), and programme prioritisation / route selection (ECVAM formal decision not to proceed). Because the regulatory process was fully concluded within TSAR without external standardisation, the method is coded as case_study_method = 0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"3","animalUseImpact":"Reduction","applicationDomainExpert":"Pharmaceutical / human medicines; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2014-03","shortName":"MucilAir","title":"Transepithelial permeability assessment using an in vitro cell model of the human airway epithelium","organisation":"EURL ECVAM - European Union","description":"MucilAir is an in vitro 3D reconstructed human tissue that includes a bronchial and a nasal epithelial model, which phenotypically and functionally are representative of in vivo human bronchial and nasal epithelium (ciliated cells, basal cells, goblet cells, presence of cilia and cilia-beating, and functional muco-ciliary clearance). It is cultured at an air -liquid interface and it is designed to measure how fast a specific part of the human upper airways absorbs the test substance. This method provides Papp (apparent permeability) values for the upper airways. Therefore, it appears to be relevant from the perspective of assessing systemic or internal exposure to a test substance via the respiratory route. The test method has potential for deriving relevant absorption parameters for the respiratory tract important for human toxicokinetic evaluation of test substances. However, the exact method to be used for this purpose and the data analysis model is not clearly indicated.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Respiratory permeability/penetration, toxicokinetics, Toxicokinetics","yearReceived":"2014","generalComments":"Considered to be followed up in the wider context of ADME methods","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:38","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Pharmaceutical","endpoint":"Respiratory permeability/penetration; Toxicokinetics","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Barrier/permeability/transport assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). MucilAir is an in vitro 3D reconstructed human airway epithelial tissue model (comprising primary bronchial and nasal ciliated cells, goblet cells producing mucus, and basal cells cultured at an air-liquid interface [ALI]) designed to measure transepithelial respiratory permeability (Papp) and barrier integrity (TEER). The assay provides human-relevant respiratory absorption parameters to support physiological-based pharmacokinetic/toxicokinetic (PBPK) modeling and internal exposure assessment for inhaled pharmaceuticals and industrial chemicals, serving an intended 3R role of Reduction. Core methodology is confirmed as In vitro; Specific methodologies are confirmed as \"Organoid/3D tissue model; Barrier/permeability/transport assay\" (2 labels). Application domain is expanded from Pharmaceutical to \"Pharmaceutical / human medicines; Industrial chemicals\". TSAR records pre-submission in June 2014 and formal discontinuation in December 2014 (\"Not prioritised for validation. Considered to be followed up in the wider context of ADME methods\", External_evidence_step_stage = SUB_STOP). Outside TSAR, MucilAir is widely utilized for preclinical research and IATA case studies, but has not entered a formal OECD Test Guideline validation pathway for permeability. Bottlenecks evaluated: standardisation signal is corrected to 0 as the review ended at pre-submission; signals are confirmed for validation readiness (lack of a standardized data analysis and prediction model), regulatory relevance/integration (absence of a dedicated regulatory framework for standalone respiratory permeability endpoints), and programme prioritisation / route selection (ECVAM discontinuation). Because the lifecycle is fully captured within TSAR and no formal external regulatory adoption occurred, the method is coded as case_study_method = 0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"3","animalUseImpact":"Reduction","applicationDomainExpert":"Pharmaceutical / human medicines; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2011-04","shortName":"Bioaccess","title":"Bioaccessibility testing from powder and massive samples of metals and alloys","organisation":"EURL ECVAM - European Union","description":"The bioaccessability test method enables the quantification of metal species released into artificial solutions (artificial body fluids of relevance for exposure routes including inhalation and ingestion, and dermal contact) from metal or alloy particles or massive sheet at a specific loading and time periods. The released metal species are measured by determining total dissolved metal concentrations in particle-free solutions (leaching analysis). These concentrations can be related and compared with available toxic endpoints for the specific route of interest (inhalation, ingestion, dermal contact), exposure time, particle loading or surface area. Further in-depth studies, also considering surface properties of the particles, speciation of released metals, and mechanisms of release, as well as comparison to some in vivo tests could allow prediction of toxicity of other alloy particles and grouping of materials. The test method is proposed to be used for classification, ranking, and screening of different metal and alloy particles or massive sheet (relative comparison). Such data cannot be estimated based on bulk alloy compositions. It is claimed that the data generated with the test method can be used to estimate the impact of alloying on the behaviour of various alloying elements and indicate whether or not hazards associated with one or more of the constituents are likely to persist for the alloy. With regard to the regulatory framework REACH is mentioned.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Bioaccessibility","yearReceived":"2011","generalComments":"Not considered for follow-up.","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 10:00","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Industrial chemicals","endpoint":"Bioaccessibility","methodology":"In chemico","specificMethodologies":"Analytical chemistry readout; Read-across/WoE; Bioaccessibility/bioelution assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). The Bioaccessibility testing from powder and massive samples of metals and alloys (Bioaccess) method is an in chemico, cell-free leaching assay measuring the release of dissolved metal species from metal/alloy powders or massive sheets into artificial physiological body fluids (inhalation, ingestion, and dermal surrogates), followed by instrumental analytical chemistry quantification (e.g. ICP-MS/OES). The data are intended to evaluate whether hazards associated with individual metal constituents persist in the alloy matrix, supporting grouping and read-across for classification and risk assessment under REACH and CLP (Three_R_category = Reduction). Core methodology is confirmed as In chemico; Specific methodologies are refined to \"Analytical chemistry readout; Read-across/WoE; Bioaccessibility/bioelution assay\" (3 labels), activating the analytical chemistry flag. Application domain is specified as \"Industrial chemicals\". TSAR records a pre-submission in July 2011, revision in November 2011, and discontinuation at EURL ECVAM in August 2012 (\"Not considered for follow-up\", External_evidence_step_stage = SUB_STOP). Methodologically, TM2011-04 represents the early conceptual predecessor to TM2016-02 (Bioelution), which later refined the approach into a standardized simulated gastric fluid protocol and achieved ESAC endorsement before OECD Test Guideline standardisation was discontinued in 2024. Case study classification is assigned as case_study_method = 2 (Borderline case study): while TM2011-04 itself ended at pre-submission within TSAR and the primary outside-TSAR regulatory progression occurred under the successor dossier TM2016-02 (which holds case_study_method = 1), TM2011-04 is designated as a borderline case study because it documents the embryonic, unprioritised multi-fluid precursor phase and illustrates how reframing an overly broad testing scope into a focused protocol was necessary to enable subsequent formal validation. Bottlenecks evaluated: standardisation signal is corrected to 0 as the review ended at pre-submission; signals are confirmed for validation readiness (lack of a standardized multi-laboratory validation dossier across multi-fluid matrices), applicability domain (overly broad scope across multiple exposure routes and physical forms), regulatory relevance/integration (absence of an established regulatory testing framework for in chemico bioaccessibility testing), and programme prioritisation / route selection (ECVAM formal discontinuation).","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Validation readiness / evidence package; Applicability domain; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2012-01","shortName":"Tettox","title":"Combined assay for the detection of tetanus toxicity in tetanus toxoids","organisation":"EURL ECVAM - European Union","description":"This functional assay is designed to detect active tetanus neurotoxin (TeNT) in vaccines containing a tetanus toxoid component. Only active TeNT would inhibit neurotransmitter release from neuronal cells leading to symptoms of tetanus disease detected with the in vivo assay. TeNT molecules consist of two subunits: a heavy chain which is responsible for the binding to target cells, and a light chain (L-chain) with a proteolytic domain which specifically cleaves the neuronal protein synaptobrevin-2, and thus inhibits neurotransmitter release. These two functional properties of the active TeNT molecules are measured in a stepwise approach: First, the test sample is incubated on a microtiter plate coated with the TeNT receptor (i.e. ganglioside GT1b). Active TeNT binds to the receptor, while molecules lacking a functional receptor domain are removed by washing. The bound TeNT molecules are treated with a reducing agent to release and activate the L-chains. The supernatant containing the activated L-chains is then transferred to a second microtiter plate containing recombinant synaptobrevin-2 (rSyb2) which is specifically cleaved by the active L-chains. The resulting cleavage fragment is detected using a cleavage-site specific antibody. Signal amplification is obtained by employing a biotinylated secondary antibody followed by peroxidase-coupled streptavidin, and tetramethylbenzidine is used as colorimetric substrate for quantification of the peroxidase. The absorbance is measured at 450 nm against 620 nm as reference wavelength. Absorption values of the test sample are determined and the decision on toxicity is based on statistical comparison to (historical) control samples. The European Pharmacopoeia monographs for tetanus vaccines for human or veterinary use stipulate that vaccine manufacturer demonstrate the absence of active TeNT during quality control of their products. The tests described are based on guinea pigs. The in vitro assay has the potential to replace the test in guinea pigs.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Quality control of vaccines","yearReceived":"2012","generalComments":"This assay, now named BINding And CLEavage (BINACLE) assay is undergoing formal validation within the Biological Standardisation Programme of EDQM (BSP136: Tetanus Toxoid BINACLE assay).","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:43","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Food safety","endpoint":"Vaccine quality control","methodology":"In vitro","specificMethodologies":"Binding/interaction assay; Enzyme/biochemical activity assay; Immunoassay/flow cytometry","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-23 using Gemini 3.8 Flash (High). The Combined assay for the detection of tetanus toxicity in tetanus toxoids (Tettox, later designated the BINACLE [BINding And CLEavage] assay) is a cell-free in vitro functional dual-step biochemical assay designed to detect residual or reverted active tetanus neurotoxin (TeNT) in tetanus toxoid vaccines. Step 1 evaluates functional receptor binding of the TeNT heavy chain to microtiter plate-immobilized ganglioside GT1b; following washing, reduction with DTT releases the active light chain endopeptidase into the supernatant. Step 2 evaluates specific proteolytic cleavage of recombinant synaptobrevin-2 (rSyb2) by the light chain, quantified via a neo-epitope cleavage-specific antibody ELISA (OD450/620 nm). Core methodology is corrected from \"In vitro; In vivo; Mixed\" to \"In vitro\" (the mention of guinea pigs reflects solely the target in vivo test to be replaced, not the assay mechanism). Specific methodologies are refined from \"HTS; Immunoassay/flow cytometry; Analytical chemistry readout; Enzyme/biochemical activity assay\" to \"Binding/interaction assay; Enzyme/biochemical activity assay; Immunoassay/flow cytometry\" (3 labels), removing non-applicable HTS and analytical chemistry tags. Application domain is corrected from \"Food safety\" to \"Pharmaceutical / human medicines; Veterinary medicines / animal health\". TSAR tracking records pre-submission in March 2012, invitation to full submission in August 2012, and discontinuation at EURL ECVAM in June 2013 because the assay entered formal international multi-centre validation under the Biological Standardisation Programme of the EDQM (project BSP136). Outside-TSAR progression is verified: BSP136 conducted multi-laboratory collaborative studies (Phase 1 feasibility, Phase 2 across 19 laboratories) to validate the BINACLE assay for formal inclusion in European Pharmacopoeia monographs (e.g. Ph. Eur. 0452) to achieve complete replacement of the 21-day guinea pig toxicity test for batch release (External_evidence_step_stage = VAL_ONGO; Three_R_category = Replacement). Bottleneck signals are set for validation readiness (multi-lab collaborative evidence package required) and programme prioritisation / route selection (handover from ECVAM to EDQM); standardisation signal is corrected to 0. Coded as case_study_method = 1 representing a primary case study of outside-TSAR institutional routing and pharmacopoeial 3R standardisation.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_ONGO","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Pharmaceutical / human medicines; Veterinary medicines / animal health","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2013-01","shortName":"IVCP assay","title":"In vitro Caco-2 permeability","organisation":"EURL ECVAM - European Union","description":"The Caco-2 permeability assay measures the permeability of compounds through a human intestinal epithelial cell barrier. Therefore, the endpoint measured is intestinal permeability (expressed as apparent permeability - Papp value). The test method appears more relevant for drug permeability studies. The use of in vitro epithelial cell culture methods to estimate intestinal permeability is already foreseen in the FDA Guidance for Industry \"Waiver of In Vivo Bioavailability and Bioequivalence Studies for Immediate-Release Solid Oral Dosage Forms Based on a Biopharmaceutics Classification System (BCS)\". This guideline explains how to demonstrate the suitability of a permeability method intended for application of the BCS. The permeability coefficient across Caco-2 cell monolayer may be used to assign a drug substance to BCS class. It may also be used to estimate the oral absorption of new chemical entities. Compounds exhibiting apparent permeability < 1x10-6 [cm/s], 1-10x10-6 [cm/s] and > 10x10-6 [cm/s], can be classified as poorly (0-20%), moderately (20-70%) and well (70-100%) absorbed drugs, respectively. It is claimed that in some cases (presumably drugs) the method may replace the use of preliminary in vivo bioavailability or bioequivalence tests on animals.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Intestinal permeability/penetration, toxicokinetics, Toxicokinetics","yearReceived":"2013","generalComments":"Considered to be followed up in the wider context of ADME methods","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=142","lastUpdate":"Monday, October 12, 2020 - 08:41","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Pharmaceutical; Industrial chemicals","endpoint":"Intestinal permeability/penetration; Toxicokinetics","methodology":"In vitro","specificMethodologies":"Barrier/permeability/transport assay; Analytical chemistry readout","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"De novo expert verification completed on 2026-09-22 using Gemini 3.8 Flash (High). The In vitro Caco-2 permeability (IVCP) assay evaluates transcellular and paracellular epithelial intestinal transport in human Caco-2 colorectal adenocarcinoma monolayers on Transwell inserts. Permeability coefficients (Papp) are quantified via HPLC-MS/MS or LC-UV alongside TEER monolayer integrity verification. Core methodology confirmed as In vitro; Specific methodologies updated to \"Barrier/permeability/transport assay; Analytical chemistry readout\" (2 labels). Application domain specified as \"Pharmaceutical / human medicines; Industrial chemicals\". TSAR tracking records pre-submission in June 2013 and discontinuation in October 2013 (\"Following the evaluation of the pre-submission, the test method has not been prioritised for validation. Considered for follow up in a wider context of ADME methods\"). Bottlenecks evaluated: AI-assigned validation readiness and standardisation signals corrected to 0 as the assay was technically mature and standardized; signals set for programme prioritisation (EURL ECVAM formal decision not to prioritise) and regulatory relevance/integration (absence of a dedicated ECVAM validation framework for standalone ADME screening vs apical hazard endpoints). 3R category assigned as \"Replacement\" (in line with TSAR \"Regulatory waiver/removal\" classification, where Caco-2 BCS Class I permeability enables in vivo bioequivalence study biowaivers under ICH M9). Case study status set to 2 (Borderline case study) reflecting its non-canonical regulatory acceptance route via international pharmacopoeial/ICH M9 biowaivers rather than classical OECD TG adoption. External evidence stage confirmed as SUB_STOP.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Regulatory waiver/removal","applicationDomainExpert":"Pharmaceutical / human medicines; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2007-03","shortName":"3T3 NRU","title":"3T3 Neutral Red Uptake cytotoxicity assay","organisation":"EURL ECVAM - European Union","description":"The 3T3 NRU cytotoxicity assay employs the BALB/c3T3 mouse fibroblast cell line and is based on the ability of viable cells to incorporate and bind the dye Neutral Red (NR), measured spectrophotometrically . The basic concept of basal cytotoxicity assays is that chemicals exert their toxic effects by disrupting structures and functions universal to all cells. The assay used the test method protocol and the IC50-LD50 regressions of the NRU cytotoxicity method, validated in the NICEATM/ECVAM validation study (see TM2003-01) and was proposed to identify chemicals that would not require classification for acute oral toxicity according to the EU CLP Regulation (i.e. LD50 > 2 000 mg/kg). It was envisaged that use of the 3T3 NRU test method to identify unclassified substances in a testing strategy, to support a read-across, or as part of a weight-of-evidence approach could potentially reduce the amount of animal testing for acute oral toxicity.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Acute toxicity, Basal Cytotoxicity","yearReceived":"2007","generalComments":"The validation study assessed the capacity of the 3T3 NRU cytotoxicity assay to identify specifically non-classified chemicals on the basis of the 2000 mg/kg b.w. threshold introduced by the EU CLP Regulation.","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=139","lastUpdate":"Monday, October 12, 2020 - 09:07","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Industrial chemicals","endpoint":"Acute toxicity; Basal cytotoxicity","methodology":"In vitro","specificMethodologies":"HTS; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"The 3T3 NRU cytotoxicity assay is an in vitro mouse fibroblast-based basal cytotoxicity method measuring spectrophotometric Neutral Red dye uptake (OD540) to determine IC50 values. Core methodology is corrected from Mixed to In vitro; specific methodologies are normalised to HTS and Cytotoxicity/cell viability assay (erroneous Read-across/WoE, ITS, Barrier, Phototoxicity, and Analytical chemistry labels were removed). As a direct method extension of TM2003-01, TM2007-03 was validated by EURL ECVAM (2008–2011) to specifically evaluate its capacity to identify non-classified substances (oral LD50 > 2000 mg/kg) under the EU CLP Regulation. Following positive ESAC peer review (2012) and an EURL ECVAM Recommendation (2013), the method was formally integrated into the ECHA Guidance on Information Requirements and Chemical Safety Assessment (Chapter R.7a) in October 2015 (External_evidence_step_stage = REG_ADOPT). The assay serves an intended 3R role of Reduction within Weight of Evidence (WoE) or Integrated Testing Strategies (ITS) under REACH Annex XI to reduce or waive in vivo acute oral testing. Predictive performance and applicability domain bottlenecks are supported due to low specificity (40–44%), inability to resolve GHS hazard categories for positive substances, lack of metabolic competence (P450 bioactivation), and exclusion of organ-specific toxicities. Because regulatory adoption is fully captured within TSAR event history (E008), the method is coded as case_study_method = 0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Predictive performance; Applicability domain","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2003-01","shortName":"NRU cytotoxicity","title":"Neutral red uptake for starting doses for acute oral toxicity","organisation":"ICCVAM/NICEATM - United States","description":"The in vitro Neutral Red Uptake (NRU) test method is a cell-based approach that assesses the cellular uptake of a dye in the presence of a particular substance. The protocols use normal human epidermal keratinocytes (NHK) and BALB/c 3T3 mouse fibroblasts (3T3). NHK cells are primary cells while 3T3 cells are an inmortal line. The method is used to assess basal cytotoxicity quantified through IC50 values (the concentration of test substance needed to decrease cell viability by 50% in the cell culture) by spectrophotometric measurments of the cellular uptake of NR dye. Assays that assess this type of toxicity look at how chemicals exert effects by disrupting structures and functions that are universal to all cells (e.g. cell membrane integrity, energy production and metabolism, transportation of molecules, secretion of molecules).This is opposed to assays that assess the effects of chemicals on specific molecular targets (such as receptors, ion channels etc.), lacking in the cells used in this method. Due to the fact that substances that produce injury and death are ultimately exerted at the cellular level, in vitro cytotoxiciicty assays may be also useful for the prediction of acute lethaly potency. The NRU IC50 concentration of a test substance in either 3T3 or NHK cells could be used to estimate the rodent LD50 value as a mean for predicting the starting doses for rodent acute oral toxicity studies.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Acute toxicity, Basal Cytotoxicity","yearReceived":"2003","generalComments":"The NICEATM/ECVAM Validation finalised/OECD Guidance Document","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=139","lastUpdate":"Monday, February 15, 2021 - 12:20","lastUpdateDate":"2021-02-15","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Acute toxicity; Basal cytotoxicity","methodology":"In vitro","specificMethodologies":"HTS; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"The in vitro Neutral Red Uptake (NRU) basal cytotoxicity assay (using BALB/c 3T3 fibroblasts and normal human epidermal keratinocytes, NHK) measures spectrophotometric dye uptake (OD540) to quantify IC50 values in 96-well microplates. Core methodology is confirmed as In vitro; specific methodologies are normalised to HTS and Cytotoxicity/cell viability assay (erroneous Organoid, Barrier, Phototoxicity, and Analytical chemistry labels were removed). The assay serves an intended 3R role of Reduction (and refinement) by using the IC50 in a linear regression model to estimate rodent LD50 starting doses for acute oral systemic toxicity tests (OECD TG 420, 423, 425), reducing animal use by 25–40%. Following a joint NICEATM/ECVAM validation study (2003–2005) and ICCVAM evaluation (2006), the method was officially published as OECD Guidance Document 129 in July 2010 (External_evidence_step_stage = REG_PUBL). Predictive performance and applicability domain bottlenecks are supported because basal cytotoxicity cannot model systemic toxicokinetics or organ-specific toxicities (e.g., neurotoxicity, metabolic bioactivation), preventing standalone replacement of animal tests. Because publication as OECD GD 129 is fully captured within TSAR event history (E008), the method is coded as case_study_method = 0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_PUBL","bottlenecks":"Predictive performance; Applicability domain","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Mixed/general toxicology; Industrial chemicals; Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2010-03","shortName":"KeratinoSens","title":"KeratinoSens assay for the testing of skin sensitizers","organisation":"EURL ECVAM - European Union","description":"The KeratinoSens™ test method supports the discrimination between sensitizing and non-sensitizing chemicals. It addresses one of the biological mechanisms described under key event 2 (events in keratinocytes) of the skin sensitization Adverse Outcome Pathway by measuring the activation of the Keap1-Nrf2-ARE pathway. The Keap1-Nrf2-ARE regulatory pathway is reported to be a major regulator of cyto-protective responses to electrophile and oxidative stress by controlling the expression of detoxification, antioxidant and stress response enzymes and proteins. Small electrophilic substances such as skin sensitisers can act on the sensor protein Keap1 (Kelch-like ECH-associated protein 1), by e.g., covalent modification of its cysteine residue, resulting in its dissociation from the transcription factor Nrf2 (nucler factor-erythroid 12-related factor 2). The dissociated Nrf2 can then activate ARE-dependent genes such as those coding for phase II detoxifying enzymes. The KeratinoSens™ is performed using an immortalized adherent cell line derived from HaCaT human keratinocytes stably transfected with a selectable plasmid containing the luciferase gene under the transcriptional control of a constitutive promoter fused with an ARE element. The quantitative measurement by luminescence detection of the luciferase gene induction is used as an indicator of the activity of the Nrf2 transcription factor in cells following exposure to electrophilic test chemicals.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin sensitisation","yearReceived":"2010","generalComments":"The validation was performed externally between 2009 and 2010","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=155","lastUpdate":"Monday, October 12, 2020 - 08:55","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"HTS; Reporter gene assay; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"The KeratinoSens assay is an in vitro human keratinocyte (HaCaT-derived) reporter gene method that measures luciferase induction driven by the Antioxidant Response Element (ARE) upon electrophilic modification of Keap1 sensor cysteine residues and subsequent Nrf2 nuclear translocation, coupled with parallel MTT viability testing in 96-well microplates to assess Key Event 2 of the skin sensitisation Adverse Outcome Pathway. Core methodology is corrected from Mixed to In vitro; specific methodologies are normalised to HTS, Reporter gene assay, and Cytotoxicity/cell viability assay (the in chemico Chemical reactivity assay label was removed). The assay serves an intended 3R role of Reduction as a partial-endpoint/key-event tool that must be combined with other assays in Defined Approaches (OECD TG 497). Following external validation (2009–2010), positive ESAC peer review (2012), and an EURL ECVAM Recommendation (2014), the method was formally adopted as OECD Test Guideline 442D in February 2015, establishing External_evidence_step_stage = REG_ADOPT. An active applicability domain bottleneck is supported due to restrictions regarding lysine-only reactive haptens, pro-haptens requiring P450 bioactivation, slow-oxidising pre-haptens, and insoluble/fluorescent substances (managed via Defined Approaches). Because regulatory adoption is fully captured within the TSAR event history (E013), the method does not represent progression outside TSAR and is coded as case_study_method = 0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain","bottleneckCount":"1","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2014-02","shortName":"H2AX ICW","title":"H2AX ICW method, gH2AX In cell western","organisation":"EURL ECVAM - European Union","description":"The method is an in vitro genotoxic 96-well plate format assay for the measurement of histone gH2AX phosphorylation, normally occurring after DSBs induction in different cell types. The use of the gH2AX global genotoxic biomarker coupled with the in cell western technique permit to determined simultaneously the cytotoxicity and the genotoxicity of any tested compound. The in cell western technique is an immunohistochemistry in situ (directly into the well) used in combination with infra-red fluorescence. The assay is proposed in early discovery phase of drug development for genotoxicity screening or as a substitute of the in vitro micronucleus test.","stepStage":"Submission > Not considered for validation","workflowStep":"Submission","workflowStage":"Not considered for validation","topic":"Genotoxicity/Mutagenicity","yearReceived":"2014","generalComments":"Presubmission assessment finalised. Method Not prioritised for validation","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:39","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_NOTVAL","applicationDomain":"Pharmaceutical","endpoint":"Genotoxicity","methodology":"In vitro","specificMethodologies":"HTS; Cytotoxicity/cell viability assay; Immunoassay/flow cytometry; Biomarker/DNA damage assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"The H2AX ICW assay is an in vitro 96-well microplate screening method using In-Cell Western (near-infrared in situ immunofluorescence) to detect histone H2AX phosphorylation (γH2AX, Ser139) induced by DNA double-strand breaks, with simultaneous cell staining for cytotoxicity normalisation. Specific methodologies are normalised to HTS, Cytotoxicity/cell viability assay, Immunoassay/flow cytometry, and Biomarker/DNA damage assay (the erroneous Micronucleus label was removed). The assay serves an intended 3R role of Reduction for early pharmaceutical genotoxicity screening. Although the source snapshot records Submission > Receipt of presubmission (NEW_STEP_STAGE = SUB_RECEIPT), the complete TSAR event history shows that EURL ECVAM finalised the presubmission assessment in November 2014, designating the method as 'Not considered for validation' because it lacked mechanistic information and offered no clear regulatory added value compared to standard batteries (establishing External_evidence_step_stage = SUB_NOTVAL). Mechanistic relevance, regulatory relevance/integration, and programme prioritisation bottlenecks are supported. The single-biomarker ICW platform did not progress outside TSAR as a standalone method (case_study_method = 0); instead, the developers resolved the mechanistic deficiency by adding pH3 and resubmitting the evolved dual-biomarker platform as TM2017-01.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_NOTVAL","bottlenecks":"Mechanistic relevance; Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"3","animalUseImpact":"Reduction","applicationDomainExpert":"Pharmaceutical / human medicines","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2017-01","shortName":"gH2AX/pH3","title":"gH2AX/pH3 biomarkers for the prediction of DNA damage","organisation":"EURL ECVAM - European Union","description":"The proposed method is based on gH2AX/pH3 biomarkers for the prediction of genotoxic potential of all kind of substances. The combination of the two biomarkers is proposed to detect early events in the DNA damage response and to discriminate structural and numerical chromosome damage. This assay is applicable to almost all cell types including cells of human origin. The assay use innovative techniques with a higher throughput than usual assays and potentially amenable to automation. The method is less prone to irrelevant positive results as compared to some of the current assays because is able to also discriminate the misleading cytotoxic chemicals.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Genotoxicity/Mutagenicity","yearReceived":"2017","generalComments":"Presubmission assessment finalised. Method Not prioritised for validation","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:26","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Genotoxicity","methodology":"In vitro","specificMethodologies":"HTS; Biomarker/DNA damage assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"The gH2AX/pH3 assay is an in vitro mammalian cell-based multiplexed genotoxicity screening method that simultaneously quantifies phosphorylated histone H2AX (γH2AX, Ser139) to detect DNA double-strand breaks (clastogenicity) and phosphorylated histone H3 (pH3, Ser10) to assess mitotic index/arrest (aneugenicity), while discriminating true genotoxins from confounding cytotoxicity. Core methodology is corrected from Other to In vitro; specific methodologies are normalised to HTS and Biomarker/DNA damage assay. The assay serves an intended 3R role of Reduction as an early screening, mechanistic MoA discrimination, and weight-of-evidence tool. The initial TSAR presubmission was stopped in February 2018 because EURL ECVAM did not prioritise the method for validation (NEW_STEP_STAGE = SUB_STOP), reflecting validation readiness and programme prioritisation bottlenecks. However, progression continued outside TSAR through entry into the OECD Test Guidelines Programme (Project 4.168), where a Detailed Review Paper (DRP) on γH2AX/pH3 assays is undergoing WNT review in 2026. This concrete acceptance-related standardisation progression outside TSAR supports External_evidence_step_stage = REG_DRAFT and qualifies the method as a direct case study (case_study_method = 1).","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_DRAFT","bottlenecks":"Validation readiness / evidence package; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Pharmaceutical / human medicines; Industrial chemicals; Cosmetics","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2009-08","shortName":"Greenscreen","title":"GreenScreen HC TM Genotoxicity Assay","organisation":"EURL ECVAM - European Union","description":"The Green Screen HCTM (GSHC) assay is an in vitro human cell-based genotoxicity test method intended to predict the in vivo genotoxic potential of chemicals. Specifically, the GSHC is a microplate format genotoxicity plus cytotoxicity screening assay which uses the DNA damage-inducible \"Growth Arrest and DNA Damage 45 alpha\" (GADD45a) - Green Fluorescent Protein (GFP) reporter gene, expressed in the p53-competent human lymphoblastoid TK6 cell line. The Submitter has proposed the test method for both regulatory and non-regulatory genotoxicity assessment: (A) for compound discovery and development screening applications; (B) as additional test to be used in Option2 under ICH S2(R1); (C) as stand-alone test alternative to the in vitro battery; (D) to support weight of evidence arguments in regulatory safety assessment of in vitro genotoxicity battery data - where genotoxicity data from other tests are conflicting.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Genotoxicity/Mutagenicity","yearReceived":"2009","generalComments":"The test method underwent an external (non EURL ECVAM-coordinated) validation study and all available information/data were submitted for a Retrospective Validation. Following consultation with EURL ECVAM network of regulators (PARERE - Preliminary Assessment of Regulatory Relevance), the test method did not progress to peer review.","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=132","lastUpdate":"Monday, October 12, 2020 - 10:06","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Genotoxicity","methodology":"In vitro","specificMethodologies":"HTS; Reporter gene assay; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"GreenScreen HC is an in vitro human cell-based genotoxicity screening assay using p53-competent TK6 cells expressing a GADD45a-GFP reporter gene construct to detect genotoxic potential (fluorescence at 485/535 nm) with simultaneous cell viability/density measurement (absorbance at 620 nm). Specific methodologies are normalised to HTS, Reporter gene assay, and Cytotoxicity/cell viability assay (Core_methodology: In vitro). The method serves an intended 3R role of Reduction as a screening/battery tool. Although submitted for retrospective validation, consultation with the EURL ECVAM regulatory network (PARERE) concluded that the assay lacked sufficient regulatory relevance to justify progression to peer review or integration into standard regulatory genotoxicity batteries (ICH S2(R1) / OECD), leading EURL ECVAM to stop the process in September 2014 (External_evidence_step_stage = SUB_STOP). Regulatory relevance/integration and programme prioritisation bottlenecks are supported. No qualifying progression occurred outside TSAR (case_study_method = 0).","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Regulatory relevance / integration; Programme prioritisation / route selection","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Pharmaceutical / human medicines; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2008-09","shortName":"SkinEthic HCE","title":"Human Reconstructed Corneal Epithelium (HCE) Eye Irritation test","organisation":"EURL ECVAM - European Union","description":"The purpose of this assay was to evaluate the ocular irritation potential of chemicals for European Union labelling and classification, in order to discriminate non irritants from irritants, and to be used as an alternative to the traditional in vivo rabbit eye test method (OECD TG 405). The test uses the SkinEthic™ HCE model, a reconstructed human cornea-like epithelium (RhCE) consisting of a multilayered epithelium prepared from immortalized human corneal epithelial cell. It constitutes a three dimensional structure which reproduces the multi-layer organization of the human cornea. The test consists of a topical exposure of the neat test chemicals onto the Human Corneal Epithelium model HCE, followed by cell viability measurement.","stepStage":"Peer-review > Finalised","workflowStep":"Peer-review","workflowStage":"Finalised","topic":"Serious eye damage/Eye irritation","yearReceived":"2008","generalComments":"This test method was unable to comply fully with the acceptance criteria set by the validation management group. A revised SkinEthic™ HCE EIT test method was re-submitted for assessment by EURL ECVAM and formal ESAC peer review in October 2015 (See TM2015-03, SkinEthic-HCE-EIT).","protocolSop":"","lastUpdate":"Wednesday, October 21, 2020 - 16:27","lastUpdateDate":"2020-10-21","stage":"Validation","status":"Finalised","code":"VAL_PEER_FINAL","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"The original SkinEthic HCE Eye Irritation Test uses a 3D reconstructed human cornea-like epithelium (RhCE) model and an MTT viability endpoint (threshold ≤ 50%) to discriminate eye irritants (UN GHS Cat 1/2) from non-irritants (No Category), serving an intended 3R role of Replacement of the in vivo rabbit eye test (OECD TG 405). Specific methodologies are Organoid/3D tissue model and Cytotoxicity/cell viability assay. In the ECVAM-coordinated Eye Irritation Validation Study (EIVS), the original generic protocol failed to meet the validation management group acceptance criteria. In November 2014, the ESAC finalised its peer review, recommending protocol optimisation to develop distinct protocols for liquids and solids, establishing External_evidence_step_stage = VAL_PEER_FINAL. A validation readiness bottleneck is supported, which was resolved historically when the developer resubmitted the optimised method as TM2015-03 (SkinEthic HCE EIT), culminating in OECD TG 492 adoption. TM2008-09 is coded as case_study_method = 0, as the external progression to OECD adoption is captured under successor TM2015-03 (case_study_method = 1).","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_PEER_FINAL","bottlenecks":"Validation readiness / evidence package","bottleneckCount":"1","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2011-10","shortName":"LuSens","title":"LuSens Assay","organisation":"EURL ECVAM - European Union","description":"The LuSens assay supports the discrimination between sensitizing and non-sensitizing chemicals. It is based on the same concepts as the OECD adopted KeratinoSens™. The LuSens assay addresses one of the biological mechanisms described under key event 2 (events in keratinocytes) of the skin sensitization Adverse Outcome Pathway by measuring the activation of the Keap1-Nrf2-ARE pathway. The Keap1-Nrf2-ARE regulatory pathway is reported to be a major regulator of cyto-protective responses to electrophile and oxidative stress by controlling the expression of detoxification, antioxidant and stress response enzymes and proteins. Small electrophilic substances such as skin sensitisers can act on the sensor protein Keap1 (Kelch-like ECH-associated protein 1), by e.g., covalent modification of its cysteine residue, resulting in its dissociation from the transcription factor Nrf2 (nucler factor-erythroid 12-related factor 2). The dissociated Nrf2 can then activate ARE-dependent genes such as those coding for phase II detoxifying enzymes. The LuSens assay is performed using genetically modified keratinocytes derived from HaCaT cells. It employs the reporter gene for luciferase under the control of an antioxidant response element (ARE) and hence monitors Nrf-2 transcription factor activity. The endpoint measurement is the up-regulation of the luciferase activity after 48 h incubation with test substance. This up-regulation is an indicator for the activation of the Keap1/Nrf2/ARE signaling pathway by ‘electrophilic stress' caused by cystein reactive substances.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin sensitisation","yearReceived":"2011","generalComments":"The Lu-Sens underwent an external catch-up validation study based on the performance standards for in vitro skin sensitisation ARE-NrF2 luciferase test methods (OECD 2015).","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=184","lastUpdate":"Monday, October 12, 2020 - 10:05","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"The LuSens assay is an in vitro reporter gene assay using genetically modified human HaCaT keratinocytes containing a luciferase gene under the transcriptional control of an antioxidant response element (ARE), measuring the activation of the Keap1-Nrf2-ARE pathway (Key Event 2 of the skin sensitisation AOP). Core methodology is corrected from mixed to In vitro, and specific methodologies are normalised to Reporter gene assay (removing the chemical reactivity label). The intended 3R role is Reduction as part of an integrated testing strategy or defined approach (OECD GL 497), not standalone replacement. Both the source snapshot and complete TSAR event history (event E016, June 2018) record adoption into updated OECD TG 442D, establishing External_evidence_step_stage = REG_ADOPT. An active applicability domain bottleneck is supported due to preferential sensitivity to cysteine-reactive electrophiles (potential false negatives for exclusive lysine reactives), limited metabolic competence for pro-haptens, and potential luciferase inhibition/quenching. Because regulatory adoption is fully captured within the TSAR record, case_study_method is coded 0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain","bottleneckCount":"1","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2014-06","shortName":"Sterlab RHE SIT","title":"Skin Irritation Test for the Prediction of Acute Skin Irritation of Chemicals With Sterlab RHE: 42 minutes application + 42 hours post-incubation","organisation":"EURL ECVAM - European Union","description":"The present test method is designed to predict and classify the skin irritant potential of chemicals according to chemical safety regulation, using STERLAB human reconstructed epidermis (RHE) model. The protocol is established for liquids, viscous and solid test substances. The relative viability of the treated tissues is measured at the end of the treatment exposure (42 minutes) followed by a post-exposure period (42 hours) using a cell viability test.","stepStage":"Submission > Assessment finalised","workflowStep":"Submission","workflowStage":"Assessment finalised","topic":"Skin irritation","yearReceived":"2014","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 13:22","lastUpdateDate":"2026-04-02","stage":"Test Submission","status":"Finalised","code":"SUB_FINAL","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Skin irritation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"The Sterlab RHE Skin Irritation Test (SIT) uses a 3D reconstructed human epidermis model (Sterlab RHE / Skin+™) with a 42-minute exposure followed by 42 hours post-incubation, measuring tissue viability via the MTT assay (threshold ≤ 50%) to classify acute skin irritants (UN GHS Cat 2 vs. No Category). Specific methodologies are Organoid/3D tissue model and Cytotoxicity/cell viability assay. The intended 3R role is Replacement of the in vivo rabbit skin irritation test (OECD TG 404). In TSAR, the dossier completed submission assessment in May 2016 following requests for additional information, but did not advance to formal EURL ECVAM validation or international adoption under OECD TG 439, establishing External_evidence_step_stage = SUB_ASSESS. A validation readiness / evidence package bottleneck is supported as the dossier stalled at submission assessment without proceeding to independent validation. Classified as case_study_method = 0 due to the absence of subsequent external lifecycle progression or non-classical transition pathway.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_FINAL","bottlenecks":"Validation readiness / evidence package","bottleneckCount":"1","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2009-06","shortName":"DPRA","title":"Direct Peptide Reactivity Assay","organisation":"EURL ECVAM - European Union","description":"The DPRA supports the discrimination between sensitising and non-sensitising chemicals. It measures in chemico the binding of test chemicals to model synthetic peptides containing either lysine or cysteine. Within the skin sensitization Adverse Outcome Pathway the covalent binding of electrophilic chemicals with nucleophilic sites of amino acids in skin proteins is postulated to be the molecular initiating event (MIE) (i.e. key event 1 – protein binding reactions) leading to skin sensitisation. In skin proteins many amino acids contain electron-rich groups capable of reacting with sensitisers. Lysine and cysteine are those most often quoted but others such as arginine, histidine, methionine and tyrosine can react with electrophilic chemicals.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin sensitisation","yearReceived":"2009","generalComments":"Validation finalised, ECVAM Recommendation published, OECD TG available","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=154","lastUpdate":"Monday, October 12, 2020 - 09:59","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In chemico","specificMethodologies":"Analytical chemistry readout; Binding/interaction assay; Chemical reactivity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"The Direct Peptide Reactivity Assay (DPRA) is an in chemico method that quantifies the depletion of synthetic heptapeptides containing cysteine or lysine via RP-HPLC/UV (220 nm) following a 24-hour incubation, modelling the Molecular Initiating Event (covalent protein binding) of the skin sensitisation AOP. Specific methodologies were corrected to include Analytical chemistry readout alongside Binding/interaction assay and Chemical reactivity assay. Intended 3R role is Reduction as part of an integrated testing strategy or defined approach (OECD GL 497), not standalone replacement. While the snapshot reflects Validation > Ongoing (VAL_ONGO), the complete TSAR event history (event E012, Feb 2015) and external evidence document adoption as OECD TG 442C, establishing External_evidence_step_stage = REG_ADOPT. An active applicability domain bottleneck is supported due to the lack of metabolic competence (pro-haptens require activation), poor solubility of highly hydrophobic substances (log Kow > 3.5), and chromatographic co-elution interference. Because regulatory adoption is fully captured within the complete TSAR event history and subsequent milestones represent guideline updates/integration, case_study_method is coded 0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain","bottleneckCount":"1","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM1998-04","shortName":"In vitro mAbs","title":"In vitro production of monoclonal antibodies (hybridoma technique)","organisation":"EURL ECVAM - European Union","description":"Based on the conclusions and recommendations of ECVAM workshop report 23 (Marx et al, 1997, ATLA, 25 121-137) and a report on monoclonal antibody production (Hendriksen, 1998, ATLA 26, 523-540), the ESAC concluded that for all levels of monoclonal antibody production, scientifically acceptable in vitro methods (e.g. hybridoma techniques) are practicably available. These methods have been shown to be either better than, or equal to, the in vivo (ascites) production method in terms of antibody quality. Therefore, the in vivo production of monoclonal antibodies by the ascites method is no longer scientifically necessary, except in rare cases.","stepStage":"Peer-review > Finalised","workflowStep":"Peer-review","workflowStage":"Finalised","topic":"Human health","yearReceived":"1998","generalComments":"","protocolSop":"","lastUpdate":"Wednesday, October 21, 2020 - 16:10","lastUpdateDate":"2020-10-21","stage":"Validation","status":"Finalised","code":"VAL_PEER_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Human health — unspecified","methodology":"In vitro","specificMethodologies":"","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":"In vitro production of monoclonal antibodies via hybridoma technology replaces the severe in vivo mouse ascites method. In March 1998, the ESAC unanimously endorsed that scientifically acceptable in vitro methods are practicably available for all production levels with equal or superior antibody quality, making in vivo ascites production unnecessary except in rare justified cases. Specific methodologies were corrected by removing the automated immunoassay label, as hybridoma culture is a cell-culture production system rather than an analytical assay. The spurious applicability domain bottleneck derived from a 'Not applicable' submission status was removed; no active bottleneck is supported. Following peer review, in vitro production became standard practice and regulatory requirement (e.g., European Pharmacopoeia Monograph 2031, Directive 2010/63/EU Article 13), supporting External_evidence_step_stage = REG_ADOPT. Borderline case study (case_study_method = 2): TM1998-04 represents a non-classical regulatory-transition pathway that resulted in the formal replacement, restriction, and phase-out of an animal-based procedure (mouse ascites method) via European Pharmacopoeia and EU animal protection legislation rather than a classical OECD hazard-testing guideline.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Replacement","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2012-04","shortName":"gEST","title":"Genomic Embryonic Stem cell Test method","organisation":"EURL ECVAM - European Union","description":"The method addresses to test human embryotoxicity and consequently predicts developmental effects on the basis of alterations of gene expression of cell differentiation. The method has showed a large potential discriminating weak embryotoxicants form non-embryotoxicants without loss of capability to detect strong embryotoxicants. The test method compares the relationships among alterations of gene expression in D3 cells and changes on viability on the same D3 mouse embryonic stem cells and 3T3 mouse using as parameters alterations on cell viability determined by the MTT test and alterations on gene expression determined by quantitative RT-PCR.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Reproductive toxicity, Embryotoxicity","yearReceived":"2012","generalComments":"Not considered for follow-up","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:44","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Embryotoxicity","methodology":"In vitro","specificMethodologies":"Omics; Cytotoxicity/cell viability assay; Embryo/developmental model","review":"Expert-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":"The Genomic Embryonic Stem cell Test (gEST) measures alterations in gene expression (via quantitative RT-PCR) and cell viability (via MTT) in D3 mouse embryonic stem cells and 3T3 mouse fibroblasts to predict human embryotoxicity. The method was submitted to EURL ECVAM but the submission was closed and not considered for follow-up. No further external progression or regulatory adoption was identified.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"SUB_STOP","bottlenecks":"Programme prioritisation / route selection","bottleneckCount":"1","animalUseImpact":"Unknown","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2005-02","shortName":"SHE 6.7 CTA","title":"Syrian hamster embryo cell transformation assay at pH 6.7","organisation":"EURL ECVAM - European Union","description":"The in vitro CTA using Syrian hamster embryonic (SHE) cells at pH 6.7 is aimed at detecting the carcinogenic potential of chemicals. The assay is based on the change of the phenotypic features of cells undergoing the first steps of the conversion from normal cells to neoplastic-like cell foci with oncogenic properties. Carcinogenesis is a complex multistage process by which normal cells are transformed into cancer cells characterised by an accumulation of changes at the cellular, genetic and epigenetic level. In vitro CTAs such as the SHE CTA have been shown to recapitulate a multistage process that closely models some stages of in vivo carcinogenesis. A minimum of four phenotypic stages appears to be involved in cell transformation. These include (from primary to fully malignant cells): a block in cellular differentiation, acquisition of immortality, characterised by unlimited lifespan, an aneuploidy karyotype and a decreased genetic stability; acquisition of tumorigenicity, which is closely associated with the in vitro phenotypes of foci formation, anchorage independent growth in semi-solid agar and autocrine growth factor production; full malignancy, including metastasis when the cells are injected into a suitable host, supporting the biological relevance of in vitro transformation to in vivo carcinogenicity. The assay is based on the change of the phenotypic features of cell colonies undergoing the first steps of the conversion from normal cells to neoplastic-like cells with oncogenic properties","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Carcinogenicity","yearReceived":"2005","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=136","lastUpdate":"Monday, October 12, 2020 - 09:10","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Carcinogenicity","methodology":"In vitro","specificMethodologies":"Cell transformation assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"SHE 6.7 CTA: in vitro cell transformation assay using primary Syrian hamster embryonic cells at pH 6.7. Exposure of primary SHE cells to test chemicals results in morphologically transformed colonies (increased MTF); phenotypic change serves as a proxy for early multi-stage carcinogenesis. Both genotoxic and non-genotoxic carcinogens can be detected. ECVAM prevalidation (2010) demonstrated protocol standardisation, inter-laboratory reproducibility (6/6 concordant chemicals, 3 labs) and transferability; ESAC endorsed (Feb 2011); EURL ECVAM Recommendation published Mar 2012. OECD GD 214 (May 2015) adopted as Guidance Document after failure to achieve TG consensus at April 2013 WNT meeting, primarily due to subjective visual scoring and limited mechanistic/non-genotoxic carcinogen data. Methodology corrected: 'Embryo/developmental model' removed; only 'Cell transformation assay' retained (SHE cells are a primary test system, not a developmental biology model per se). Bottleneck vector revised to [0,0,0,1,0,0,0,0,0,1]: applicability domain (non-genotoxic AD boundary, operationally managed via GD 214 WoE framework) and standardisation/regulatory adoption (OECD TG not achieved as of Sep 2026). 3R revised to Reduction: SHE cells derived from specifically bred pregnant hamsters; method reduces rodent bioassay use as WoE component but does not replace it and uses primary cells from live animals. Case study: 0 (highest lifecycle stage fully captured in TSAR event history, GD 214 = E008). External evidence step stage: REG_ADOPT (TSAR E008, May 2015; no post-TSAR OECD TG published). Application domain: Mixed/general toxicology (carcinogenicity screening broadly applicable across chemical sectors).","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain; Standardisation / regulatory adoption","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2005-03","shortName":"SHE 7.0 CTA","title":"Syrian hamster embryo cell transformation assay at pH 7.0","organisation":"EURL ECVAM - European Union","description":"The in vitro CTA using Syrian hamster embryonic (SHE) cells at pH 7.0 is aimed at detecting the carcinogenic potential of chemicals. The assay is based on the change of the phenotypic features of cells undergoing the first steps of the conversion from normal cells to neoplastic-like cell foci with oncogenic properties. Carcinogenesis is a complex multistage process by which normal cells are transformed into cancer cells characterised by an accumulation of changes at the cellular, genetic and epigenetic level. In vitro CTAs such as the SHE CTA have been shown to recapitulate a multistage process that closely models some stages of in vivo carcinogenesis. A minimum of four phenotypic stages appears to be involved in cell transformation. These include (from primary to fully malignant cells): a block in cellular differentiation, acquisition of immortality, characterised by unlimited lifespan, an aneuploidy karyotype and a decreased genetic stability; acquisition of tumorigenicity, which is closely associated with the in vitro phenotypes of foci formation, anchorage independent growth in semi-solid agar and autocrine growth factor production; full malignancy, including metastasis when the cells are injected into a suitable host, supporting the biological relevance of in vitro transformation to in vivo carcinogenicity. The assay is based on the change of the phenotypic features of cell colonies undergoing the first steps of the conversion from normal cells to neoplastic-like cells with oncogenic properties","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Carcinogenicity","yearReceived":"2005","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=136","lastUpdate":"Monday, October 12, 2020 - 09:10","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Carcinogenicity","methodology":"In vitro","specificMethodologies":"Cell transformation assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"The SHE 7.0 CTA detects carcinogenic potential via morphological transformation of primary Syrian hamster embryo cells at physiological pH 7.0. Methodology corrected: embryo/developmental model label removed — embryonic cell origin is a material characteristic, not the interrogated mechanism (cell transformation is the methodology). 3R classification changed from Unknown to Reduction — the assay provides screening/weight-of-evidence data that reduces reliance on 2-year rodent bioassays but requires primary animal-derived cells and does not independently replace the in vivo test. All ten bottleneck signals verified as 0: no method-specific bottleneck supported by evidence. The prevalidation was successfully completed, peer-reviewed by ESAC, and recommended by EURL ECVAM. OECD published GD 214 (May 2015) as a guidance document supporting weight-of-evidence use; a formal TG was not adopted due to lack of international consensus on scoring subjectivity and mechanistic understanding. Case study code 0: the complete TSAR record already documents REG_ADOPT; no later exact-method progression outside TSAR. External_evidence_step_stage: REG_ADOPT (from complete TSAR history). Application domain: Mixed/general toxicology (carcinogenicity screening broadly applicable across chemical sectors).","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Reduction","applicationDomainExpert":"Mixed/general toxicology","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2008-05","shortName":"hCLAT","title":"Human Cell Line Activation Test","organisation":"EURL ECVAM - European Union","description":"The h-CLAT supports the discrimination between sensitizing and non-sensitizing chemicals The h-CLAT quantifies in vitro changes in the expression of the CD86 and CD54 membrane phenotypic markers in a human monocytic leukemia cell line (THP-1 cells). THP-1 cells are monocyte-derived cells that have shown to produce DC-like responses following exposure to skin sensitising chemicals (e.g. upregulation of surface markes (e.g. CD86 and CD54) and cytokine production (e.g. TNF-α). The CD86 (a co-stimulatory molecule) and the CD54 (an adhesion molecule) are upregulated in activated Dendritic Cells (DC) and play a critical role in DC presentation of antigens to T cells (T-cell priming). By studying the potential of test chemicals to up-regulate markers of DC activation, the h-CLAT generates information addressing key event 3 (dendritic cell activation) of the skin sensitization Adverse Outcome Pathway.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin sensitisation","yearReceived":"2008","generalComments":"Test Guideline has been adopted as TG442E in July 2016","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=158","lastUpdate":"Wednesday, September 3, 2025 - 09:43","lastUpdateDate":"2025-09-03","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Immunoassay/flow cytometry","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"The h-CLAT measures CD86 and CD54 surface marker upregulation by flow cytometry in human monocytic THP-1 cells after 24-hour chemical exposure, addressing Key Event 3 (dendritic cell activation) of the skin sensitisation AOP. Validated as an in vitro assay providing partial/key-event evidence within IATA and Defined Approaches (OECD GL 36); Three_R_category is Reduction. Application domain covers both original cosmetics driver and broad industrial chemicals (REACH). EURL ECVAM validation (2009-2013), ESAC peer review (2014) and EURL ECVAM recommendation (2015) culminated in regulatory adoption as OECD TG 442E in July 2016. Documented applicability limitations (false negatives for log Kow > 3.5, limited metabolic capacity for pro-haptens, FITC autofluorescence) are managed within the Test Guideline. Because complete TSAR history already captures regulatory adoption (NEW_STEP_STAGE=REG_ADOPT), External_evidence_step_stage=REG_ADOPT and case_study_method=0.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Applicability domain","bottleneckCount":"1","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2016-08","shortName":"ToxCast ER Pathway Model","title":"The ToxCast Estrogen Receptor Agonist Pathway Model","organisation":"ICCVAM/NICEATM - United States","description":"The ToxCast estrogen receptor (ER) pathway model is a mathematical model that combines the results from 18 high-throughput screening (HTS) assays from the ToxCast and Tox21 research programs. The HTS assays measure ER binding, dimerization, chromatin binding, transcriptional activation and ER-dependent cell proliferation. The model uses activity patterns across the in vitro assays to predict whether a chemical is an ER agonist or antagonist, or is otherwise influencing the assays through a manner dependent on the physics and chemistry of the technology platform (“assay interference”). The output of the model provides an area under the curve (AUC) value for the potential of a chemical to cause ER agonism, normalized with respect to the positive control chemical, estradiol.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Reproductive toxicity, Endocrine disruption","yearReceived":"2016","generalComments":"","protocolSop":"","lastUpdate":"Monday, February 15, 2021 - 12:18","lastUpdateDate":"2021-02-15","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"Integrated approach; In vitro; In silico; Mixed","specificMethodologies":"HTS; Reporter gene assay; Binding/interaction assay; Integrated testing strategy/battery","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"No coded bottleneck signal","bottleneckCount":"0","animalUseImpact":"Replacement","applicationDomainExpert":"Industrial chemicals; Environmental","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"},{"id":"TM2016-07","shortName":"EASA","title":"The Electrophilic Allergen Screening Assay for the Detection of Substances Causing Allergic Contact Dermatitis","organisation":"ICCVAM/NICEATM - United States","description":"The EASA consists of 2 simple chemical tests that assess the ability of electrophilic substances to bind to protein by measuring the depletion of free protein surrogates caused by covalent binding of the protein surrogate to the test substance. In the first test, depletion of 4-nitrobenzothiol (NBT), the protein surrogate for soft electrophiles, is measured by the loss of absorbance at 324 nm at 25oC for up to 2 hours. If depletion of NBT ≥ 30%, the test substance is classified as a sensitizer. If depletion of NBT < 30%, confirmation tests must be performed. To confirm the result, the test substance is retested at twice the initial concentration of test substance and/or by increasing the reaction time to 4 hours. If depletion of NBT < 30%, then the second test is performed. In the second test, depletion of pyridoxylamine (PDA), the protein surrogate for hard electrophiles, is measured by the loss of absorbance at 324 nm at 25oC for up to 2 hours. If depletion of PDA ≥ 30%, the test substance is classified as a sensitizer. If depletion of PDA < 30%, confirmation tests, analogous to those with NBT, must be performed. For test substances that interfere with the absorbance of PDA, the loss of PDA is assessed by measuring the decrease in fluorescence at excitation wavelength=324 nm and emission wavelength=398 nm at 25°C for up to 2 hours.","stepStage":"Validation > Planning","workflowStep":"Validation","workflowStage":"Planning","topic":"Skin sensitisation","yearReceived":"2016","generalComments":"","protocolSop":"","lastUpdate":"Monday, February 15, 2021 - 13:03","lastUpdateDate":"2021-02-15","stage":"Validation","status":"Ongoing","code":"VAL_PLAN","applicationDomain":"Mixed/general toxicology","endpoint":"Skin sensitisation","methodology":"In chemico","specificMethodologies":"HTS; Analytical chemistry readout; Binding/interaction assay; Chemical reactivity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"External expert evidence shows completion of the EASA multilaboratory validation, followed by a final NICEATM validation report in 2025 and peer-reviewed validation publication in 2026. This supports External_evidence_step_stage = VAL_FINAL. TSAR source-copy lifecycle/status fields are intentionally left unchanged; any source snapshot refresh should be handled through the source-refresh workflow.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_FINAL","bottlenecks":"Validation readiness / evidence package; Regulatory relevance / integration","bottleneckCount":"2","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2016-06","shortName":"MAT","title":"Monocyte Activation Test","organisation":"BraCVAM - Brazil","description":"MAT is intended to determine pyrogenic contamination of injectable products. The aim of this activity is to demonstrate new appplications of MAT, such as, its use on biological products (hyperimmune sera, vaccines, blood products), medical devices, nanomaterials and Non-Endotoxin Pyrogens (NEPs). Once demonstrated, this test may replace Rabbit Pyrogen Test (RPT) or enter together wit Bacterial Endotoxin Test (BET). In this last case, since BET is negative, it is needed to perform MAT. If BET is positive, then, stop. The assay is based upon the Human mechanism of fever. The products is kept in contact with human blood and the cytokines (IL-1b and/or IL-6) are measured by commercial ELISA,","stepStage":"Regulatory acceptance/Standards > Drafting of new regulatory standard/guideline","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Drafting of new regulatory standard/guideline","topic":"Quality control of vaccines, Airborne pyrogens","yearReceived":"2016","generalComments":"","protocolSop":"","lastUpdate":"Tuesday, March 6, 2018 - 07:57","lastUpdateDate":"2018-03-06","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_DRAFT","applicationDomain":"Pharmaceutical; Medical devices","endpoint":"Vaccine quality control; Pyrogenicity","methodology":"Ex vivo","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay; Integrated testing strategy/battery","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Expert review: Later evidence documents continued MAT validation/application expansion and subsequent European Pharmacopoeia progress. TSAR source-copy lifecycle/status fields are intentionally left unchanged; lifecycle/status updates should be handled through the source-refresh workflow.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"REG_ADOPT","bottlenecks":"Validation readiness / evidence package; Applicability domain; Product / matrix qualification; Regulatory relevance / integration; Standardisation / regulatory adoption","bottleneckCount":"5","animalUseImpact":"Replacement","applicationDomainExpert":"Pharmaceutical / human medicines; Medical devices","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2016-05","shortName":"HET-CAM","title":"Hen’s Egg Test – Chorio-Allantoic Membrane","organisation":"BraCVAM - Brazil","description":"This method is intented to enter a battery of assays to replace rabbits on Eye Irritation Test, as indication of non-irritant substances and a Bottom-Up strategy. Leghorn SPF eggs are used. The test substance is applied to the surface of the CAM. The CAM is evaluated by the appearance of following: congestion (hyperemia), hemorrhage (bleeding), and coagulation (intra- and extravascular). In Brazil, HET-CAM is already accepted by ANVISA as a screening test, but nor for regulatory purposes.","stepStage":"","workflowStep":"","workflowStage":"","topic":"Serious eye damage/Eye irritation","yearReceived":"2016","generalComments":"","protocolSop":"","lastUpdate":"Tuesday, March 6, 2018 - 07:57","lastUpdateDate":"2018-03-06","stage":"Regulatory assessment","status":"Unknown","code":"UNKNOWN_UNKNOWN","applicationDomain":"Mixed/general toxicology","endpoint":"Eye irritation/Serious eye damage","methodology":"In vivo","specificMethodologies":"Embryo/developmental model; In vivo reduction/refinement assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"External expert evidence documents the 2015 BraCVAM prospective validation and later OECD IATA status for HET-CAM. TSAR source-copy lifecycle/status fields are intentionally left unchanged; any lifecycle/status refresh should be handled through the source-refresh workflow.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_PEER_FINAL","bottlenecks":"Validation readiness / evidence package; Predictive performance; Regulatory relevance / integration; Standardisation / regulatory adoption","bottleneckCount":"4","animalUseImpact":"Reduction","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"0","lifecycleVerification":"Original export retained"},{"id":"TM2016-04","shortName":"MCTT HCE™-EIT","title":"A new in vitro eye irritation test with a 3D-reconstructed human cornea epithelium, MCTT HCE™","organisation":"KoCVAM - Republic of Korea","description":"The MCTT HCE™-EIT is a test method identifying eye irritation potential of chemicals using reconstructed human corneal epithelium (RhCE) prepared from primary human corneal cells.","stepStage":"Validation > Ongoing","workflowStep":"Validation","workflowStage":"Ongoing","topic":"Serious eye damage/Eye irritation","yearReceived":"2016","generalComments":"","protocolSop":"","lastUpdate":"Tuesday, March 6, 2018 - 07:57","lastUpdateDate":"2018-03-06","stage":"Validation","status":"Ongoing","code":"VAL_ONGO","applicationDomain":"Mixed/general toxicology","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Expert review (de novo): MCTT HCE™-EIT uses a 3D reconstructed human cornea-like epithelium (RhCE) with WST-1 metabolic viability readout to assess eye irritation. While the TSAR record stopped at submission/early validation (SUB_FINAL / VAL_ONGO), authoritative external evidence documents a multi-laboratory me-too validation study (Lim et al. 2019), an independent OECD validation peer review (OECD Series on Testing and Assessment No. 300, 2019), and formal regulatory adoption into OECD Test Guideline 492 in June 2019. Consequently, case_study_method is updated to 1 (direct case study of progression outside TSAR), External_evidence_step_stage is REG_ADOPT, and the 3R role is Replacement for UN GHS No Category identification.","coreVerification":"Expert-reviewed","caseStudyVerification":"Expert-reviewed","evidenceUpdatedStage":"VAL_ONGO","bottlenecks":"Validation readiness / evidence package; Predictive performance","bottleneckCount":"2","animalUseImpact":"Replacement","applicationDomainExpert":"Cosmetics; Industrial chemicals","lifecycleVerifiedAgainstTSAR":"1","lifecycleVerification":"Verified against live TSAR"}];
